 code+='if(sl){vec2 sz=vec2(2048.,'+SUP.atlas.image.height.toFixed(1)+');vec2 sa=(vec2(mod(si,4.),floor(si/4.))*512.+128.+fract(ss)*256.)/sz;float filtro=si>.5&&si<1.5?1.8:si>1.5&&si<2.5?2.:si>3.5&&si<4.5?1.35:1.;float gm=max(1.,footprint*filtro/16.);sd=texture2DGradEXT(supAtlas,sa,gx*filtro/gm/sz,gy*filtro/gm/sz);}';
