/* CEO 09/11 (Dona Marlene): ambiente coberto (mercadinho, casinha, galpao). TETOS = forro de cada ambiente {x0,x1,z0,z1,h}, h = altura do forro acima do chao.
   Regra: com o corpo de 1,8 m, a cabeca nunca passa do forro. Parkour so sobe se cabe; pulo e apice batem no forro. Em cima do telhado nao vale (alt >= h). */
var TETOS=[{x0:61.3,x1:97.7,z0:56.3,z1:68.7,h:8}],CORPO_ALT=1.8; /* [0] = forro do galpao (mesma caixa do COL roof de genGalpao) */
function tetoOk(ld){ /* escalada para o topo ld.b[4] no ponto ld.x,ld.z */
  var topo=ld.topo===undefined?ld.b[4]:ld.topo;
  for(var i=0;i<TETOS.length;i++){var t=TETOS[i];
    var la=ld.x>t.x0&&ld.x<t.x1&&ld.z>t.z0&&ld.z<t.z1,de=P.x>t.x0&&P.x<t.x1&&P.z>t.z0&&P.z<t.z1;
    if(!la&&!de)continue;
    var h=t.y===undefined?t.h:t.y-groundY(ld.x,ld.z);de=de&&(t.y===undefined?P.alt<t.h:P.y<t.y);
    if(la&&topo<h&&topo+CORPO_ALT>h)return false; /* a cabeca bateria no forro */
    if(de&&topo>=h)return false; /* de dentro do comodo nao atravessa o forro para cima */
  }
  return true;
}
function tetoClamp(){ /* coberto: pulo e apice nunca levam a cabeca acima do forro */
  for(var i=0;i<TETOS.length;i++){var t=TETOS[i];
    if(P.x<=t.x0||P.x>=t.x1||P.z<=t.z0||P.z>=t.z1)continue;
    var h=t.y===undefined?t.h:t.y-groundY(P.x,P.z);if(P.alt>h-CORPO_ALT&&P.alt<h){P.alt=h-CORPO_ALT;if(P.vy>0)P.vy=0;}}
}
function colAltura(b,p){
  if(b.minY===undefined)return true;
  var y=p.y===undefined?0:p.y;
  return y+1.65>b.minY&&y<b.maxY-.04;
}
function colJogador(){return !S.inCar&&pisoEm(P)?COL_SUB:COL;}
function setGalpaoPortao(aberto){
  if(aberto&&!GALPAO.aberto&&S&&S.baileFim&&S.phase==='play'){
    $('fade').classList.add('on');later(TRANSICAO,function(){if(!GP.trans)$('fade').classList.remove('on');});
  }
  GP.portao.ativo=!aberto;GALPAO.aberto=!!aberto;
  GP.folhas.forEach(function(m,i){m.position.x=aberto?(i?2.5:-2.5):0;});
}
function transicaoGalpao(origem,destino,janela){
  if(S.inCar||S.phase!=='play'||GP.trans||Math.hypot(P.x-origem[0],P.z-origem[1])>2.5||Math.abs(P.y-origem[2])>1)return false;
  if(janela&&CB.drawn){say('Guarde a arma para passar pela janela.','sys');return false;}
  GP.trans={t:0,de:[P.x,P.z,P.y],ate:destino,janela:!!janela};pkReset();
  /* CEO 08/11 janela de parkour: sem tela preta, agachamento suave e rapido e barulho de passar pela janela */
  P.vx=P.vz=0;if(janela)smp('botina-sola-1',.16,.95);else $('fade').classList.add('on');return true;
}
