function missaoErros(ficha){
  var erros=[],ids=new Set();
  if(!ficha||!Array.isArray(ficha.passos))return ['passos invalidos'];
  ficha.passos.concat(ficha.alternativos||[]).forEach(function(p){
    if(!p||typeof p.id!=='string'||!p.id){erros.push('passo invalido');return;}
    if(ids.has(p.id))erros.push('passo repetido: '+p.id);ids.add(p.id);
    if(p.verbo!==undefined&&!Object.prototype.hasOwnProperty.call(MECANICAS,p.verbo))erros.push('verbo fora do catalogo: '+p.verbo);
  });
  Object.keys(ficha.zonas||{}).forEach(function(z){
    if(!Array.isArray(ficha.zonas[z])){erros.push('zona invalida: '+z);return;}
    ficha.zonas[z].forEach(function(id){if(!ids.has(id))erros.push('zona '+z+' cita passo inexistente: '+id);});
  });
  return erros;
}
function missaoCampos(campo){
  var tabela={};Object.keys(MISSOES).forEach(function(id){var f=MISSOES[id];
    f.passos.concat(f.alternativos||[]).forEach(function(p){if(Object.prototype.hasOwnProperty.call(p,campo))tabela[p.id]=p[campo];});
  });return tabela;
}
