function moverTransicaoGalpao(dt){
  var t=GP.trans;if(!t)return false;t.t=Math.min(1,t.t+dt/(t.janela?1.1:TRANSICAO*2));var k=sm(t.t);if(t.t>=.5&&!t.janela)$('fade').classList.remove('on');
  if(t.janela){P.dip=Math.sin(Math.PI*t.t)*.24;if(t.t===1){P.dip=0;smp('botina-sola-2',.14,.95);}}
  P.x=lerp(t.de[0],t.ate[0],k);P.z=lerp(t.de[1],t.ate[1],k);P.y=lerp(t.de[2],t.ate[2],k);
  if(t.t===1){var y=t.ate[2];GP.trans=null;P.alt=y<-.3?0:Math.max(0,y-groundY(P.x,P.z));P.clr=P.alt+.05;}
  return true;
}
