function nmModo(){return Math.min(2,Math.max(BAT|0,SMALL?1:0));}/* tela pequena (celular ou janela estreita) usa no maximo a linha do PS2; SMALL ja existe, sem desvio novo de celular */
function nmDiaOk(v){return typeof v==='number'&&v>=0&&v<1e6&&v===Math.floor(v)?v:0;}/* save antigo sem o campo ou valor invalido = dia 0 */
function nmDia(){return S?nmDiaOk(S.nmDia):0;}
function nmClima(d){var r=mulberry32(NM_SEMENTE*7919+d*104729)(),a=0;for(var i=0;i<CLIMA.length;i++){a+=CLIMA[i].peso;if(r<a)return CLIMA[i];}return CLIMA[CLIMA.length-1];}
/* cache: so sorteia de novo na virada do dia (ou quando o teste forca o clima) */
function nmClimaAgora(){var d=nmDia(),f=S&&S.marlene&&S.marlene.active?CLIMA_CENA.escolta:NM.forca||null;if(d!==NM.cd||f!==NM.cf||!NM.cc){NM.cd=d;NM.cf=f;NM.sorteio++;NM.cc=null;
  if(f)for(var i=0;i<CLIMA.length;i++)if(CLIMA[i].id===f)NM.cc=CLIMA[i];if(!NM.cc)NM.cc=nmClima(d);}return NM.cc;}
/* janela acesa: posicao em mundo pelo mesmo transform do Batch (quadV), sem sortear nada (a sequencia de R() da casa nao muda) */
function nmFonte(B,lx,y,lz,c){NM.fontes.push([lx*B.tc+lz*B.ts+B.tx,y,-lx*B.ts+lz*B.tc+B.tz,c.r*.45,c.g*.45,c.b*.45]);}
function nmChaoRua(x,z){return roadAt(x,z)>=0||pertoRua(x,z);}
function nmSob(x,y,z){for(var i=0;i<TETOS.length;i++){var t=TETOS[i];if(x>t.x0&&x<t.x1&&z>t.z0&&z<t.z1&&y<GY+t.h)return true;}return false;}
/* coberto: camera sob forro; a pe, piso de interior ou corpo sob forro; de carro, a viatura sob forro (galpao) */
function nmInterior(){var c=camera.position;if(nmSob(c.x,c.y,c.z))return true;
  if(S.inCar)return !!CAR&&nmSob(CAR.position.x,CAR.position.y,CAR.position.z);return !!pisoEm(P)||nmSob(P.x,P.y,P.z);}
