  L=NM_U.L.value[9];if(gi>0){CAR.localToWorld(_nmV.set(0,2.25,-.1));var g=u.gLight.color;L.set(_nmV.x,_nmV.y,_nmV.z,.3);NM_U.LC.value[9].set(g.r*gi*8,g.g*gi*8,g.b*gi*8);}else L.w=0;
