  if((tipo==='bush'?naRua(x,z):pertoRua(x,z))||((Math.abs(x)>=111||Math.abs(z)>=78)&&soloGrama(x,z)<.6))return false;var ry=R()*6.283,modelo=(R()*VEGMOD[tipo].length)|0;
