/* floresta densa onde era o muro (CEO 05/11): faixa entre o limite do jogador e a mata distante (buildMata) */
function buildForest(){
  var rnd=mulberry32(512),N=1100,n=0,tries=0,EX=BOUND_X+16,EZ=BOUND_Z+16;
  while(n<N&&tries<N*12){
    tries++;
    var x=-EX+rnd()*EX*2,z=-EZ+rnd()*EZ*2;
    if(Math.abs(x)<111&&Math.abs(z)<78)continue; /* cidade */
    if(Math.abs(x)<GX+5&&z>70)continue; /* rodovia sul */
    if(Math.abs(x)<7&&z<-100)continue; /* estrada norte */
    if(Math.abs(x)<14&&z<-78||Math.abs(x)<43&&z<PG_PLACA_Z+12&&z>MP_NORTH_Z)continue; /* patio do MP e muralha livres: o forte e o morro aparecem */
    if(Math.abs(z-HWY_Z)<HWY_W/2+3&&Math.abs(x)<BOUND_X+2)continue; /* rodovia */
    if(Math.abs(x-CABANA.x-1)<7&&z>CABANA.z-4&&z<CABANA.z+13)continue; /* clareira da cabana */
    if(noMar(x,z)||inCol(x,z,1.2)||soloGrama(x,z)<.6)continue; /* so na grama */
    var borda=Math.min(BOUND_X-Math.abs(x),BOUND_Z-Math.abs(z)); /* <0 = alem do limite */
    if(borda>6&&rnd()>.35)continue; /* miolo aberto e ralo; a mata fecha na borda e vira a parede */
    var u=rnd(),tipo=borda<4?(u<.55?'tree':u<.7?'palm':'bush'):(u<.6?'tree':u<.8?'palm':'bush'),s=tipo==='bush'?1+rnd()*.9:.85+rnd()*.8;
    if(!plantar(tipo,x,groundY(x,z),z,s,false))continue;n++;
    if(tipo!=='bush'&&borda>-2)COL.push([x-.3,z-.3,x+.3,z+.3,VEGH[tipo]*s]);
  }
}
