// As latas vêm do mesmo GLB e do mesmo material que o salão já carregou.
function coberturaLatas(pecas){
  if(!scene.getObjectByName('laje-equipamento')||scene.getObjectByName('laje-latas-pol'))return;
  const st=BAILE.stage,y=st[1]-1+8.85+.008;
  for(const [id,poses] of [['pol',[[2.95,-3.67,.6,0],[2.65,1.84,1.2,1]]],['trama',[[2.43,3.28,-.9,1],[2.85,3.57,-.32,0]]]]){
    const src=pecas['lata_'+id],geo=src.geometry.clone(),m=new THREE.InstancedMesh(geo,src.material,poses.length);
    const all=new THREE.Box3(),box=new THREE.Box3();geo.computeBoundingBox();
    poses.forEach(([x,z,a,deitada],i)=>{
      const t=new THREE.Matrix4().makeRotationFromEuler(new THREE.Euler(0,a,deitada*Math.PI/2,'YXZ'));
      box.copy(geo.boundingBox).applyMatrix4(t);t.setPosition(st[0]+x,y-box.min.y,st[2]+z);m.setMatrixAt(i,t);all.union(box.copy(geo.boundingBox).applyMatrix4(t));
    });
    geo.boundingSphere=all.getBoundingSphere(new THREE.Sphere());m.name='laje-latas-'+id;scene.add(m);
  }
}

