    for(var j=0;j<p.count;j++)if(n.getY(j)>.3){var u=p.getX(j)/.3,v=(p.getZ(j)+.02)/.15,b=Math.max(0,1-u*u)*Math.max(0,1-v*v);p.setY(j,p.getY(j)-.011*b*b);}/* leve afundado no meio */
