  g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));g.computeBoundingSphere();g.computeBoundingBox();
  var t=sofaTextura(),m=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,map:t,bumpMap:t,bumpScale:.0015,roughness:.96,metalness:0}));
  m.name='sofa-professor';m.castShadow=m.receiveShadow=false;grupo.add(m);SOFA_M=m;g.userData.contagens=contagens;sofaNivel(BAT);
  var cv=document.createElement('canvas');cv.width=64;cv.height=32;var x=cv.getContext('2d'),gr=x.createRadialGradient(32,16,2,32,16,32);/* sombra de contato macia */
  gr.addColorStop(0,'rgba(0,0,0,.62)');gr.addColorStop(.7,'rgba(0,0,0,.4)');gr.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=gr;x.fillRect(0,0,64,32);
  var sm=new THREE.Mesh(new THREE.PlaneGeometry(2.9,1.05),new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(cv),transparent:true,depthWrite:false}));
  sm.rotation.x=-Math.PI/2;sm.position.set(O[0]-.7,O[1]+.006,O[2]+.47);sm.name='sofa-sombra';sm.castShadow=sm.receiveShadow=false;grupo.add(sm);
