    if(lod!==-2)sh.fragmentShader='uniform float vfFar;varying float vfD;\n'+(lod===3?'varying float vfL;\n':'')+sh.fragmentShader.replace('#include <clipping_planes_fragment>',
      '#include <clipping_planes_fragment>\nfloat vfNoise=fract(52.9829189*fract(dot(floor(gl_FragCoord.xy),vec2(.06711056,.00583715))));\n'+
      (lod===3?'if(vfL<.5){if(vfNoise<smoothstep(10.,22.,vfD))discard;}else if(vfL<1.5){if(vfNoise>=smoothstep(10.,22.,vfD)||vfNoise<smoothstep(94.,118.,vfD))discard;}else{if(vfNoise>=smoothstep(94.,118.,vfD))discard;}\n':'')+
      'if(fract(vfNoise+.5)<smoothstep(vfFar-32.,vfFar,vfD))discard;');
