/*ARV-LUGAR-INI*/
/* ONDE nasce arvore (regras 1, 5, 6): pesos de vegBioma(x,z) {a: arvore solta, f: floresta} quando existir; senao soloGrama (mata na borda e rala no miolo, como buildForest). Semente fixa, nada de Math.random. */
function arvPeso(x,z){
  if(typeof vegBioma==='function'){var w=vegBioma(x,z);return{a:w.a||0,f:w.f||0};}
  var s=soloGrama(x,z);if(s<.6)return{a:0,f:0};
  return{a:.5,f:Math.min(BOUND_X-Math.abs(x),BOUND_Z-Math.abs(z))<4?1:.18};
}
/* nunca em rua, acostamento, calcada, predio, patio do MP, pedagio, cabana, favela, rodovia, mar, linha de visao da rua de impressao nem vaga de viatura */
function arvProibido(x,z){
  if(naRua(x,z)||pertoRua(x,z)||roadAt(x,z)>=0||noMar(x,z)||dentroGalpao(x,z,3)||outdoorSightline(x,z)||inCol(x,z,1.5))return true;
  if(Math.abs(x)<111&&Math.abs(z)<78)return true; /* cidade: so as arvores que ja eram plantadas la */
  if(Math.abs(x)<GX+5&&z>70)return true; /* rodovia sul */
  if(Math.abs(x)<9&&z<-100)return true; /* estrada norte */
  if(Math.abs(x)<16&&z<-78||Math.abs(x)<45&&z<PG_PLACA_Z+14&&z>MP_NORTH_Z)return true; /* patio do MP, pedagio, posto e muralha */
  if(Math.abs(z-HWY_Z)<HWY_W/2+4&&Math.abs(x)<BOUND_X+2)return true; /* rodovia leste-oeste */
  if(Math.abs(x-CABANA.x-1)<8&&z>CABANA.z-5&&z<CABANA.z+14)return true; /* clareira da cabana */
  if(z>-215&&z<-112&&x>-150&&x<95)return true; /* favela */
  var vg=cenaVagas(),i;for(i=0;i<vg.length;i++)if(Math.abs(vg[i].x-x)<4&&Math.abs(vg[i].z-z)<4)return true; /* vaga de viatura */
  return false;
}
/* conv = arvores que o jogo ja plantava (cidade, quintais): entram primeiro e ocupam o lugar. Devolve [{x,z,s,yaw,e,v,c}] (c=1 convertida) */
function arvLugares(conv){
  var R=[],G={},bx,bz,t,x,z,w,pf,e,u,v,s,d,dens,q,r2,u1,u2,u3,u4,u5;
  function perto(x,z,r){var gx=Math.floor(x/6),gz=Math.floor(z/6),a,b,l,k;for(a=gx-2;a<=gx+2;a++)for(b=gz-2;b<=gz+2;b++){l=G[a+','+b];if(l)for(k=0;k<l.length;k++)if((l[k].x-x)*(l[k].x-x)+(l[k].z-z)*(l[k].z-z)<r*r)return true;}return false;}
  function poe(q){R.push(q);var k=Math.floor(q.x/6)+','+Math.floor(q.z/6);(G[k]=G[k]||[]).push(q);}
  conv.forEach(poe);
  [[-21,-104,1,.86],[-30,-134,3,.94],[25,-146,1,.91],[-18,-158,1,.89],[-32,-183,2,1.05],[33,-190,1,.93],[22,-205,3,.82]].forEach(function(p,i){if(inCol(p[0],p[1],1.4)||bairroPiso(p[0],p[1])>=0||perto(p[0],p[1],5))return;poe({x:p[0],z:p[1],e:p[2],s:p[3],v:i%2,yaw:i*2.41,c:0});});
  for(bx=-12;bx<12;bx++)for(bz=-12;bz<12;bz++){r2=mulberry32(9100+(bx+12)*61+(bz+12)*7919);
    for(t=0;t<170;t++){u1=r2();u2=r2();u3=r2();u4=r2();u5=r2();if(R.length>=ARV.MAX)break;
      x=(bx+u1)*32;z=(bz+u2)*32;if(Math.abs(x)<111&&Math.abs(z)<78)continue;
      w=arvPeso(x,z);d=Math.max(Math.abs(x)-BOUND_X,Math.abs(z)-BOUND_Z);dens=1-.5*Math.min(1,Math.max(0,d)/200);
      pf=Math.min(1,w.f*1.7+w.a*.025)*dens;if(u3>=pf)continue;
      if(perto(x,z,3.2+(1-Math.min(1,w.f))*6)||arvProibido(x,z))continue;
      u=u4;e=w.f>=w.a?(u<.3?1:u<.55?2:u<.65?0:u<.75?3:4):(u<.28?0:u<.58?1:u<.75?2:u<.92?3:4);
      s=.85+((u5*977)%1)*.55;v=((u5*1000)|0)%2;
      poe({x:x,z:z,s:s,yaw:u1*977%1*6.2832,e:e,v:v,c:0});}}
  return R;
}
