  g.fillStyle=e===3?'#8fa84a':'#d9cf62';g.fillRect(226,8,20,20);g.fillStyle='#6a2a5c';g.fillRect(226,34,20,20);g.fillStyle='#98a63c';g.fillRect(226,60,20,20);
