function buildMata(){
  var N=1100,rnd=mulberry32(7),geo=canopyGeo(8,3),/* CEO 08/11 perf: mata de fundo com copa de 8 segmentos (era 14: 1,4 mi tris) */tg=new THREE.CylinderGeometry(.1,.2,1,8);
  var cm=new THREE.InstancedMesh(geo,new THREE.MeshStandardMaterial({roughness:.95,vertexColors:true}),N),tm=new THREE.InstancedMesh(tg,new THREE.MeshStandardMaterial({color:C(0x4a3626),roughness:1}),N);
  var m4=new THREE.Matrix4(),q=new THREE.Quaternion(),e=new THREE.Euler(),v=new THREE.Vector3(),sc=new THREE.Vector3(),c=new THREE.Color(),n=0,tries=0;
  while(n<N&&tries<N*8){
    tries++;
    var road=rnd()<.18,x=road?(rnd()<.5?-1:1)*(9+rnd()*28):-380+rnd()*760,z=road?88+rnd()*200:-380+rnd()*760; /* alem de 380 m a pintura assume */
    if(road&&z<BOUND_Z+6)continue;
    if(!road&&Math.abs(x)<BOUND_X+6&&Math.abs(z)<BOUND_Z+6)continue; /* fora da area jogavel: la a mata real (buildForest) tem colisao */
    if(Math.abs(x)<8&&z>80)continue; /* asfalto da estrada sul */
    if(Math.abs(x)<43&&z<PG_PLACA_Z+12&&z>MP_NORTH_Z||Math.abs(x)<8&&z<-100)continue; /* estrada norte rumo ao morro */
    if(z>-215&&z<-112&&x>-150&&x<95)continue; /* favela */
    if(noMar(x,z)||soloGrama(x,z)<.6)continue;
    var y=terrainH(x,z),s=road?1.6+rnd()*1.2:2.6+rnd()*3.4;
    e.set(0,rnd()*6,0);q.setFromEuler(e);
    sc.set(s,s*(1.1+rnd()*.6),s);v.set(x,y+s*1.6,z);m4.compose(v,q,sc);cm.setMatrixAt(n,m4);
    c.setHex(GRN[Math.floor(rnd()*GRN.length)]).multiplyScalar(.36+rnd()*.22);cm.setColorAt(n,c);
    sc.set(s*.6,s*1.6,s*.6);v.set(x,y+s*.8,z);m4.compose(v,q,sc);tm.setMatrixAt(n,m4);
    n++;
  }
  tm.userData.troncos=true;cm.userData.arvT=tm.userData.arvT='mata';cm.count=tm.count=n;cm.instanceColor.needsUpdate=true;cm.frustumCulled=tm.frustumCulled=false;scene.add(cm);scene.add(tm);vegCullAdd(cm);vegCullAdd(tm);
}
function buildFavela(){
  var B=KG.B,E=KG.E,n=0,tries=0;
  while(tries<4000){
    tries++;
    var x=rr(-150,95),z=rr(-215,-112),h0=terrainH(x,z);
    if(h0<7)continue;
    var w=rr(3,5.5),d=rr(3,5),h=rr(2.6,4.6),y=Math.min(h0,terrainH(x-w/2,z),terrainH(x+w/2,z),terrainH(x,z+d/2),terrainH(x,z-d/2))-.4;
    tf(KG,x,z,0);
    B.add(BOX,0,y,0,w,h+.6,d,0,pc(BAIRRO_TEMA.comu),.35,.08);
    B.add(BOX,0,y+h+.5,0,w+.3,.25,d+.3,0,C(pick(BAIRRO_TEMA.telhado)),0,0);
    if(R()<.55)E.quadV(rr(-w/3,w/3),y+h*.55,d/2+.04,.8,.8,0,pick(LITS));
    if(R()<.12)E.add(BOX,w/2,y+h+.75,d/2,.18,.18,.18,0,new THREE.Color(.4,.6,3),0,0);
    n++;
  }
  tf(KG,0,0,0);
}
