/*ENTRADA-BR:ini*/
/* ENTRADA-BR 19/11 (worker visual rodovia). Cruzamento sul x BR sem briga de profundidade, cunha de curva irregular,
   asfalto/tinta gastos, defensa com variacao pequena (postes intactos) e margens naturais. Visual puro: sem COL, sem transito.
   Constantes e funcoes ebr* sao geometria pura (sem THREE/DOM): o teste roda em node. */
var EBR={R:5,xe:4.9,y:.015,xMin:14,xMax:136,dzMin:6.6,dzN:17.5,dzS:16,dzT:1.0,proib:[]};
EBR.proib=STREAM_OUTDOOR_X.map(function(x){return [x-8,x+8,HWY_Z+8,HWY_Z+19];}).concat([[OUTDOOR.x-7,OUTDOOR.x+7.5,OUTDOOR.z-5,OUTDOOR.z+5]]);
/* raio relativo da curva de ligacao: 1 nas duas pontas com derivada zero (tangente da estrada e da BR preservada), irregular no meio */
function ebrRaio(t){var s=Math.sin(2*t);return 1+s*s*(.10*Math.sin(3.3*t+1.2)+.03*Math.sin(5.3*t));}
/* (u,v): u = afastamento lateral da borda da estrada, v = afastamento da borda da BR; (0,R) -> (R,0) */
function ebrArco(R,n){var p=[],i,t,r;for(i=0;i<=n;i++){t=Math.PI/2*i/n;r=R*ebrRaio(t);p.push([R-r*Math.cos(t),R-r*Math.sin(t)]);}return p;}
function ebrOnda(t,sem){return .5*Math.sin(t*.9+sem)+.3*Math.sin(t*2.7+sem*2.3)+.2*Math.sin(t*7.1+sem*5.1);}
function ebrR(k,sem){var s=Math.sin(k*127.1+sem*311.7)*43758.5453;return s-Math.floor(s);}
/* banda das margens: fora do acostamento/defensa (dzMin), fora do vao da estrada sul (xMin), fora de outdoors, antes do muro da cidade (dzN) */
function ebrMargemOk(x,z,m){m=m||0;var ax=Math.abs(x),dz=z-HWY_Z;
  if(ax<EBR.xMin+m||ax>EBR.xMax-m)return false;
  if(Math.abs(dz)<EBR.dzMin+m||Math.abs(dz)>(dz>0?EBR.dzS:EBR.dzN)-m)return false;
  return !EBR.proib.some(function(r){return x>r[0]-m&&x<r[1]+m&&z>r[2]-m&&z<r[3]+m;});}
/* grupos: centros de grupo + vizinhas em disco; filtro(x,z) e a checagem dinamica (COL, ruas) */
function ebrPontos(sem,nGr,minM,filtro){var r=mulberry32(sem),out=[],g,k,m,cx,cz,sg,a,d,x,z,t;
  for(g=0;g<nGr;g++){
    for(t=0;t<60;t++){sg=r()<.5?-1:1;cx=(r()<.5?-1:1)*(EBR.xMin+r()*(EBR.xMax-EBR.xMin));cz=HWY_Z+sg*(EBR.dzMin+r()*((sg>0?EBR.dzS:EBR.dzN)-EBR.dzMin));
      if(ebrMargemOk(cx,cz,minM+1.5)&&(!filtro||filtro(cx,cz)))break;}
    if(t>=60)continue;
    m=4+Math.floor(r()*7);
    for(k=0;k<m;k++){a=r()*6.283;d=Math.sqrt(r())*1.9;x=cx+Math.cos(a)*d;z=cz+Math.sin(a)*d;
      if(ebrMargemOk(x,z,minM)&&(!filtro||filtro(x,z)))out.push([x,z,1+.9*r(),r()*6.283]);}
  }
  return out;}
/* defensa com variacao: paineis de 4 m, cada um com desnivel/lateral minimos e raro amassado; os postes (a cada 4 m) nao mexem.
   dy<=1,2 cm e deslocamento lateral <=2,2 cm (amassado so para o lado do poste). Mesma pele e mesmo perfil do defensaGeo. */
function defensaVar(len,eixo,lado,sem){
  var k='v'+len.toFixed(2)+eixo+lado+sem;if(DEFENSA.cache[k])return DEFENSA.cache[k];
  var pf=DEFENSA.perfil,n=pf.length,acc=[0],i,j,p,r,pos=[],uv=[],idx=[],np=Math.max(1,Math.round(len/4)),T0=-len/2;
  for(i=1;i<n;i++)acc.push(acc[i-1]+Math.hypot(pf[i][0]-pf[i-1][0],pf[i][1]-pf[i-1][1]));
  for(p=0;p<np;p++){
    var a=T0+len*p/np,b=T0+len*(p+1)/np,dyP=.008*(2*ebrR(p,sem)-1),dlP=.006*(2*ebrR(p+97,sem)-1),dent=ebrR(p+211,sem)<.07?.012:0;
    for(r=0;r<3;r++){
      var t=a+(b-a)*r/2,u=r/2,dy=dyP+.004*ebrOnda(t,sem),dl=dlP+.003*ebrOnda(t*1.3+5,sem)-lado*dent*Math.exp(-Math.pow((u-.5)/.28,2));
      for(j=0;j<n;j++){var lat=pf[j][0]*lado+dl,y=pf[j][1]+dy;if(eixo==='x')pos.push(t,y,lat);else pos.push(lat,y,t);uv.push((t-T0)/4,acc[j]);}
    }
    for(r=0;r<2;r++)for(j=0;j<n-1;j++){var q=(p*3+r)*n+j;idx.push(q,q+n,q+1,q+1,q+n,q+n+1);}
  }
  var g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
  g.setIndex(idx);g.computeVertexNormals();g.userData.defensa=true;g.userData.perfil=n;return (DEFENSA.cache[k]=g);}
/* GLSL de ruido de chao, compartilhado pelo asfalto gasto e pela faixa de grama */
function ebrGLSL(){return 'float ebH(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n'+
  'float ebN(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(ebH(i),ebH(i+vec2(1.,0.)),f.x),mix(ebH(i+vec2(0.,1.)),ebH(i+vec2(1.,1.)),f.x),f.y);}\n';}
/* A rua termina nas duas bordas da BR. A curva pertence à própria malha e usa o mesmo asfalto. */
function ebrRuaGeo(){
 var pos=[],uv=[],idx=[],w=(RW+2.4)/2,pts=ebrArco(EBR.R,28);
 [-1,1].forEach(function(sg){
  var primeira=pos.length/3;if(sg>0)PRAIA.bocaVia=[];
  function linha(z,extra){if(sg>0&&z<164)PRAIA.bocaVia.push([z,w+extra]);for(var sx=-1;sx<=1;sx+=2){pos.push(sx*(w+extra),122-z,0);uv.push((sx+1)/2,(164-z)/84);}
   var k=pos.length/3-2;if(k>primeira){if(sg>0)idx.push(k-2,k,k-1,k,k+1,k-1);else idx.push(k-2,k-1,k,k,k-1,k+1);}}
  var lado=HWY_Z+sg*HWY_W/2;
  for(var i=pts.length-1;i>=0;i--)linha(lado+sg*pts[i][1],pts[i][0]*(HWY_GAP-w)/EBR.R);
  linha(sg>0?164:80,0);
 });
 var g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();return g;
}
/* faixa de grama (foto de grama que o jogo ja carrega: RUA_TEX.grama) nas duas margens, com borda irregular; so chao, 1 mesh */
function entradaBRGrama(){
  var pos=[],uv=[],aD=[],aW=[],idx=[],vi=0,NX=34,NZ=5;
  [-1,1].forEach(function(sg){[-1,1].forEach(function(sx){
    var W=(sg>0?EBR.dzS:EBR.dzN)-EBR.dzMin+.6,x0=EBR.xMin-2,x1=EBR.xMax+2,i,j;
    var q={x0:x0,z0:EBR.dzMin-.6,ix:NX/(x1-x0),iz:NZ/(W+.6),nx:NX+1,nz:NZ+1,g:new Float32Array((NX+1)*(NZ+1))};
    MARGENS_BR[(sg>0?2:0)+(sx>0?1:0)]=q;
    for(j=0;j<=NZ;j++)for(i=0;i<=NX;i++){var x=sx*(x0+(x1-x0)*i/NX),d=-.6+(W+.6)*j/NZ,z=HWY_Z+sg*(EBR.dzMin+d);
      var borda=sm((d-.9)/3)*sm((W-4.3-d)/3.2)*sm((Math.abs(x)-EBR.xMin-2)/5)*sm((EBR.xMax-7-Math.abs(x))/5);
      EBR.proib.forEach(function(r){borda*=sm((Math.max(r[0]-x,x-r[1],r[2]-z,z-r[3])-1)/4);});
      var h=borda*(.18+.105*Math.sin(x*.23+z*.36)+.057*Math.cos(x*.47-z*.26));
      pos.push(x,q.g[j*q.nx+i]=h,z);uv.push(x/7,z/7);aD.push(d);aW.push(W);}
    for(j=0;j<NZ;j++)for(i=0;i<NX;i++){var a=vi+j*(NX+1)+i,b=a+1,c=a+NX+1,e=c+1;
      if((sx*sg)>0)idx.push(a,c,b,b,c,e);else idx.push(a,b,c,b,e,c);}
    vi+=(NX+1)*(NZ+1);
  });});
  var geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
  geo.setAttribute('aD',new THREE.Float32BufferAttribute(aD,1));geo.setAttribute('aW',new THREE.Float32BufferAttribute(aW,1));geo.setIndex(idx);geo.computeVertexNormals();geo.computeBoundingSphere();
  var mat=new THREE.MeshStandardMaterial({map:RUA_TEX.grama,transparent:true,depthWrite:false,roughness:1,metalness:0,envMapIntensity:.35,polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-2});
  mat.onBeforeCompile=function(sh){
    sh.vertexShader='attribute float aD;attribute float aW;varying float vD;varying float vW;varying vec2 vEw;\n'+sh.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvD=aD;vW=aW;vEw=(modelMatrix*vec4(position,1.)).xz;');
    sh.fragmentShader='varying float vD;varying float vW;varying vec2 vEw;\n'+ebrGLSL()+sh.fragmentShader.replace('#include <map_fragment>','#include <map_fragment>\n'+
      'float en=ebN(vEw*.35)*.6+ebN(vEw*1.7)*.4;\n'+
      /* verde natural a partir da foto: puxa o canal verde, segura o marrom, deixa manchas mais secas e mais viçosas */
      'float lu=dot(diffuseColor.rgb,vec3(.3,.59,.11));vec3 vd=mix(diffuseColor.rgb*vec3(.8,1.12,.62),vec3(lu)*vec3(.62,1.,.36)*1.12,.5);\n'+
      'diffuseColor.rgb=vd*mix(vec3(.72,.8,.6),vec3(1.12,1.1,.88),en);\n'+
      'float ent=smoothstep(0.,.9,vD+(en-.5)*1.4)*(1.-smoothstep(vW-7.,vW,vD+(en-.5)*5.));\n'+
      'ent*=smoothstep('+(EBR.xMin).toFixed(1)+','+(EBR.xMin+5).toFixed(1)+',abs(vEw.x))*(1.-smoothstep('+(EBR.xMax-10).toFixed(1)+','+EBR.xMax.toFixed(1)+',abs(vEw.x)));\n'+
      'diffuseColor.a*=ent;');};
  mat.customProgramCacheKey=function(){return 'entradaBRgrama';};
  var m=new THREE.Mesh(geo,mat);m.receiveShadow=true;m.renderOrder=-1;m.name='entradaBRgrama';scene.add(m);return m;}
