function pistaNorteGeo(meia,NS,NE,altura){
 var pos=[],uv=[],q=SOLO_REAL,p=q.pos,ix=q.idx;
 function corta(poly,axis,lim,sd){var out=[];for(var i=0;i<poly.length;i++){var a=poly[i],b=poly[(i+1)%poly.length],da=(a[axis]-lim)*sd,db=(b[axis]-lim)*sd;if(da>=-1e-8)out.push(a);if((da>0&&db<0)||(da<0&&db>0)){var t=da/(da-db);out.push(a.map(function(v,k){return v+(b[k]-v)*t;}));}}return out;}
 for(var i=0;i<ix.length;i+=3){var a=ix[i]*3,b=ix[i+1]*3,c=ix[i+2]*3;
  if(Math.max(p[a],p[b],p[c])< -meia||Math.min(p[a],p[b],p[c])>meia||Math.max(p[a+2],p[b+2],p[c+2])<NE||Math.min(p[a+2],p[b+2],p[c+2])>NS)continue;
  var poly=[a,b,c].map(function(j){return [p[j],p[j+1],p[j+2]];});
  [[0,-meia,1],[0,meia,-1],[2,NE,1],[2,NS,-1]].forEach(function(c){if(poly.length)poly=corta(poly,c[0],c[1],c[2]);});
  for(var j=1;j<poly.length-1;j++){var tri=[poly[0],poly[j],poly[j+1]],a=tri[0],b=tri[1],c=tri[2];if(Math.abs((b[0]-a[0])*(c[2]-a[2])-(b[2]-a[2])*(c[0]-a[0]))<1e-9)continue;
   tri.forEach(function(v){pos.push(v[0],Math.max(0,v[1])+altura,v[2]);uv.push((NS-v[2])/(NS-NE),(.5-v[0]/(meia*2)));});}
 }
 var g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.computeVertexNormals();g.computeBoundingBox();g.computeBoundingSphere();return g;
}
