// q=[cx,cy,cz,w,h,ry,ru,rv,deitado]; cy e o centro; ru/rv repetem a textura.
function texQuads(G,file,cor,qs){
  var p=[],n=[],uv=[];
  qs.forEach(function(q){
    var c=Math.cos(q[5]),s=Math.sin(q[5]),hw=q[3]/2,hh=q[4]/2,ru=q[6]||1,rv=q[7]||1;
    [[-1,-1,0,0],[1,-1,ru,0],[1,1,ru,rv],[-1,-1,0,0],[1,1,ru,rv],[-1,1,0,rv]].forEach(function(v){
      var lx=v[0]*hw,ly=v[1]*hh;
      if(q[8]){p.push(q[0]+lx,q[1],q[2]-ly);n.push(0,1,0);}
      else{p.push(q[0]+lx*c,q[1]+ly,q[2]-lx*s);n.push(s,0,c);}
      uv.push(v[2],v[3]);
    });
  });
  var g=new THREE.BufferGeometry();
  g.setAttribute('position',new THREE.Float32BufferAttribute(p,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(n,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
  var m=new THREE.MeshLambertMaterial({color:cor});
  if(qs.some(function(q){return q[8];})){m.polygonOffset=true;m.polygonOffsetFactor=-2;m.polygonOffsetUnits=-4;} /* CEO 09/11 piso piscando: lajota deitada ganha do forro de terra/quadra no mesmo y (z-fighting) */
  if(file)new THREE.TextureLoader().load(file,function(t){t.encoding=THREE.sRGBEncoding;t.anisotropy=4;t.wrapS=t.wrapT=THREE.RepeatWrapping;m.map=t;m.alphaTest=.5;m.color.set(0xffffff);m.needsUpdate=true;},undefined,function(){});
  var me=new THREE.Mesh(g,m);me.receiveShadow=true;G.add(me);return me;
}
