    vidro.name='expositor-vidro-'+id;vidro.position.set(x,y+(h+baixo-cima)/2,fr-.008);G.add(vidro);
    var px=x+(id?-1:1)*(w/2-.026);chapa(px,.78,fr+.017,.025,.027,.063,cor);chapa(px,1.05,fr+.017,.025,.027,.063,cor);chapa(px,.78,fr+.052,.024,.297,.023,0x6a7171);
