/* ===== BK: geometria baked (vertex color, facetada) ===== */
function hh(a,b,c){var s=Math.sin(a*127.1+b*311.7+c*74.7)*43758.5453;return s-Math.floor(s);}
function JG(geo,amt,seed){
  var p=geo.attributes.position,mp={},i,k,o;seed=seed||0;
  for(i=0;i<p.count;i++){
    var x=p.getX(i),y=p.getY(i),z=p.getZ(i);k=Math.round(x*500)+'_'+Math.round(y*500)+'_'+Math.round(z*500);
    o=mp[k];if(!o)o=mp[k]=[(hh(x,y,z+seed)-.5)*amt,(hh(y,z,x+seed)-.5)*amt,(hh(z,x,y+seed)-.5)*amt];
    p.setXYZ(i,x+o[0],y+o[1],z+o[2]);
  }
  return geo;
}
function BK(){this.p=[];this.c=[];this.m=new THREE.Matrix4();this.q=new THREE.Quaternion();this.e=new THREE.Euler();this.v=new THREE.Vector3();this.s=new THREE.Vector3();}
BK.prototype.add=function(geo,hex,x,y,z,sx,sy,sz,rx,ry,rz,shade,vary){
  var g=geo.index?geo.toNonIndexed():geo,p=g.attributes.position,col=C(hex),m=this.m;
  this.e.set(rx||0,ry||0,rz||0,'YXZ');this.q.setFromEuler(this.e);this.v.set(x,y,z);this.s.set(sx==null?1:sx,sy==null?1:sy,sz==null?1:sz);
  m.compose(this.v,this.q,this.s);shade=shade==null?1:shade;vary=vary==null?.1:vary;
  var a=new THREE.Vector3(),i,f;
  for(i=0;i<p.count;i++){
    a.set(p.getX(i),p.getY(i),p.getZ(i)).applyMatrix4(m);this.p.push(a.x,a.y,a.z);
    if(i%3===0){f=shade*(1-vary/2+vary*hh(a.x*3,a.y*3,a.z*3));}
    this.c.push(col.r*f,col.g*f,col.b*f);
  }
  if(g!==geo)g.dispose();
};
BK.prototype.mesh=function(mat,cast){
  var g=new THREE.BufferGeometry();
  g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(this.p),3));
  g.setAttribute('color',new THREE.BufferAttribute(new Float32Array(this.c),3));
  g.computeVertexNormals();g.computeBoundingSphere();
  var o=new THREE.Mesh(g,mat);o.castShadow=cast!==false;return o;
};
var VMAT=new THREE.MeshStandardMaterial({vertexColors:true,roughness:.78,metalness:.02,envMapIntensity:.45});
var VMATM=new THREE.MeshStandardMaterial({vertexColors:true,roughness:.3,metalness:.7,envMapIntensity:1.3});
