 D.cab+=((olha?-.18:.3)-D.cab)*k;D.gir+=((olha?alvo:.15*Math.sin(T*.2))-D.gir)*k;D.rabo=olha&&dd<3.5?.35*Math.sin(T*6):.06*Math.sin(T*.8);
