 var Ct=VMB.cat,cdx=hx-Ct.hx,cdz=hz-Ct.hz,cd=Math.sqrt(cdx*cdx+cdz*cdz);Ct.t+=dt;var pa=0,cc=0,cg=0,rb=.25*Math.sin(T*1.3);
 if(Ct.st===0){if(ape&&cd<3){Ct.st=1;Ct.t=0;}else{var ciclo=(T+2)%9;if(ciclo>3.5&&ciclo<7){pa=1.25;cc=.5+.12*Math.sin(T*9);cg=.25;}else cg=.6*Math.sin(T*.45);}}
 if(Ct.st===1){var u=Math.min(1,Ct.t/.45);Ct.x=Ct.hx+(Ct.qx-Ct.hx)*u;Ct.z=Ct.hz+(Ct.qz-Ct.hz)*u;var yq=groundY(Ct.qx,Ct.qz);Ct.y=Ct.hy+(yq-Ct.hy)*u+1.6*u*(1-u);Ct.yaw=Math.PI;pa=.6;if(u>=1){Ct.st=2;Ct.t=0;}}
 if(Ct.st===2&&cd>14&&Ct.t>10){Ct.st=0;Ct.t=0;Ct.x=Ct.hx;Ct.y=Ct.hy;Ct.z=Ct.hz;Ct.yaw=0;}
 VMB.lCat.visible=Ct.st!==2;vmPoe(VMB.lCat,0,Ct.x,Ct.y,Ct.z,Ct.yaw,0,0,1,rb,pa,cc,cg);VMB.lCat.instanceMatrix.needsUpdate=true;VMB.lCat.st.needsUpdate=true;
 /* mosquitinho: so com o poste aceso; leve = metade */
