function makeDog(onlyFallback){
  var g=new THREE.Group(),u=g.userData,fur=0xd99a52,dark=0xa86f33,light=0xf0cf9a,nose=0x15100c;
  var b=new BK();
  b.add(gIco(2,.08,3),fur,0,.47,.02,.16,.17,.38,0,0,0,1,.14);
  b.add(gIco(2,.08,4),light,0,.38,-.03,.13,.1,.28,0,0,0,1,.1);
  b.add(gIco(2,.08,5),fur,0,.52,-.24,.15,.16,.17,0,0,0,1,.12);
  b.add(gCyl(.08,.1,.2,10,2,.01,1),fur,0,.58,-.33,1,1,1,-.7,0,0,1,.1);
  b.add(gBox,0xd8344a,0,.55,-.31,.2,.04,.2,-.7,0,0,1,0);
  for(var i=0;i<10;i++)b.add(gCyl(0,.02,.07,4,1),dark,(hh(i,1,2)-.5)*.2,.62,.1-i*.05,1,1,1,0,0,(hh(i,2,3)-.5)*.6,1,.12);
  g.add(b.mesh(VMAT));
  var hd=new THREE.Group();hd.position.set(0,.66,-.42);g.add(hd);u.head=hd;
  var h=new BK();
  h.add(gIco(2,.08,6),fur,0,0,0,.115,.11,.12,0,0,0,1,.12);
  h.add(gIco(2,.06,7),light,0,-.04,-.13,.065,.055,.09,0,0,0,1,.08);
  h.add(gIco(1,.05,8),nose,0,-.01,-.215,.03,.024,.022);
  h.add(gIco(1,.05,9),0x7a3b36,0,-.075,-.18,.04,.012,.05);
  [-1,1].forEach(function(sg){
    h.add(gIco(1,.1,sg+10),dark,sg*.125,.02,.03,.04,.1,.07,0,0,sg*.45,1,.1);
    h.add(gIco(0,.05,0),0xf3eee6,sg*.05,.04,-.108,.022,.022,.012);h.add(gIco(0,.05,0),nose,sg*.05,.04,-.118,.012,.014,.008);
    h.add(gBox,dark,sg*.05,.075,-.105,.045,.012,.012,0,0,sg*-.2);
  });
  hd.add(h.mesh(VMAT));
  u.legs=[];
  [[-.1,-.2],[.1,-.2],[-.1,.26],[.1,.26]].forEach(function(p,i){
    var l=new THREE.Group();l.position.set(p[0],.36,p[1]);
    var lb=new BK();
    lb.add(gCyl(.052,.036,.34,8,3,.01,i),i<2?fur:dark,0,-.17,0,1,1,1,0,0,0,1,.12);
    lb.add(gIco(1,.06,i),light,0,-.355,-.015,.045,.035,.062);
    l.add(lb.mesh(VMAT));g.add(l);u.legs.push(l);
  });
  var tl=new THREE.Group();tl.position.set(0,.56,.38);tl.rotation.x=-.7;
  var tb=new BK();
  for(var k=0;k<5;k++)tb.add(gIco(1,.05,k),k>3?light:dark,0,k*.01,.06+k*.07,.034-k*.003,.034-k*.003,.05);
  tl.add(tb.mesh(VMAT));g.add(tl);u.tail=tl;
  g.traverse(function(o){o.castShadow=true;});
  u.ph=0;u.t=0;u.sit=false;
  if(!onlyFallback&&!QS.has('pipocaFallback'))pipocaPlug(g);
  return g;
}
/* Pipoca: corpo do Meshy, clipes do esqueleto CC0 e reserva até carregar. */
function pipocaPlug(g){
  if(!PIPOCA_HD){PIPOCA_WAIT.push(g);return;}
  var root=THREE.SkeletonUtils.clone(PIPOCA_HD.scene),u=g.userData;
  var fallback=g.children.slice();g.add(root);
  root.traverse(function(m){if(m.isMesh){m.castShadow=true;m.frustumCulled=false;}});
  var mixer=new THREE.AnimationMixer(root),actions={};
  PIPOCA_HD.animations.forEach(function(c){actions[c.name]=mixer.clipAction(c);});
  u.hd={root:root,mixer:mixer,actions:actions,cur:'',idle:0,bark:0,fallback:fallback};
  fallback.forEach(function(m){m.visible=false;});animDog(g,0,0,'idle');
}
function pipocaLoad(){
  if(PIPOCA_LOAD||QS.has('pipocaFallback'))return;PIPOCA_LOAD=true;
  gltfTry('models/pipoca/pipoca-meshy.glb',function(asset){
    var required=['Idle','Walk','Gallop','Eating','Sitting','Lying','Carry','Fear','FearRun','Bark'];
    if(required.some(function(n){return !THREE.AnimationClip.findByName(asset.animations,n);}))return;
    PIPOCA_HD=asset;var wait=PIPOCA_WAIT;PIPOCA_WAIT=[];wait.forEach(pipocaPlug);
  },function(){PIPOCA_WAIT=[];/* reserva ja visivel, falha de arte nunca interrompe o jogo */});
}
function pipocaHDAnim(g,dt,sp,state){
  var h=g.userData.hd;if(!h)return false;
  h.idle=sp>.2||state==='medo'?0:h.idle+dt;h.bark=Math.max(0,h.bark-dt);
  var carried=typeof CARRY!=='undefined'&&CARRY&&g===DOGM&&CARRY.ser==='dog';
  var n=carried||state==='colo'?'Carry':state==='dorme'||state==='deita'?'Lying':state==='medo'?(sp>.2?'FearRun':'Fear'):sp>3.4?'Gallop':sp>.2?'Walk':state==='late'||h.bark>0?'Bark':state==='fareja'||state==='tigela'?'Eating':state==='sit'||state==='sentado'||g.userData.sit||h.idle>4?'Sitting':'Idle';
  if(h.cur!==n){var prev=h.actions[h.cur],next=h.actions[n];next.reset().setEffectiveTimeScale(1).setEffectiveWeight(1).play();if(prev)prev.crossFadeTo(next,.16,false);h.cur=n;}
  h.actions[n].timeScale=n==='Walk'?clamp(sp/1.7,.45,1.8):n==='Gallop'?clamp(sp/5,.75,1.8):1;
  h.mixer.update(dt);g.position.y=0;return true;
}

/* ---------- viatura (sedan prata, 3 a 6 mil triangulos) ---------- */
BK.prototype.strut=function(a,b,r,hex,sd){
  var d=new THREE.Vector3().subVectors(b,a),L=d.length(),mid=new THREE.Vector3().addVectors(a,b).multiplyScalar(.5);
  var q=new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,1,0),d.clone().normalize());var e=new THREE.Euler().setFromQuaternion(q,'YXZ');
  this.add(gCyl(r,r,L,5,1),hex,mid.x,mid.y,mid.z,1,1,1,e.x,e.y,e.z,1,.06);
};
function quadG(arr,a,b,c,d){arr.push(a[0],a[1],a[2],b[0],b[1],b[2],c[0],c[1],c[2],a[0],a[1],a[2],c[0],c[1],c[2],d[0],d[1],d[2]);}
