// A viatura usa a mesma insígnia fictícia do colete do protagonista.
function insigniaDoVale(tecido){
 var cv=document.createElement('canvas');cv.width=cv.height=tecido?256:768;var x=cv.getContext('2d');x.scale(cv.width/256,cv.height/256);
 x.fillStyle='#22271d';if(tecido)x.fillRect(0,0,256,256);x.strokeStyle='#aaa68c';x.lineWidth=5;
 x.beginPath();x.moveTo(48,30);x.lineTo(208,30);x.lineTo(199,158);x.lineTo(128,226);x.lineTo(57,158);x.closePath();x.fill();x.stroke();
 /* Insignia ficticia de Vale de Abril: vale geometrico e duas sementes, sem brasao corporativo. */
 x.beginPath();x.moveTo(75,91);x.lineTo(128,153);x.lineTo(181,91);x.moveTo(83,156);x.lineTo(128,193);x.lineTo(173,156);x.stroke();
 x.fillStyle='#d6d1ac';x.fillRect(112,57,10,16);x.fillRect(136,57,10,16);
 return cv;
}
function texturaInsigniaVale(){if(!texturaInsigniaVale.tx){var t=new THREE.CanvasTexture(insigniaDoVale(false));t.encoding=THREE.sRGBEncoding;t.anisotropy=4;texturaInsigniaVale.tx=t;}return texturaInsigniaVale.tx;}
function carTex(kind,livery){
  if(kind==='pol'||kind==='pm'||livery){
    livery=livery||PERFIS[kind==='pm'?'pm':'pc'].viatura.livery;
    var key=livery.texto+'|'+livery.corTexto;
    if(LIVERY_TX[key])return LIVERY_TX[key];
    var cv=mkCanvas(1024,160),g=cv.getContext('2d'),size=76;
    g.clearRect(0,0,cv.width,cv.height);
    g.textAlign='center';g.textBaseline='middle';g.lineJoin='round';
    g.font='700 '+size+'px Rajdhani, sans-serif';
    while(g.measureText(livery.texto).width>984&&size>16){size--;g.font='700 '+size+'px Rajdhani, sans-serif';}
    g.strokeStyle=livery.corTexto===0x1a1710?'#f5dfb0':'#15171b';g.lineWidth=2;
    g.strokeText(livery.texto,512,82);g.fillStyle='#'+('000000'+livery.corTexto.toString(16)).slice(-6);g.fillText(livery.texto,512,82);
    var t=new THREE.CanvasTexture(cv);t.encoding=THREE.sRGBEncoding;t.anisotropy=4;
    LIVERY_TX[key]=t;return t;
  }
  var cv=mkCanvas(128,48),g=cv.getContext('2d');
  g.fillStyle='#e8e8e8';g.fillRect(0,0,128,48);g.fillStyle='#1d3f8a';g.fillRect(0,0,128,10);g.fillStyle='#111';g.font='700 28px Rajdhani, sans-serif';g.textAlign='center';g.textBaseline='middle';g.fillText('VDA4B12',64,30);
  var t=new THREE.CanvasTexture(cv);t.encoding=THREE.sRGBEncoding;t.anisotropy=4;return t;
}
