    var d=Math.min(dt,Math.max(0,p.tempo-p.t)),f=p.tempo>0?Math.min(1,(p.t+d)/p.tempo):1,s=f*f*(3-2*f);
    var arr=Math.exp(-1.6*d);m.position.x+=p.vx*(1-arr)/1.6;m.position.z+=p.vz*(1-arr)/1.6;p.vx*=arr;p.vz*=arr;p.t+=d;
    m.quaternion.copy(p.inicioQ).slerp(p.fimQ,s);
