/* casa=true (Marlene na escolta, CEO 09/11 05h15 "bem lisinho"): passo casa com o chao (Run 2,68 m/s e Walk 1,0 m/s no clip, medidos no pe de apoio) e histerese 1,3 a 1,6 sem pisca-pisca */
function glMode(u,sp,mode,casa){
  if(mode==='sit')glPlay(u,'Sitting');
  else if(casa&&mode==='walk'){if(u.gl&&u.gl.cur==='Run'?sp>1.3:sp>1.6)glPlay(u,'Run',sp/2.68);else glPlay(u,'Walk',Math.max(.3,sp/1.0));}
  else if(mode==='dance')glPlay(u,'Idle');
  else if(mode==='cheer'||mode==='wave')glPlay(u,u.gl.a.Clapping?'Clapping':'Idle');
  else if(sp>1.6)glPlay(u,'Run',Math.min(1.4,sp/2.2));
  else if(sp>.05)glPlay(u,'Walk',u.cfg.velha?Math.max(.28,sp*(u.cfg.vel||.55)):Math.max(.6,sp));
  else glPlay(u,'Idle');
}
