  if(!D){
    D=G.danca={t:0,on:false,b:[],feet:[],v:new THREE.Vector3()};
    [['Hips','Hips','z',.045],['Torso','Spine1','z',-.06],['UpperLegL','LeftUpLeg','x',.10],['UpperLegR','RightUpLeg','x',-.10],['LowerLegL','LeftLeg','x',.10],['LowerLegR','RightLeg','x',-.10],['UpperArmL','LeftArm','x',.22],['UpperArmR','RightArm','x',-.22],['LowerArmL','LeftForeArm','x',.18],['LowerArmR','RightForeArm','x',-.18]].forEach(function(p){var b=G.s.getObjectByName(p[0])||G.s.getObjectByName(p[1]);if(b)D.b.push({b:b,q:b.quaternion.clone(),axis:p[2],a:p[3]});});
    ['FootL','FootR','LeftFoot','RightFoot'].forEach(function(k){var b=G.s.getObjectByName(k);if(b)D.feet.push(b);});
  }
