  if(vestido&&vestido.sola.length){var mesh=n.m.userData.profMesh;mesh.updateMatrixWorld(true);var chao=Infinity;
    vestido.sola.forEach(function(i){chao=Math.min(chao,mesh.boneTransform(i,D.v).y);});G.s.position.y-=chao;
  }else if(Number.isFinite(floor)&&Number.isFinite(sole))G.s.position.y+=(floor-sole)/(G.s.parent.getWorldScale(D.v).y||1);
