  var bones=v.sm.skeleton.bones,rows=[],i,b,r,rx=n.m.rotation.x,rz=n.m.rotation.z,ry=n.m.position.y;
  for(i=0;i<bones.length;i++){b=bones[i];r=BANDIDO.g.scene.getObjectByName(b.name);rows.push({b:b,from:b.quaternion.clone(),pos:b.position.clone(),to:r.quaternion.clone(),rest:r.position.clone()});b.quaternion.copy(r.quaternion);b.position.copy(r.position);}
