    var a=v.s.getObjectByName('mixamorig'+sd+'Arm'),f=v.s.getObjectByName('mixamorig'+sd+'ForeArm'),h=v.s.getObjectByName('mixamorig'+sd+'Hand');
    var origin=new THREE.Vector3(),elbow=new THREE.Vector3(),target=new THREE.Vector3(),dir=new THREE.Vector3(),bend=new THREE.Vector3();
    a.getWorldPosition(origin);f.getWorldPosition(elbow);h.getWorldPosition(target);
    var upper=origin.distanceTo(elbow),lower=elbow.distanceTo(target),dist=Math.sqrt(upper*upper+lower*lower+2*upper*lower*Math.cos(Math.PI/6));
    n.m.worldToLocal(p.tmp.copy(origin));var dx=side*.035-p.tmp.x,dz=-.178-p.tmp.z,yy=p.tmp.y-Math.sqrt(dist*dist-dx*dx-dz*dz);
    n.m.localToWorld(target.set(side*.035,yy,-.178));dir.copy(target).sub(origin);var d=dir.length();dir.normalize();
    var along=(upper*upper-lower*lower+d*d)/(2*d),height=Math.sqrt(Math.max(0,upper*upper-along*along));
    bend.set(side,0,-.6).transformDirection(n.m.matrixWorld);bend.addScaledVector(dir,-bend.dot(dir)).normalize();elbow.copy(origin).addScaledVector(dir,along).addScaledVector(bend,height);
    glAim(a,p.tmp.copy(elbow).sub(origin).normalize());f.getWorldPosition(origin);glAim(f,p.tmp.copy(target).sub(origin).normalize());
