  for(var i=0;i<2;i++){var arm=p.arms[i],ring=cuffs.children[i];arm.h.getWorldPosition(arm.target);arm.b.getWorldPosition(arm.origin);ring.position.copy(arm.target);ring.quaternion.setFromUnitVectors(_gS.set(0,0,1),_gD.copy(arm.target).sub(arm.origin).normalize());ring.scale.setScalar(.58);}
  var chain=cuffs.children[2],left=cuffs.children[0].position,right=cuffs.children[1].position;
  chain.position.copy(left).add(right).multiplyScalar(.5);chain.quaternion.setFromUnitVectors(_gS.set(1,0,0),_gD.copy(right).sub(left).normalize());chain.scale.x=left.distanceTo(right)/.06;cuffs.visible=vis;
