var UNO_VIDA=3,UNO_BT=3;/* CEO 09/11 'nao consigo ganhar': era 1,2 s; o Uno foguete volta a 6 m/s em 1,2 s, entao segurar W no muro tirava as 3 barras em 4,6 s (medido). Agora so conta outra batida depois de 3 s sem encostar */
function unoVida(u){return !u||u.cai||u.mao?0:u.vida==null?UNO_VIDA:u.vida;}
function unoBatida(lado){var u=unoEsc();if(!u)return;var db=u.bT==null?9:S.time-u.bT;if(u.cai||u.mao||S.fc&&S.fc.on&&fcToca(S.fc))return;/* bater no Fusca e a missao: nao custa barrinha */u.bT=S.time;if(db>=0&&db<UNO_BT)return;/* CEO 09/11 'nao consigo ganhar': raspar no muro sem parar conta 1 batida so (jogada medida: perdia as 3 barras em 4,6 s) */u.vida=unoVida(u)-1;
  if(u.vida<=0){PCARS[UNO_SPOT].solta=lado;return;}sfx('bump');say(u.vida===1?'Escada por um fio: na próxima batida ela cai.':'A escada balançou. Segura esse Uno.','sys',2,null,false,'perigo');}
function unoVidaHud(u){var e=$('unov'),on=!!(u&&S.uno&&S.inCar&&!S.cut&&!S.fcCena),v=on?unoVida(u):-1;if(e._v===v)return;e._v=v;e.style.display=on?'':'none';
  for(var i=0;on&&i<UNO_VIDA;i++)e.children[i].className=i<v?'':'off';}
