function qBancoRe(re){var p=QUIZ_BANCO.filter(function(q){return q.t.length<=200&&re.test(q.t);});return p.length?p[Math.floor(Math.random()*p.length)]:quizEscolhe(1,'facil',170)[0];}function qById(id){if(QUIZ_PRONTO){/* decisao da historia: questao do banco sobre o mesmo assunto, se houver */var qb=qBancoRe(id==='maus'?/maus.tratos|animais|animal/i:id==='casa'?/domic[ií]lio|inviol/i:/./);if(qb)return qb;}for(var i=0;i<QB.length;i++)if(QB[i].id===id)return QB[i];}

