function setTxt(id,v){if(UIK[id]!==v){UIK[id]=v;dica($(id),v);}}
function pop(id){var e=$(id);e.classList.remove('up');void e.offsetWidth;e.classList.add('up');}
var HUDK={};
function hud(){
  var pz=pazDisponivel();if(HUDK.pz!==pz){HUDK.pz=pz;$('pazB').classList.toggle('on',pz);}if(pz){var el=$('pazB'),modo=INPUT+':'+S.inCar+':'+PAD.sony+':'+pazHoras();if(HUDK.pzh!==modo){HUDK.pzh=modo;var carro=S.inCar&&INPUT==='controle',key=INPUT==='toque'?'':carro?'Menu':PAD.sony&&INPUT==='controle'?'△':tecla('paz');el.firstElementChild.textContent=key;el.firstElementChild.hidden=!key;el.setAttribute('aria-label',(key?key+': ':'')+'Pausa pro tereré. Esperar '+pazHoras()+' h');el.title='Esperar '+pazHoras()+' h até a paz voltar';}}
  if(HUDK.rs!==S.rs){if(HUDK.rs!==undefined)pop('rs');HUDK.rs=S.rs;$('rs').textContent='R$ '+S.rs;}
  if(HUDK.pts!==S.pts){if(HUDK.pts!==undefined)pop('pts');HUDK.pts=S.pts;$('pts').textContent=S.pts;}
  if(HUDK.aut!==S.aut){if(HUDK.aut!==undefined)pop('aut');HUDK.aut=S.aut;$('aut').textContent=S.aut;}
  if(HUDK.k!==S.karma){HUDK.k=S.karma;$('kval').textContent=(S.karma>0?'+':'')+S.karma;$('kmark').style.left=(50+S.karma/2)+'%';}
  var v=S.vest?'inline-block':'none';if(HUDK.vest!==v){HUDK.vest=v;$('vest').style.display=v;}
  var cr=S.karma<=-30?'inline-block':'none';if(HUDK.cr!==cr){HUDK.cr=cr;corr.style.display=cr;}
  var fl=S.funk||radioNoAr()?'RÁDIO DA VIATURA · LIGADO':'RÁDIO DA VIATURA · DESLIGADO';if(HUDK.fl!==fl){HUDK.fl=fl;$('funkb').textContent=fl;$('funkb').classList.toggle('on',S.funk);$('bR').classList.toggle('on',!!radioNoAr());}
  var np=radioNoAr()?PAT.n:'';if(HUDK.np!==np){HUDK.np=np;$('npl').lastChild.textContent='No ar · '+np;$('npl').classList.toggle('on',!!np);}
}
