    if(VOZB.want!==id||S.time-t0>(S.phase==='cut'?9:2.5))return; /* CEO 07/11 "so apareceu a primeira fala": na abertura o pacote de voz pode chegar tarde; a fala espera ate a proxima comecar */
    var quando=falaVozQuando(AC.currentTime); /* CENA LIVRE 5f: a nova espera a vez, nunca corta a anterior */
    var s=AC.createBufferSource(),g=AC.createGain();s.buffer=buf;g.gain.value=(v[1]?(/^Dona Marlene/.test(txt)?.62:.85):.95)*(MOB?1.35:1);/* CEO 09/11 'voz muito baixa no smartphone': alto-falante do celular pede voz mais forte */s.connect(g);var sp=(v[1]||/^Você:/.test(txt))?null:vozEspaco(id,g);(sp||g).connect(v[1]?vozFx():AU.master);s.connect(vozAn());
