    var f=S.falante;if(f&&f.voz===id){f.talk=S.time+(quando-AC.currentTime)+buf.duration/rt+.1;f.talkDur=f.talk-f.talkStart;} /* audio chegou atrasado: boca segue o audio, nao o relogio */
