var SOM_KEY='valeSom',SOM={sfx:90,mus:100,mot:15}/* CEO 09/11 16h1x: padrao efeitos 90, musica 100, motor 15 (escape aberto so pra quem abrir no menu) */,SOM_MEDIA=[];
function somLe(){var v;try{v=JSON.parse(localStorage.getItem(SOM_KEY)||'null');}catch(e){}if(v&&v.lei!==2)v.mus=v.mus<100?70:100;/* a curva da musica mudou: quem tinha abaixado na regua antiga volta pro 100 uma vez, senao o radio some */['sfx','mus','mot'].forEach(function(k){SOM[k]=v&&typeof v[k]==='number'&&isFinite(v[k])?Math.max(0,Math.min(100,v[k])):k==='mot'?15:k==='sfx'?90:100;});}
