/* CEO 09/11 22h04 'o som do radio ta muito alto... continuou reclamando mesmo eu abaixando no menu': medido na saida, MUSICA de 100 pra 30 so tirava 5,5 dB (o compressor final achata). Curva ao quadrado so na musica: 50% = -12 dB na entrada. 100% nao muda. */
function somG(k){var v=SOM[k]/100;return k==='mus'?v*v:v;}
function somAplica(){['sfx','mus','mot'].forEach(function(k){if(AU[k+'G'])AU[k+'G'].gain.value=somG(k);});if(AU.master)AU.master.gain.value=MUTED?0:.9;impEsp();SOM_MEDIA.forEach(somMediaAplica);}
