['touchstart','touchend','pointerdown','mousedown','keydown','click'].forEach(function(ev){document.addEventListener(ev,audioInit,{capture:true,passive:true});});
/* CEO 07/11: aba escondida fica muda (varias abas abertas no Mac = som por cima de som) */
document.addEventListener('visibilitychange',function(){var lm=document.getElementById('lmus');if(document.hidden){if(AC&&AC.state==='running')try{AC.suspend();}catch(e){}if(lm&&!lm.paused){lm.pause();lm.dataset.vis='1';}return;}if(AC&&AC.state!=='running'&&!pausado())try{AC.resume();}catch(e){}if(lm&&lm.dataset.vis){delete lm.dataset.vis;lm.play().catch(function(){});}});
function aok(){return AC&&AU.master&&!MUTED;}
/* botao mostra a verdade: so diz SOM ON com o audio rodando de fato (no iPhone, se travar, pede o toque) */
function muteLbl(){var b=$('mute');if(!b)return;var t=MUTED?'SOM DESLIGADO':(SELFTEST||(AC&&AC.state==='running'))?'SOM LIGADO':'TOQUE P/ SOM';if(b.textContent!==t)b.textContent=t;}
function tone(f0,f1,d,type,g,delay,dest){
  if(!aok())return;
  try{
    var t=AC.currentTime+(delay||0),o=AC.createOscillator(),a=AC.createGain();
    o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+d);
    a.gain.setValueAtTime(g,t);a.gain.exponentialRampToValueAtTime(.0008,t+d);
    o.connect(a);a.connect(dest||AU.fxg);o.start(t);o.stop(t+d+.03);
  }catch(e){}
}
/* rajada de ruido filtrado: base de passo, porta, chiado, latido, conversa */
function nburst(freq,q,d,g,delay,type,dest,f1){
  if(!aok())return;
  try{
    var t=AC.currentTime+(delay||0),s=AC.createBufferSource(),f=AC.createBiquadFilter(),a=AC.createGain();
    s.buffer=noiseBuf();f.type=type||'bandpass';f.frequency.setValueAtTime(freq,t);if(f1)f.frequency.exponentialRampToValueAtTime(f1,t+d);f.Q.value=q||1;
    a.gain.setValueAtTime(0.0001,t);a.gain.exponentialRampToValueAtTime(g,t+Math.min(.02,d*.3));a.gain.exponentialRampToValueAtTime(.0005,t+d);
    s.connect(f);f.connect(a);a.connect(dest||AU.fxg);s.start(t,Math.random()*1.5,d+.05);
  }catch(e){}
}
function sfx(n,v,p){
  if(n==='thump'){tone(95,38,.22,'sine',.22);}
  else if(n==='apito'){tone(2400,2850,.18,'sine',.12);tone(2850,2500,.12,'sine',.08,.19);}
  else if(n==='beep'){tone(880,880,.09,'square',.04);tone(880,880,.09,'square',.04,.15);}
  else if(n==='siren'){tone(600,1000,.35,'sawtooth',.03);tone(1000,600,.35,'sawtooth',.03,.35);}
  else if(n==='ok'||n==='hit'){tone(520,780,.14,'triangle',.09);tone(780,1170,.16,'triangle',.07,.1);}
  else if(n==='bad'||n==='miss'){tone(220,110,.3,'sawtooth',.07);tone(165,80,.3,'sawtooth',.06,.12);}
  else if(n==='agua'){nburst(700,.7,.22,.14,0,'bandpass',null,2600);nburst(320,.5,.14,.08,.06,'lowpass');}
  /* CEO 07/11 "pulo do Mario, faz um barulho mais realista": foley de verdade (tools/sfx-eleven.py pk-*), v = forca do impacto 0..1 */
  else if(n==='pkPulo'){if(!smp('pk-pulo',.55*(v==null?1:v),.94+Math.random()*.12,p))nburst(3200,1.2,.07,.12,0,'bandpass',null,1800);}
  else if(n==='pkPouso'){var f=v==null?1:v;if(!smp('pk-pouso',.25+.65*f,.92+Math.random()*.14-.08*f,p))nburst(160,.8,.12,.25*f,0,'lowpass');}
  else if(n==='pkAgarra'){var ag=pkAgVar(); /* CEO 08/11: 6 variacoes sem voz (mao + tenis), nunca repete a anterior, tom fixo */
    if(!smp('pk-agarra-'+ag,.7*(v==null?1:v),1,p))nburst(1800,1.4,.05,.16,0,'bandpass');}
  else if(n==='soco'){smp('soco-'+(1+(Math.random()*4|0)),.9*(v==null?1:v),.92+Math.random()*.16,p)||tone(120,50,.12,'square',.07);}
  else if(n==='grunhido'){smp('grunhido-'+(1+(Math.random()*5|0)),.55*(v==null?1:v),1,p); /* CEO 08/11: voz com tom fixo, variar tom desafina */}
  else if(n==='pkTelha'){smp('pk-telha',.5*(v==null?1:v),.95+Math.random()*.1,p);}
  else if(n==='bump'){tone(120,50,.12,'square',.07);}
  else if(n==='metal'){tone(1760,1700,.55,'triangle',.07);tone(2640,2560,.42,'sine',.045,.005);tone(940,900,.7,'triangle',.05);tone(3950,3800,.18,'square',.012);nburst(2600,.6,.05,.1,0,'bandpass');}/* CEO 07/11: placa soa metal */
  else if(n==='crash'){if(!smp(Math.random()<.5?'crash-forte-1':'crash-forte-2',1.1,.92+Math.random()*.16)&&!smp('escape-estouro',.9,.55))nburst(90,.7,.35,.5);tone(70,35,.35,'sine',.5*MIX.batida);nburst(1800,1.2,.18,.25*MIX.batida,.02);tone(120,50,.12,'square',.1*MIX.batida,.05);}
  else if(n==='crashLeve'){if(!smp('crash-leve',.9,.9+Math.random()*.2))tone(120,50,.12,'square',.07);}
  else if(n==='atropLeve'){if(!smp('atropelo-leve',1,.95+Math.random()*.1))tone(120,50,.12,'square',.07);}
  else if(n==='atropForte'){smp('atropelo-forte',1.1);}
  else if(n==='muroForte'){if(!smp('muro-forte',1.1,.92+Math.random()*.16))nburst(90,.7,.35,.5);}
  else if(n==='muroLeve'){if(!smp('muro-leve',.9,.9+Math.random()*.2))tone(95,40,.2,'sine',.1);}
  else if(n==='corpoChao'){smp('corpo-chao',.9,.95+Math.random()*.1);}
  else if(n==='buzina'){smp('buzina',.7,.95+Math.random()*.1);}
  else if(n==='screech'){if(smp('freada',.9,.95+Math.random()*.1))return;nburst(2600,5,.26,.05,0,'bandpass',null,1900);tone(1450,1150,.22,'sawtooth',.012);}
  else if(n==='radio'){nburst(1800,2,.12,.05);tone(1500,1100,.06,'square',.03);tone(1100,1500,.06,'square',.03,.08);}
  else if(n==='whimper'){tone(620,380,.3,'sine',.06);tone(540,320,.3,'sine',.05,.34);}
  else if(n==='step'){nburst(220+Math.random()*80,.8,.09,.16,0,'lowpass');}
  else if(n==='door'){nburst(180,1,.25,.3,0,'lowpass');tone(140,60,.2,'square',.05);nburst(900,6,.4,.05,.05,'bandpass',null,500);}
  else if(n==='interact'){tone(700,1050,.08,'triangle',.08);tone(1050,1400,.1,'triangle',.06,.07);}
  else if(n==='cambTrinco'){tone(1250,450,.035,'square',.055);nburst(1900,.5,.045,.055,.015,'highpass');}
  else if(n==='carDoor'){if(!(smp('car-door',.45,.8)&&smp('car-door',.85,1,0,.55))){nburst(300,1,.16,.28,0,'lowpass');tone(200,90,.12,'square',.04,.02);}}
  else if(n==='bark'){nburst(700,3,.12,.2,0,'bandpass',AU.amb,420);tone(520,300,.1,'sawtooth',.05,0,AU.amb);}
  else if(n==='moto'){motoPass();}
  else if(n==='chat'){chatter();}
}
/* Toda moto nasce em makeBike e ganha uma das 3 vozes espaciais. */
function motoPass(){/* O evento de roteiro nao cria uma quarta voz sem posicao. */}
function motoMix(x,z,v,radio){var e=esp(x,z,40);return {gain:e.g*(v>.15?MIX.moto:.065)*(radio?MOTOR_COM_RADIO:1),pan:e.pan,rate:.85+Math.min(MIX.motoGiro,Math.abs(v)*.065)};}
/* CEO 09/11: moto civil que levou arma apontada fica so no ronco leve, sem acelerar */
function motoGanho(m,v,radio){var e=motoMix(m.position.x,m.position.z,v,radio);if(m.userData.calma){e.gain*=REACAO_ARMA.moto.calmaGanho;e.rate=.85;}return e;}
var MOTO_NEAR=[];
function motoEngines(dt,radio){
  /* pausa, cutscene, conversa, game over, subsolo: nenhuma voz de moto fica tocando */
  var near=MOTO_NEAR,quieto=S.phase!=='play'||carroMudo()||pausado()||!carroOuve();near.length=0;
  for(var i=0;i<MOTO_MESHES.length;i++){var m=MOTO_MESHES[i],u=m.userData,p=m.position;
    var v=u.motorX==null?0:Math.min(25,Math.hypot(p.x-u.motorX,p.z-u.motorZ)/Math.max(.001,dt));u.motorX=p.x;u.motorZ=p.z;
    var visible=!!m.parent;for(var a=m;a&&visible;a=a.parent)visible=a.visible;
    u.paradoT=v<.15?(u.paradoT||0)+dt:0;/* CEO 09/11 04h "barulho de moto em loop": moto parada ha mais de 2 s desliga o motor */
    if(!visible||u.semMotor||u.paradoT>2||quieto)continue;var dx=p.x-camera.position.x,dz=p.z-camera.position.z,d=dx*dx+dz*dz;if(d>=1600)continue;
    var item={m:m,v:v,d:d},j=0;while(j<near.length&&near[j].d<=d)j++;if(j<3){near.splice(j,0,item);if(near.length>3)near.pop();}
  }
  for(i=0;i<3;i++){var n=near[i],l=loopGain('moto-motor-loop',AU.engBus||AU.fxg,'moto-engine-'+i,1);if(!l)continue;
    // ponytail: trecho central da gravacao CC0 existente, 3 fontes reutilizadas para toda a frota.
    l.s.loopStart=0;l.s.loopEnd=l.s.buffer.duration;
    var e=n?motoGanho(n.m,n.v,radio):null;
    l.owner=n?n.m:null;l.g.gain.value=e?e.gain:0;if(e){l.s.playbackRate.value=e.rate;if(l.p)l.p.pan.value=e.pan;}
  }
}

function chatter(){
  for(var i=0;i<5;i++)nburst(500+Math.random()*700,5,.09+Math.random()*.1,.04,i*.17+Math.random()*.06,'bandpass',AU.amb);
}
/* funk: batida de baile 128 bpm (tamborzao simplificado) agendada com antecedencia */
function musicTick(){
  if(!aok()||!AU.mus)return;
  if(!TRK.bad){AU.nextBeat=AC.currentTime;return;} /* ordem CEO 12: o "pixel beat" sintetico nunca soa (nem enquanto a trilha real carrega); so se o navegador nao cria <audio> */
  var spb=60/AU.bpm/4,now=AC.currentTime;
  if(AU.nextBeat<now-.5)AU.nextBeat=now;
  while(AU.nextBeat<now+.35){
    var s=AU.step16,t=AU.nextBeat,d=AU.mus,i;
    var kick=PAT.k[s%16];
    var snr=PAT.s[s%16];
    var hat=!!PAT.h[s%16];
    if(kick){var o=AC.createOscillator(),g=AC.createGain();o.frequency.setValueAtTime(130,t);o.frequency.exponentialRampToValueAtTime(42,t+.16);g.gain.setValueAtTime(.9,t);g.gain.exponentialRampToValueAtTime(.001,t+.22);o.connect(g);g.connect(d);o.start(t);o.stop(t+.25);}
    if(snr){var ns=AC.createBufferSource(),nf=AC.createBiquadFilter(),ng=AC.createGain();ns.buffer=noiseBuf();nf.type='bandpass';nf.frequency.value=1800;nf.Q.value=.7;ng.gain.setValueAtTime(.5,t);ng.gain.exponentialRampToValueAtTime(.001,t+.14);ns.connect(nf);nf.connect(ng);ng.connect(d);ns.start(t,Math.random(),.2);}
    if(hat){var hs=AC.createBufferSource(),hf=AC.createBiquadFilter(),hg=AC.createGain();hs.buffer=noiseBuf();hf.type='highpass';hf.frequency.value=7000;hg.gain.setValueAtTime(s%4===2?.22:.12,t);hg.gain.exponentialRampToValueAtTime(.001,t+.04);hs.connect(hf);hf.connect(hg);hg.connect(d);hs.start(t,Math.random(),.06);}
    if(s%16===0||s%16===6||s%16===10){ /* baixo */
      var bo=AC.createOscillator(),bg=AC.createGain(),bf=AC.createBiquadFilter(),nt=[55,55,65.4,49][Math.floor(s/16)%4];
      bo.type='sawtooth';bo.frequency.value=nt;bf.type='lowpass';bf.frequency.value=300;bg.gain.setValueAtTime(.42,t);bg.gain.exponentialRampToValueAtTime(.001,t+spb*2.4);
      bo.connect(bf);bf.connect(bg);bg.connect(d);bo.start(t);bo.stop(t+spb*2.5);
    }
    if(s%16===3||s%16===11||s%16===14){ /* stab de teclado */
      var m=[440,523.3,392,466.2][Math.floor(s/16)%4];
      for(i=0;i<2;i++){var so=AC.createOscillator(),sg=AC.createGain();so.type='square';so.frequency.value=m*(i?1.5:1);sg.gain.setValueAtTime(.07,t);sg.gain.exponentialRampToValueAtTime(.001,t+.16);so.connect(sg);sg.connect(d);so.start(t);so.stop(t+.18);}
    }
    AU.nextBeat+=spb;AU.step16++;
  }
}
/* sirene: volume acima de tudo (musica .3, motor .2); ciclo 12 s = 8 s wail (sobe e desce 650-1500 Hz em 3 s) + 4 s yelp (varredura de .3 s) */
var SIRENE_VOL=.42;
/* CEO 06/11 'a musica tambem tem que ser alta... cada um com seu punch': medido com ffmpeg, radio (faixa de painel 300-3600 Hz) saia ~10 dB abaixo do motor no talo. Radio sobe (+8 dB) e o motor abaixa 6 dB so com o radio ligado; sem radio o motor segue com punch cheio. So som de dentro da viatura; som pra fora e skill futura. */
/* CEO 09/11 22h04 (live) 'o som do radio ta muito alto': radio saia 8,5 dB acima do resto do jogo (-10,8 contra -19,3 dB medidos na saida). Ganho 1,8 -> 0,45: sai perto de -18 dB, abaixo da voz. */
var RADIO_VOL=1,RADIO_WET=.45,MOTOR_COM_RADIO=.5;
function sirFreq(t){var c=t%12;if(c<8){var w=(c%3)/3;return 650+850*(w<.5?w*2:2-w*2);}var y=(c%.3)/.3;return 700+800*y;}
/* chamado todo quadro: volume da musica pela distancia ao baile, motor, sirene, ambiente aleatorio */
var BAILE_SOM=[90,49,48]; /* centro do galpao e raio em que o grave vaza abafado pra rua a noite */
function baileNoite(){return nightF()>.35;}
var MUS_CENA_FINAL={list:null,volume:0,rapido:true};/* CEO 12/11 kv: cena final toca so a trilha e as falas dela */
function musicScene(){
  if(EST.on||EST.fim)return MUS_CENA_FINAL;
  if(S.marlene&&S.marlene.silencio)return {list:null,volume:0};
  /* CEO 07/11 "o volume do soundtrack de acordo com a cena": mesma trilha da fuga ate o Uno, sem reiniciar; impasse baixo e abafado,
     porrada alta, queda some a musica e fica so o grito, pancada no silencio, depois volta devagar; rendicao em silencio */
  var qq=S.soco&&S.soco.queda;
  if(qq)return {list:TRKL.fuga,volume:qq.t<.4?.35:qq.t<1.5?.05:qq.t<2.8?0:.14,abafado:qq.t>=.4,rapido:qq.t<1.7};
  if(S.step==='topo34')return {list:TRKL.fuga,volume:.15,abafado:true,rapido:true};
  if(S.step==='soco34')return {list:TRKL.fuga,volume:.62};
  if(S.step==='fuga')return {list:TRKL.fuga,volume:S.slowT>0?.18:.55,abafado:S.slowT>0,rapido:S.slowT>0}; /* camera lenta no pulo grande: trilha afunda junto */
  if(S.step==='fugacarro'&&S.uno&&S.inCar)return {list:TRKL.uno,volume:.6,radio:true};/* radio do Uno com escada */
  if(S.step==='fugacarro'&&!(S.funk&&S.inCar&&S.stn>=0))return {list:TRKL.fuga,volume:.5};
  if(S.step==='rendido')return {list:null,volume:0};
  var r=S.inCar?C0:P,inside=!S.inCar&&(r.x>BAILE.gate[0]+.8&&r.x<102&&Math.abs(r.z-49)<20||pisoEm(P));
  /* CEO 07/11 "de dia som leve family friendly, de noite pancadao pesado... a noite ouvir la de fora bem abafado" */
  var noite=baileNoite(),bd=Math.hypot(r.x-BAILE.stage[0],r.z-BAILE.stage[2]),bv=clamp(1-.85*Math.max(0,bd-4)/56,.15,1),near=!S.baileFim&&inside&&bd<=60?bv:0,lst=near?(noite?'baileNoite':'baile'):null,ab=false;
  if(!S.inCar&&!near&&!S.baileFim&&bd<=60){near=bv;lst=noite?'baileNoite':'baile';ab=true;}
  MUSPOT.forEach(function(m){var v=clamp(1-Math.hypot(r.x-m.x,r.z-m.z)/26,0,1)*.42;if(v>near){near=v;lst=m.k;ab=false;}});
  var radio=radioNoAr();
  if(S.phase==='cut'&&S.step==='cena')return {list:STATIONS[0].f,volume:.5}; /* CEO 04/11: abertura com o modao de viola do protagonista */
  return {list:radio?(radio.tipo?null:radio.f):lst?TRKL[lst]:null,estacao:radio&&radio.tipo?radio:null,volume:radio?RADIO_VOL:near,radio:!!radio,abafado:!radio&&ab,pesado:!radio&&(lst==='baile'||lst==='baileNoite')&&!ab};
}
function audioUpdate(dt){
  if(!AC||!AU.master)return;
  AU.master.gain.value=MUTED?0:.9;impEsp();
  var music=musicScene(),mv=music.volume;
  if(!isFinite(mv)||!isFinite(dt))return;
  var falando=VOZB.end>AC.currentTime;if(falando)mv*=DUCK_VOZ;if(S.sir&&S.inCar)mv*=.5; /* CEO 04/11: musica abaixa quando alguem fala e volta no silencio */
  AU.mus.gain.value+=(mv-AU.mus.gain.value)*Math.min(1,dt*(falando||music.rapido?8:2.5));
  trkWant(music.list);radioTick(music.estacao,dt);muteLbl();baileFx(music,dt);
  var run=S.inCar&&S.phase==='play';
  var cv=isFinite(C0.v)?C0.v:0,av=Math.abs(cv),mx=ambAlvo({run:run,v:cv,rpm:S.uno?0:C0.rpmVtr,inCar:S.inCar,indoor:!S.inCar&&!!pisoEm(P),coberto:!!NM.somChuva&&NM.dentro,gente:gentePerto(),silencio:!!(S.marlene&&S.marlene.silencio)||EST.on||EST.fim}),k1=Math.min(1,dt*6),k2=Math.min(1,dt*1.5);
  if(NM.somChuva||AU.chuva)nmSomTick(mx.chuva,(falando?DUCK_VOZ:1)*(S.phase==='play'&&!cenaOn()?1:.18));
  var mg=loopGain('motor-viatura',AU.engBus||AU.fxg,0,1),fu=loopGain('fusca-motor',AU.engBus||AU.fxg,0,1),em=esp(C0.x,C0.z,60);
  /* CEO 06/11 "barulho de motor de Fusca... pitch pra simular a marcha": carro civil (Uno) usa o boxer a ar com troca de marcha */
  if(fu){fu.g.gain.value+=((S.uno?mx.mGain*UNO_SOM*em.g*(music.radio?MOTOR_COM_RADIO:1):0)-fu.g.gain.value)*k1;fu.s.playbackRate.value=marcha(av)*.9;/* CEO 10/11 'barulho do Uno um pouquinho mais baixo, imponente sem irritar': volume .85 -> .55 e giro 10% mais grave (menos esganicado no fim da marcha) */if(fu.p)fu.p.pan.value=em.pan;}
  fuscaNpc(dt);motoEngines(dt,music.radio);
  /* CEO 06/11 bug "desço da viatura e o motor fica na minha cabeça": fora do carro a viatura fica DESLIGADA (CEO 06/11 19h: ainda ouvia o motor ao descer) */
  var ec=(!S.inCar&&S.phase==='play'&&!S.uno)?esp(C0.x,C0.z,28):null;if(mg&&mg.p)mg.p.pan.value=em.pan;
  if(mg){mg.g.gain.value+=((S.uno&&fu?0:ec?0:mx.mGain*em.g*(music.radio?MOTOR_COM_RADIO:1))-mg.g.gain.value)*k1;mg.s.playbackRate.value=ec?.8:mx.mRate;AU.engO.frequency.value=32+av*3.2;AU.eng.gain.value+=((run?(ec?0:(.2+Math.min(.16,av*.008))*em.g):0)-AU.eng.gain.value)*k1;} /* fora do carro o sub cai com a distancia (senao zumbe na cabeca) */ /* sub grave por baixo da gravacao: peito do motor */
  else{AU.engO.frequency.value=38+av*5.5;AU.eng.gain.value+=((run?(.05+Math.min(.1,av*.006))*em.g:0)-AU.eng.gain.value)*k1;}
  /* CEO 04/11 "escape aberto, rebenta": ronco na arrancada, estouro ao tirar o pe em alta */
  /* CEO 07/11 'voltou o barulho da viatura fora da viatura, estragou a cutscene com o Professor': em cena todo som de carro cala num ponto so (barramento do motor, sub, pneu, sirene) */
  var mudo=carroMudo();if(AU.engBus)AU.engBus.gain.value+=((mudo?0:1)-AU.engBus.gain.value)*Math.min(1,dt*8);if(mudo)AU.eng.gain.value*=Math.max(0,1-dt*8);
  pneuTick(C0,dt,run&&!mudo?1:0);
  if(run){var th=C0.thr||0;AU.escT=(AU.escT||0)-dt;
    AU.peT=th>.6?(AU.peT||0)+dt:0;var esc=.3+.7*Math.min(1,SOM.mot/60);/* CEO 10/11 'qualquer coisinha ja da um barulho forte de corte de giro, irritante': so ronca com o pe embaixo por 0,7 s seguido, no maximo 1 vez a cada 12 s, e o volume segue o controle Motor do menu (padrao 15 = baixo; quem sobe o Motor ganha o ronco cheio) */
    if(AU.peT>.7&&av<14&&AU.escT<=0){if(av<4&&!S.uno&&smp('arrancada',.55*esc*em.g,.95+Math.random()*.1,em.pan))AU.escT=12;else if(smpE('motor-ronco',(S.uno?.5:.8)*esc*em.g,.92+av*.012+Math.random()*.1,em.pan))AU.escT=12;} /* CEO 06/11 'pisa fundo e nao tem som': arrancada com pneu girando */
    }
  escapeTick(dt,run&&!mudo,C0.thr||0,av,em.g);
  [['amb-passaros','pas'],['amb-criancas','cri'],['amb-burburinho','bur']].forEach(function(a){var l=loopGain(a[0],AU.amb);if(l)l.g.gain.value+=(mx[a[1]]-l.g.gain.value)*k2;});
  AU.sir.gain.value+=((S.sir&&S.inCar&&S.phase==='play'&&!mudo?SIRENE_VOL:0)-AU.sir.gain.value)*Math.min(1,dt*8);
  var sf0=sirFreq(S.time||0);AU.sirO.frequency.value=sf0;AU.sirO2.frequency.value=sf0*1.008;
  if(mx.silencio)return;
  AU.ambT-=dt;
  if(AU.ambT<=0){
    AU.ambT=5+Math.random()*7;var k=Math.random();
    sfx(mx.indoor?(k<.5?'chat':'bark'):k<.3?'bark':k<.45?'moto':k<.9?'chat':'bark'); /* CEO 05/11 "reduz a moto, ta irritante": moto de fundo rara e baixa */
  }
  musicTick();
}
/* pneu (CEO 05/11): rolagem + chiado de freio e drift. Por carro (c._pn), pronto para NPC na perseguicao: pneuTick(npcCar,dt,vol pela distancia) */
function pneuAlvo(c){var v=c.v||0,av=Math.abs(v),sl=Math.abs(c.sl||0),fr=av>3?clamp((-(c.ac||0)*(v<0?-1:1)-6)/10,0,1):0,dr=av>5?clamp((sl-.12)/.4,0,1):0;
  return {rol:Math.min(.22,av*.009),chi:Math.max(fr*.8,dr)*Math.min(1,av/12)*.5,f:1500+sl*1400+av*18};}
function pneuTick(c,dt,vol){if(!aok())return;var p=c._pn;
  if(!p){var s=AC.createBufferSource(),lp=AC.createBiquadFilter(),bp=AC.createBiquadFilter();s.buffer=noiseBuf();s.loop=true;lp.type='lowpass';lp.frequency.value=180;bp.type='bandpass';bp.Q.value=7;
    p=c._pn={r:AC.createGain(),c:AC.createGain(),bp:bp};p.r.gain.value=p.c.gain.value=0;s.connect(lp);lp.connect(p.r);s.connect(bp);bp.connect(p.c);p.r.connect(AU.fxg);p.c.connect(AU.fxg);s.start();}
  var a=pneuAlvo(c),k=Math.min(1,dt*10),sc=c===C0?loopGain('pneu-cantando',AU.fxg,'pneu-c0'):null;p.r.gain.value+=(a.rol*vol-p.r.gain.value)*k;p.c.gain.value+=(a.chi*vol*MIX.pneu*(sc?.35:1)-p.c.gain.value)*k;
  if(sc){sc.g.gain.value+=(Math.min(1.2,a.chi*2.6)*vol*MIX.pneu-sc.g.gain.value)*k;sc.s.playbackRate.value=.85+a.chi*.4;} /* CEO 06/11 'pneu cantando': gravacao real por cima do chiado sintetico */p.bp.frequency.value=a.f;}
/* mistura alvo do som de rua (pura, testada no selftest): motor da viatura e camadas de ambiente */
var AMB={pas:.32,cri:.16,bur0:.05,burN:.035,burMax:.32,dentro:.18,carro:.55};
function ambAlvo(o){
  var av=Math.abs(isFinite(o.v)?o.v:0),fora=o.silencio?0:o.indoor?AMB.dentro:o.inCar?AMB.carro:1,n=Math.max(0,o.gente|0);
  return {mGain:o.run?.75+Math.min(1.65,av*.07):0,mRate:o.rpm>0?clamp(.8+(o.rpm-800)*.00045,.8,2.1):Math.min(2.1,.8+av*.05), /* CEO 04/11 'cadê o punch': alto e grave */
    pas:AMB.pas*fora,cri:AMB.cri*fora,bur:o.silencio?0:Math.min(AMB.burMax,AMB.bur0+n*AMB.burN)*(o.indoor?.7:o.inCar?AMB.carro:1),
    chuva:NM.somChuva?nmSomAlvo(o):NM_SOM_SECO,indoor:!!o.indoor,silencio:!!o.silencio};
}
/* quantas pessoas a ate 14 m: burburinho cresce com a rua cheia */
function gentePerto(){var r=S.inCar?C0:P,n=0;for(var i=0;i<NPCS.length;i++){var q=NPCS[i];if(!q.down&&q.m&&q.m.visible!==false&&Math.abs(q.x-r.x)<14&&Math.abs(q.z-r.z)<14)n++;}return n;}
/* marcha (CEO 06/11): rotacao sobe dentro da marcha e cai na troca; 4 marchas como o Fusca */
var MARCHAS=[0,4,9,15,22];
var UNO_SOM=.55;
/* CEO 10/11 01h29 'ta muito alto o barulho, o volume geral... equalizacao profissional': todos os motores -3 dB e sem chiado acima de 4,2 kHz; moto e Fusca de rua mais 3 dB abaixo e moto sem giro agudo. Musica nao entra aqui (CEO: 'nao vai abaixar a musica da cena final'). */
var MIX={motor:1.7,corte:4200,moto:.26,motoGiro:.85,fuscaDentro:.2,fuscaFora:.3,batida:.5,pneu:.4,arranca:.8};
/* CEO 10/11 01h34 'barulho de batida, barulho de pneu ta irritando... equalizar igual um GTA de verdade': batida -6 dB, pneu cantando/freada/arrancada -8 dB, num ponto so (smp) */
function mixSom(n){return /^(crash|muro|mureta|atropelo)/.test(n)?MIX.batida:/^(pneu-cantando|freada)/.test(n)?MIX.pneu:n==='arrancada'?MIX.arranca:1;}
function indiceMarcha(av){var g=0;while(g<MARCHAS.length-1&&av>=MARCHAS[g+1])g++;return g;}
function marcha(v){var av=Math.abs(v||0),g=indiceMarcha(av);var lo=MARCHAS[g],hi=MARCHAS[g+1]||lo+10,f=Math.min(1,(av-lo)/(hi-lo));
  return .78+g*.06+f*.62;}
/* NPC mais perto toca o motor de Fusca pela distancia (uma camada so, ponytail: um carro por vez; por carro se a perseguicao pedir) */
/* som de carro some na cutscene e com o jogador em subsolo/dentro de casa (motor da rua nao atravessa laje) */
function carroMudo(){return cenaOn()||S.phase==='cut';}
function carroOuve(){return S.inCar||!(P.y<-1||pisoEm(P));}
function fuscaNpc(dt){var l=loopGain('fusca-motor',AU.engBus||AU.fxg,'fusca-npc',1);if(!l)return;var r=camera.position,best=null,bd=3600;
  TRAF.forEach(function(n){if(n.oc!=null||n.len>5||n.m&&n.m.visible===false)return;var d=dist2(n.x,n.z,r.x,r.z);if(d<bd){bd=d;best=n;}});
  var f=S.fc;if(f&&f.on&&f.car&&f.car.visible&&dist2(f.x,f.z,r.x,r.z)<bd)best={x:f.x,z:f.z,sp:f.v};
  var e=best?esp(best.x,best.z,60):null,a=e&&carroOuve()?e.g*(S.inCar?MIX.fuscaDentro:MIX.fuscaFora):0;l.g.gain.value=a?l.g.gain.value+(a-l.g.gain.value)*Math.min(1,dt*4):0;if(best){l.s.playbackRate.value=marcha(best.sp);if(l.p)l.p.pan.value=e.pan;}}
/* ponytail: uma curva para todos os motores, cheia ate 3 m e muda no raio r; reutiliza as fontes existentes. */
var ESPV=new THREE.Vector3();
function esp(x,z,r){var dx=x-camera.position.x,dz=z-camera.position.z,d=Math.sqrt(dx*dx+dz*dz);camera.getWorldDirection(ESPV);var fl=Math.sqrt(ESPV.x*ESPV.x+ESPV.z*ESPV.z)||1;
  return {g:Math.pow(clamp(1-(d-3)/(r-3),0,1),2),pan:d<.8?0:Math.max(-.9,Math.min(.9,(-ESPV.z*dx+ESPV.x*dz)/(fl*d)))};}
/* camada em loop: nasce quando o arquivo chega, ganho 0, quem chama ajusta; k separa duas camadas do mesmo arquivo */
function loopGain(n,dest,k,pan){
  AU.loops=AU.loops||{};k=k||n;var l=AU.loops[k];if(l)return l;
  var b=AUDIO_EMBED[n];if(!b||!aok())return null;
  try{var s=AC.createBufferSource(),g=AC.createGain(),p=pan&&AC.createStereoPanner?AC.createStereoPanner():null;s.buffer=b;s.loop=true;g.gain.value=0;s.connect(g);if(p){g.connect(p);p.connect(dest);}else g.connect(dest);s.start(AC.currentTime,Math.random()*b.duration*.8);l=AU.loops[k]={s:s,g:g,p:p};}catch(e){return null;}
  return l;
}

/* ---------- overlays: decisao, questao, fim ---------- */
/* CEO 08/11 T3: tela de fim/decisao solta o ponteiro preso no canvas, senao o clique nao chega ao botao */
function uiSolta(b){try{if(document.pointerLockElement&&document.exitPointerLock)document.exitPointerLock();}catch(e){}if(b)try{b.focus({preventScroll:true});}catch(e){}}
function showDec(tag,title,text,opts,deathShown,mouse){hudClasseLimpa();
  if(mouse==null&&/FIM DE JOGO|FALHOU|VOCÊ CAIU/.test(tag))mouse=document.pointerLockElement===cv;
  if(/FIM DE JOGO|FALHOU/.test(tag)&&!deathShown){deathStart(function(){showDec(tag,title,text,opts,true,mouse);});return;}
  /* ORDEM 34: opcao com so:'ferramenta' so aparece para a classe que tem, marcada [PM] (estilo Streets of Rogue) */
  opts=opts.filter(function(o){return !o.so||PRO.ferramentas.indexOf(o.so)>=0;}).map(function(o){return o.so?Object.assign({},o,{t:'['+PRO.cargo+'] '+o.t,cls:((o.cls||'')+' pro').trim()}):o;});
  if(mouse)opts=opts.map(function(o){return Object.assign({},o,{fn:function(){o.fn();retomaMouse();}});});
  if(!S.dicaPro&&opts.some(function(o){return o.so;})){S.dicaPro=true;later(.4,function(){playSeq(DIALOGO.dicaPro);});}
  $('dtag').textContent=tag;$('dt').textContent=title;$('dx').textContent=text;
  var box=$('dopts');box.innerHTML='';
  opts.forEach(function(o,i){
    var b=document.createElement('button');b.type='button';b.className='b '+(o.cls||'');
    b.innerHTML='<span></span><small></small>';b.firstChild.textContent=(i+1)+'. '+o.t;b.lastChild.textContent=o.s||'';
    b.onclick=function(){if(S.phase==='ui'&&$('dec').classList.contains('on'))o.fn();};
    box.appendChild(b);
  });
  hudMolduras();hudConfirmacoes();S.decOpts=opts;S.phase='ui';$('dec').classList.add('on');
  uiSolta(opts.length===1?box.firstChild:null); /* ponytail: foco so com botao unico (retry); com escolhas, Enter da fala nao escolhe sem querer */
}
function closeDec(){hudClasseLimpa();$('dec').classList.remove('on');S.decOpts=null;}
function closeDecPlay(){closeDec();S.phase='play';}
function askQ(q,cb,tag,secs,trava){
  var m=(secs||15)+rpgAt('foco');QZ={q:q,cb:cb,t:m,max:m,done:false,ok:false,rapido:trava!=null,trava:trava||0,abre:performance.now()};
  $('qtag').textContent=tag||'QUESTÃO · CERTO OU ERRADO';$('qt').textContent=q.t;
  $('qres').style.display='none';$('qbtns').style.display='flex';$('qC').lastChild.textContent='{{qc}}';$('qE').lastChild.textContent='{{qe}}';$('qbar').style.transform='scaleX(1)';
  $('q').classList.add('on');S.phase='ui';
}
function ansQ(v){
  if(!QZ||QZ.done)return;
  if(v!==null&&performance.now()-QZ.abre<QZ.trava)return;QZ.done=true;var ok=(v===QZ.q.a);QZ.ok=ok;if(!ok)cadRegistra(QZ.q,$('qtag').textContent);
  if(ok){S.acertos++;gainXP(10);}else S.erros++;
  sfx(ok?'ok':'bad');
  $('qbtns').style.display='none';$('qres').style.display='block';
  var rv=$('qrv');rv.textContent=v===null?'TEMPO ESGOTADO':ok?'CERTO ✓ você acertou':'ERRADO ✗ não foi dessa vez';rv.style.color=ok?'var(--ok)':'var(--bad)';
  /* CEO 16/11: simulado da morte e rapidao; comentario so depois, no Start (Questoes que errei) */if(QZ.rapido){$('qexp').textContent=$('qsrc').textContent='';$('qOK').style.display='none';QZ.fbAte=performance.now()+300;var zq=QZ;setTimeout(function(){if(QZ===zq&&!$('opt').classList.contains('on'))closeQ();},300);}else{$('qOK').style.display='';$('qexp').textContent='Gabarito: '+(QZ.q.a?'CERTO':'ERRADO')+'. '+QZ.q.x;$('qsrc').textContent=QZ.q.src;}
}
function closeQ(){
  if(!QZ||!QZ.done)return;
  var z=QZ;QZ=null;$('q').classList.remove('on');S.phase='play';z.cb(z.ok);
}
