var LUTA_DISC={cnh:'CTB',alc:'CTB',cinto:'CTB',som:'CTB',sinal:'CTB',casa:'Constitucional',flag:'Processo Penal',maus:'Legislação'};
var QF=QB.map(function(q){return Object.assign({d:LUTA_DISC[q.id]||'Geral'},q);}).concat(QF_EXTRA);
// ponytail: todas as disciplinas da PRF misturadas; filtro por objetivo do aluno (?curso=) entra quando o banco tiver curso por item
var LUTA=null,LUTA_N=8,LUTA_SEG=10,LUTA_VENCE=6;
function lutaShuffle(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t;}return a;}
function lutaStart(done,n){
  n=n||LUTA_N;LUTA={qs:lutaShuffle(QUIZ_PRONTO?QUIZ_BANCO.filter(function(q){return q.dif==='facil'&&q.t.length<=170;}):QF).slice(0,n),i:0,t:LUTA_SEG,wait:0,ok:0,res:[],done:done||null,prev:S.phase,fim:false};
  S.phase='luta';$('luta').className='on cima';$('lres').classList.remove('on');$('lres').innerHTML='';lutaQ();
}
function lutaQ(){var q=LUTA.qs[LUTA.i];LUTA.t=LUTA_SEG;LUTA.wait=0;LUTA.q0=S.time;
  $('lq').textContent=q.t;$('ldisc').textContent=q.d.toUpperCase();$('lnum').textContent=(LUTA.i+1)+'/'+LUTA.qs.length;lutaAnel();}
function lutaAnel(){var f=clamp(LUTA.t/LUTA_SEG,0,1);$('lanel').style.strokeDashoffset=(314.16*(1-f)).toFixed(1);$('lanel').style.stroke=f<.3?'#ff3b2f':'#ffd34d';$('lseg').textContent=Math.ceil(LUTA.t);}
function lutaVida(){return Math.max(0,100-LUTA.ok*100/LUTA_VENCE);}
function lutaAns(v){
  if(!LUTA||LUTA.fim||LUTA.wait>0)return;
  var q=LUTA.qs[LUTA.i],hit=v===q.a;if(!hit)cadRegistra(q,'Luta');
  LUTA.res.push({q:q,v:v,hit:hit,s:S.time-LUTA.q0});
  if(hit){LUTA.ok++;S.acertos++;}else S.erros++;
  sfx(hit?'soco':'bad');
  $('luta').className='on '+(hit?'cima':'baixo');$('lvida').style.width=lutaVida()+'%';
  var p=$('lpop');p.textContent=hit?'PÁ!':(v===null?'LENTO!':'ERROU!');p.style.color=hit?'#ffd34d':'#ff5a4a';p.classList.remove('v');void p.offsetWidth;p.classList.add('v');
  LUTA.wait=.55;
}
function lutaNext(){LUTA.i++;if(LUTA.i>=LUTA.qs.length)lutaEnd();else lutaQ();}
function lutaTick(dt){
  if(!LUTA||LUTA.fim||S.phase!=='luta')return;
  if(LUTA.wait>0){LUTA.wait-=dt;if(LUTA.wait<=0){LUTA.wait=0;lutaNext();}return;}
  LUTA.t-=dt;lutaAnel();if(LUTA.t<=0){LUTA.t=0;lutaAns(null);}
}
function lutaEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function lutaEnd(){
  LUTA.fim=true;var n=LUTA.qs.length,ok=LUTA.ok,win=ok>=LUTA_VENCE,pct=Math.round(ok*100/n);
  var tm=LUTA.res.reduce(function(a,r){return a+r.s;},0)/n,rk=pct>=100?'S':pct>=85?'A':pct>=70?'B':pct>=40?'C':'D';
  var h='<h1>'+(win?'VITÓRIA!':'ELE ESCAPOU')+'</h1><div class="sub">'+(win?'BANDIDO DOMINADO':'TREINA E VOLTA MAIS FORTE')+'</div>'+
    '<div class="st"><div>ACERTOS<b>'+ok+'/'+n+'</b></div><div>TEMPO MÉDIO<b>'+tm.toFixed(1)+'s</b></div><div>NOTA<b>'+rk+'</b></div></div>';
  LUTA.res.forEach(function(r,k){h+='<div class="it'+(r.hit?'':' x')+'"><div class="h">'+(k+1)+' · '+lutaEsc(r.q.d.toUpperCase())+' · '+(r.hit?'ACERTOU':r.v===null?'TEMPO':'ERROU')+' · GABARITO '+(r.q.a?'CERTO':'ERRADO')+'</div>'+lutaEsc(r.q.t)+'<div class="p">'+lutaEsc(r.q.x)+'</div></div>';});
  h+='<button class="go" id="lGo">CONTINUAR</button>';
  $('lres').innerHTML=h;$('lres').classList.add('on');$('lres').scrollTop=0;$('luta').scrollTop=0;$('lGo').onclick=lutaClose;
  if(win)gainXP(10*ok);
}
function lutaClose(){if(!LUTA)return;var z=LUTA;LUTA=null;$('luta').className='';S.phase=z.prev==='luta'?'play':(z.prev||'play');if(z.done)z.done(z.ok,z.res);}
$('lC').onclick=function(){lutaAns(true);};$('lE').onclick=function(){lutaAns(false);};
addEventListener('keydown',function(e){if(!LUTA)return;var k=e.key.toLowerCase();
  if(LUTA.fim){if(k==='enter'||k===' ')lutaClose();return;}
  if(k==='1'||k==='c'||k==='arrowleft')lutaAns(true);else if(k==='2'||k==='e'||k==='arrowright')lutaAns(false);});
function drawQ(){
  if(QUIZ_PRONTO){var qb=quizEscolhe(1,'facil',170)[0];if(qb)return qb;}
  var pool=QB.filter(function(q){return q.id!=='maus'&&q.id!=='casa'&&S.qUsed.indexOf(q.id)<0;});
  if(!pool.length){S.qUsed=[];pool=QB.filter(function(q){return q.id!=='maus'&&q.id!=='casa';});}
  var q=pool[Math.floor(Math.random()*pool.length)];S.qUsed.push(q.id);return q;
}
