/* Mesmos passos de 5% no desktop. Entre as escalas, o navegador já pode desenhar o próximo quadro. */
function* gojEscalas(o){
  var col=o.querySelector('.gjcol'),kids=[o.querySelector('#gojMain'),o.querySelector('#gojSide')];
  if(o.ownerDocument.defaultView.getComputedStyle(col).overflowY==='auto')return;
  function escala(i){for(var e of kids)e.style.zoom=String(i/20);}
  var lo=5,hi=20;
  while(lo<hi){var m=Math.ceil((lo+hi)/2);escala(m);yield;
    if(col.scrollHeight<=col.clientHeight+1&&col.scrollWidth<=col.clientWidth+1)lo=m;else hi=m-1;}
  escala(lo);
}
function gojFit(o,preparo){
  if(preparo&&preparo.pronto&&preparo.w===innerWidth&&preparo.h===innerHeight)return;
  // Salto de cena imediato, troca de tamanho ou inspeção de uma cópia fora do jogo.
  for(var passo of gojEscalas(o)){}
}
