  var fx=((KEYS.KeyD||KEYS.ArrowRight)?1:0)-((KEYS.KeyA||KEYS.ArrowLeft)?1:0),fy=((KEYS.KeyW||KEYS.ArrowUp)?1:0)-((KEYS.KeyS||KEYS.ArrowDown)?1:0);
