  if(e.code==='Escape'&&e.isTrusted&&S.soco&&quizCancela()){e.preventDefault();return;}
  if($('gojor').classList.contains('on')&&(e.code==='Enter'||e.code==='Space')){e.preventDefault();$('gojRe').click();return;}
  KEYS[e.code]=true;audioInit();
  if(['Enter','Space','KeyE','KeyC'].indexOf(e.code)>=0&&questFala(e.code==='KeyE')){e.preventDefault();return;}
  if(S.phase==='cut'){if(e.code==='Escape')skipPede();else if(e.code==='Enter'||e.code==='Space'||e.code==='KeyE'||e.code==='KeyC')act.nextLine();return;}
  if(S.fcCena){if(e.code==='Escape')skipPede();else if(['KeyA','KeyE','Enter','Space','KeyC'].indexOf(e.code)>=0)skipSub();e.preventDefault();return;}
  if(S.phase==='play'&&cenaOn()){if(e.code==='Enter'||e.code==='Space'||e.code==='KeyE'||e.code==='KeyC'){skipSub();e.preventDefault();}if(e.code!=='KeyM'&&e.code!=='Escape')return;}/* conversa: nada de pular, agachar, sacar arma, sirene ou giro no meio da fala (Cyberpunk/GTA: cena manda) *//* CEO 08/11 "nao passa o dialogo com A, com B": conversa cara a cara passa com Espaco/Enter/E/C = A, B e X do controle */
  if(QZ&&!QZ.done){if(e.code==='Digit1')ansQ(true);else if(e.code==='Digit2')ansQ(false);return;}
  if(QZ&&QZ.done){if(e.code==='Enter'||e.code==='Space'||e.code==='KeyE')closeQ();return;}
  if(S.phase==='ui'&&S.decOpts){var n=parseInt(e.key,10);if(n>=1&&n<=S.decOpts.length)S.decOpts[n-1].fn();return;}
  if(S.inCar&&(e.code==='BracketLeft'||e.code==='BracketRight')){radioEscolhe(e.code==='BracketLeft'?-1:1);return;}
  if(e.code==='Space')act.jump();else if(e.code==='KeyE')act.interact();else if(e.code==='KeyR'){if(!PAD_DISPATCH&&!S.inCar&&CB.drawn)reload();else act.funk();}else if(e.code==='KeyG')act.giro();else if(e.code==='KeyH')act.sirene();else if(e.code==='KeyV')act.camIn();else if(e.code==='KeyJ')pazPassa();
  else if(e.code==='KeyC'&&!lifeActive())P.crouch=!P.crouch;
  else if(e.code==='KeyM')act.mute();else if(e.code==='KeyF'){if(!CB.drawn)draw(true);CB.aimHold=CB.drawn&&!CB.aimHold;}
