var NOTOUCH='.tb,.ov,#skip,#mute,#karma,button,#opt,#fimPop';/* CEO 09/11 18h30 'gente travada no menu de pause': toque dentro do menu e do menu (rola, mexe no som), nunca do jogo */
function tStart(e){
  if(LOADING||!e.changedTouches)return;
  for(var i=0;i<e.changedTouches.length;i++){
    var t=e.changedTouches[i];if(t.target.closest&&t.target.closest(NOTOUCH))continue;
    if(S.phase==='cut'){act.nextLine();break;}
    if(S.phase==='play'&&cenaOn()){skipSub();break;}/* CEO 07/11: no celular o toque passa a conversa, igual o clique no PC */
    if(S.phase!=='play'||cenaOn())continue;/* CEO 07/11: toque nao anda nem gira camera na cutscene */
    if(t.clientX<innerWidth*.5&&!JOY.on){JOY.on=true;JOY.id=t.identifier;JOY.ox=t.clientX;JOY.oy=t.clientY;JOY.x=0;JOY.y=0;
      var jb=$('jbase');jb.style.display='block';jb.style.left=t.clientX+'px';jb.style.top=t.clientY+'px';$('jknob').style.transform='translate(0,0)';}
    else if(t.clientX>=innerWidth*.5&&LK.id===null){LK.id=t.identifier;LK.x=t.clientX;LK.y=t.clientY;}
  }
  var allUI=true;for(var q=0;q<e.changedTouches.length;q++){var tg=e.changedTouches[q].target;if(!(tg.closest&&tg.closest(NOTOUCH)))allUI=false;}
  if(!allUI)e.preventDefault();
}
function tMove(e){
  if(!e.changedTouches)return;if(e.target&&e.target.closest&&e.target.closest('#opt,#fimPop'))return;/* CEO 10/11: tela do Pix rola no dedo */
  for(var i=0;i<e.changedTouches.length;i++){
    var t=e.changedTouches[i];
    if(JOY.on&&t.identifier===JOY.id){var dx=(t.clientX-JOY.ox)/46,dy=(t.clientY-JOY.oy)/46,m=Math.hypot(dx,dy);if(m>1){dx/=m;dy/=m;}JOY.x=dx;JOY.y=dy;$('jknob').style.transform='translate('+dx*46+'px,'+dy*46+'px)';}
    else if(t.identifier===LK.id){if(S.phase==='play'&&!cenaOn())lookBy((t.clientX-LK.x)*1.25,(t.clientY-LK.y)*1.25);LK.x=t.clientX;LK.y=t.clientY;}
  }
  e.preventDefault();
}
function tEnd(e){
  if(!e.changedTouches)return;
  for(var i=0;i<e.changedTouches.length;i++){
    var t=e.changedTouches[i];
    if(JOY.on&&t.identifier===JOY.id){correToque(false);JOY.on=false;JOY.id=null;JOY.x=0;JOY.y=0;$('jbase').style.display='none';}
    if(t.identifier===LK.id)LK.id=null;
  }
}
document.addEventListener('touchstart',tStart,{passive:false});document.addEventListener('touchmove',tMove,{passive:false});
document.addEventListener('touchend',tEnd);document.addEventListener('touchcancel',tEnd);

