var CAR=makeSUV();scene.add(CAR);sinaisReg(CAR,"viatura",-1,null);// Vista da calçada. A carroceria só abre as três áreas de vidro quando a cabine correspondente está perto.
// Agulha em relevo, no plano da escala original. Os dois painéis têm UV e graduação diferentes.
// A carcaça fica no lugar; face, aro e eixo usam a mesma correção de proporção.
var PROPORCAO_QUADRO=[.75,1.38];
function ponteiroViatura(pai,suv,rpm){
 var suporte=new THREE.Group(),eixo=new THREE.Group(),agulha=new THREE.Shape();
 var dx=suv?.394/(512*.98):.4/1024,dy=suv?.185/(512*.98):.133/384;
 suporte.position.set(suv?-.415:-.42,suv?1.366:1.365,suv?-.740:-.755);suporte.rotation.x=suv?-.13:-.2;
 var cx=suv?(rpm?132:384):(rpm?766:258);
 suporte.translateY((suv?256-274:192-205)*dy);
 if(suv){dx*=PROPORCAO_QUADRO[0];dy*=PROPORCAO_QUADRO[1];}
 suporte.translateX((cx-(suv?256:512))*dx);suporte.translateZ(suv?.021:.002);
 suporte.scale.set(dx,dy,1);pai.add(suporte);suporte.add(eixo);eixo.name=rpm?'agulha-rpm':'agulha-kmh';
 var aro=new THREE.Mesh(new THREE.TorusGeometry(.06,.0016,6,48),new THREE.MeshStandardMaterial({color:0x50575a,metalness:.42,roughness:.46}));
 aro.scale.set((suv?112:153)/.06,(suv?126:153)/.06,1);aro.position.z=suv?-.0019:-.0008;aro.name='aro-do-mostrador';soNoPrincipal(aro);suporte.add(aro);
 eixo.userData.zero=suv?Math.PI/2+2.02:-Math.PI*.72;eixo.userData.porUnidade=(suv?-4.04:-Math.PI*1.56)/(rpm?6000:suv?200:240);
 var r=suv?99:144,base=suv?16:12;agulha.moveTo(base,-3.5);agulha.lineTo(r,-.8);agulha.lineTo(r,.8);agulha.lineTo(base,3.5);agulha.closePath();
 eixo.add(new THREE.Mesh(new THREE.ExtrudeGeometry(agulha,{depth:.0008,bevelEnabled:false}),new THREE.MeshBasicMaterial({color:0xff6244,toneMapped:false})));
 eixo.rotation.z=eixo.userData.zero;return eixo;
}
function indicaMostrador(agulha,valor){if(agulha)agulha.rotation.z=agulha.userData.zero+valor*agulha.userData.porUnidade;}
function giroViatura(v,pedal){
 var av=Math.abs(v),g=indiceMarcha(av),fim=v<0?6:(MARCHAS[g+1]||32);
 var carga=clamp((v<0?-pedal:pedal)||0,0,1);
 // Conversor em marcha lenta; na ré há uma relação única, mesmo quando a velocidade passa dos 4 m/s.
 return Math.min(5200,Math.max(800,av/fim*3000)+carga*350);
}
// Uma moldura interna para as duas cabines (reserva e SUV). Montada uma vez; não participa do trânsito.
function revestimentoViatura(tecido,vinil){
  var pos=[],uv=[],indices=[],emendas=[];
  function faixa(n,m,fecha,ponto){
    var base=pos.length/3;
    for(var j=0;j<=m;j++)for(var i=0;i<=n;i++){
      var u=i/n,v=j/m,p=ponto(u,v);pos.push(...p);uv.push(fecha?u*.45:(p[0]+1)*4,fecha?v*1.5:p[2]*4);
      if(i<n&&j<m){var a=base+j*(n+1)+i;indices.push(a,a+1,a+n+1,a+1,a+n+2,a+n+1);}
    }
    if(fecha)for(var j=0;j<=m;j++)emendas.push([base+j*(n+1),n]);
  }
  // Frente enrolada do forro; as bordas descem até a guarnição das portas.
  var secoes=[[0,.020],[.014,.004],[.042,0],[.095,.010],[.22,.034],[.48,.055],[.83,.062],[1.32,.061],[1.74,.050],[2.08,.025]];
  faixa(24,secoes.length-1,false,function(u,v){
    var x=2*u-1,l=Math.pow(Math.abs(x),3),q=secoes[Math.round(v*(secoes.length-1))];
    return [x*.975,1.923+q[1]-.058*l,-.90+.16*l+q[0]];
  });
  // Dobra lateral real, da face do teto até a vedação acima das portas.
  [-1,1].forEach(function(s){faixa(4,secoes.length-1,false,function(u,v){
    var q=secoes[Math.round(v*(secoes.length-1))],a=u*Math.PI/2;
    return [s*(.935+.040*Math.cos(a)),1.923+q[1]-.058-.075*Math.sin(a),-.74+q[0]];
  });});
  var fimForro=indices.length;[-1,1].forEach(function(s){
    // A base é mais larga; o topo dobra para trás e entra no forro antes de acabar.
    var eixo=new THREE.CubicBezierCurve3(new THREE.Vector3(s*.931,1.245,-1.143),new THREE.Vector3(s*.925,1.48,-1.118),new THREE.Vector3(s*.892,1.901,-.835),new THREE.Vector3(s*.866,1.944,-.59));
    faixa(32,12,true,function(u,v){
      var c=eixo.getPoint(v),d=eixo.getTangent(v),a=u*Math.PI*2,h=Math.hypot(d.y,d.z),r=(.058-.022*Math.sin(Math.PI*v))*(-Math.sin(a));
      return [c.x+(.057-.021*Math.sin(Math.PI*v))*Math.cos(a),c.y-r*d.z/h,c.z+r*d.y/h];
    });
  });
  // Coluna B oval fechada, encaixada sob a curva do teto.
  [-1,1].forEach(function(s){faixa(32,4,true,function(u,v){
    var a=u*Math.PI*2;return [s*.948+.047*Math.cos(a),1.30+.565*v,.42+.070*Math.sin(a)];
  });});
  var g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();
  var n=g.attributes.normal;emendas.forEach(function(e){var a=e[0],b=a+e[1],x=n.getX(a)+n.getX(b),y=n.getY(a)+n.getY(b),z=n.getZ(a)+n.getZ(b),k=1/Math.hypot(x,y,z);n.setXYZ(a,x*k,y*k,z*k);n.setXYZ(b,x*k,y*k,z*k);});
  g.addGroup(0,fimForro,0);g.addGroup(fimForro,indices.length-fimForro,1);
  var o=new THREE.Mesh(g,[tecido,vinil]);o.name='revestimento-para-brisa';return o;
}

// Mesmo atlas e mesmos triângulos da frente vista da rua. Só o índice muda; nenhum desenho por cima da lataria.
function encaixeCabineSUV(){return new THREE.Matrix4().makeTranslation(0,.245,-.61).scale(new THREE.Vector3(.92,.80,.91));}
function capoDaLataria(base,cab,casco){
 var g=casco.geometry,pos=g.attributes.position,idx=g.index,ids=[],v=new THREE.Vector3();
 base.updateWorldMatrix(true,true);var rel=base.matrixWorld.clone().invert().multiply(casco.matrixWorld);
 // No GLB da viatura a frente é -X; a junção do capô com o para-brisa fica em x=-.58.
 var frente=new Uint8Array(pos.count);
 for(var i=0;i<pos.count;i++){v.fromBufferAttribute(pos,i);frente[i]=v.x<-.575&&v.y<.081&&v.y>-.115;}
 for(var i=0;i<(idx?idx.count:pos.count);i+=3){var a=idx?idx.getX(i):i,b=idx?idx.getX(i+1):i+1,c=idx?idx.getX(i+2):i+2;if(frente[a]&&frente[b]&&frente[c])ids.push(a,b,c);}
 if(!ids.length)return;
 var painel=new THREE.BufferGeometry();Object.keys(g.attributes).forEach(function(k){painel.setAttribute(k,g.attributes[k]);});painel.setIndex(ids);
 var capo=new THREE.Mesh(painel,casco.material);capo.name='capo';capo.receiveShadow=true;capo.matrixAutoUpdate=false;capo.matrix.copy(encaixeCabineSUV()).invert().multiply(rel);cab.add(capo);
}
// O vidro pode virar dois pedaços na dobradiça. O recorte por UV serve para ambos.
function fumeLateralRonda(mat){
 var mt=mat.clone();mt.customProgramCacheKey=function(){return 'vidro-dianteiro-ronda';};
 mt.onBeforeCompile=function(sh){sh.uniforms.rondaVidro=RONDA.vidro;
  sh.vertexShader='varying float vAlturaVidro;\n'+sh.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvAlturaVidro=uv.y;');
  sh.fragmentShader='uniform float rondaVidro;varying float vAlturaVidro;\n'+sh.fragmentShader.replace('#include <clipping_planes_fragment>','#include <clipping_planes_fragment>\nif (vAlturaVidro>1.-rondaVidro) discard;');};
 return mt;
}
