function reparaFrota(){TRAF.concat(PCARS).forEach(function(v){var c=v.m&&v.m.getObjectByName('carro-classico'),antiga=c&&c.userData.amassa0;if(!antiga||!antiga.isBufferGeometry)return;var usada=c.geometry;c.geometry=antiga;delete c.userData.amassa0;usada.dispose();});}
