  var geo=m.geometry,rel=new THREE.Matrix4().multiplyMatrices(inv,m.matrixWorld),keys=Object.keys(geo.attributes).filter(function(k){return !/^skin/.test(k);}),packs=[[],[],[]],ix=geo.index,n=ix?ix.count:geo.attributes.position.count,changed=false;
