  if(!force&&TP.m)sequenciaComeca(-1);P.y=surfaceY(P.x,P.z);P.vy=0;if(TP.m&&TP.mx&&TP.a.Idle_3){var xt=TP,xo=xt.a[xt.cur];if(xo&&xo!==xt.a.Idle_3)xo.stop();xt.a.Idle_3.reset().setEffectiveWeight(1).play();xt.cur='Idle_3';xt.aim=0;xt.m.position.set(P.x,P.y+(xt.oy||0),P.z);xt.m.rotation.y=Math.atan2(B.position.x-P.x,B.position.z-P.z);xt.mx.update(0);}L.yaw=C0.yaw+L.yaw;L.pitch=0;C0.v=0;C0.sl=0;S.inCar=false;S.radioUlt=S.stn;S.funk=false;S.sir=false;S.stn=-1;trkWant(null);radioJingleStop();pkReset();
  if(S.uno)unoSai();
