  if(!smpE('botina-'+piso+'-'+n,vol*(agua?.70:1),.96+.10*peso,lado*.09))nburst(250,.8,.08,vol*.13,0,'lowpass');
  if(agua&&!smpE('botina-agua-'+n,vol*(.38+.36*peso),1.1-.15*peso,lado*.09))nburst(1150,.8,.12,vol*.12,0,'bandpass',420);
