      for(var i=0;i<marcas.length;i++){var t=marcas[i];if(reverso?(fase<ant?t<ant&&t>=fase:t<ant||t>=fase):(fase>ant?t>ant&&t<=fase:t>ant||t<=fase))lado=i%2?1:-1;}
