function pipaMoto(dt){
  var b=S.pipa,m=PIPA.M.moto,w=m.userData;
  if(b.st!=='moto'&&b.st!=='sai')return;
  transitBuild();var speed=b.st==='sai'?9:6,cap=transitLimit(m,-1,0,speed,dt);transitReact(m,dt);
  b.presoT=cap<.5?(b.presoT||0)+dt:0;if(b.presoT>8)cap=speed;/* 09/11: moto do roteiro presa no transito sorteado travava a missao da pipa (1 falha na bateria: 225 s parada). Depois de 8 s presa ela segue assim mesmo. */
  if(m.trafficWait>4){var side={x:m.position.x,z:m.position.z+dt*1.8};
    if(!pushCircle(side,.5,COL)&&transitLimit(m,0,1,1.8,dt)>=1.8)m.position.z=side.z;}
  if(b.st==='moto'){
    m.position.x=Math.max(PIPA.mOut[0],m.position.x-cap*dt);w.wf.rotation.x-=dt*cap/.3;w.wr.rotation.x-=dt*cap/.3;
    if(m.position.x<=PIPA.mOut[0]){b.st='fala';sfx('moto');later(.35,function(){sfx('moto');});
      var fala=DIALOGO.pp8.slice();if(b.op===2)fala[1]=DIALOGO.pp8c[0];
      playSeq(DIALOGO.pp7.concat(fala),function(){b.lock=false;b.st='sai';});}
    return;
  }
  if(b.st==='sai'){m.position.x-=cap*dt;w.wf.rotation.x-=dt*cap/.3;w.wr.rotation.x-=dt*cap/.3;
    if(m.position.x<PIPA.mFim[0]){m.visible=false;pipaFim();}}
}
function pipaTick(dt){
  var b=S.pipa,k=NPCBY.kaua,c=NPCBY.cidap;b.t+=dt;
  if(b.st==='cal'){
    if(!S.inCar&&nearNPC('cidap',4)&&!seqBusy()){b.st='b1';b.lock=true;P.vx=P.vz=0;c.face=P;cenaFoco(c,true);
      playSeq(DIALOGO.pp1,function(){b.lock=false;S.falante=null;b.st='sobe';b.still=0;c.face={x:k.x,z:k.z};setObj('Suba na laje do Kauã.');setMark([PIPA.laje[0],PIPA.lajeY+2,PIPA.laje[1]],pipaRota());});}
    return;
  }
  if(b.st==='sobe'){
    b.still=Math.hypot(P.vx||0,P.vz||0)<.2?b.still+dt:0;
    if(b.still>10&&!b.hint){b.hint=true;say('Suba pelas caixas ao lado da casa. Use {{pulo}} em cada degrau.','sys');}
    if(P.alt>3&&nearNPC('kaua',3)&&!seqBusy()){b.up=true;b.st='b2';b.lock=true;P.vx=P.vz=0;k.face=P;cenaFoco(k,true);
      playSeq(DIALOGO.pp2,function(){b.lock=false;S.falante=null;b.st='pega';k.face={x:PIPA.fio[0],z:PIPA.fio[1]};setObj('Pegue a pipa no fio.');setMark([PIPA.fio[0],PIPA.fio[2]+1,PIPA.fio[1]]);});}
    return;
  }
  if(b.st==='pega'){
    if(P.alt<.5&&!S.inCar&&!seqBusy()){P.x=PIPA.escada[0];P.z=PIPA.escada[1];pkReset();P.vx=P.vz=0;P.y=groundY(P.x,P.z);
      if(!b.caiu){b.caiu=true;playSeq(DIALOGO.pp2b);}b.st='sobe';b.still=0;}
    return;
  }
  if(b.st==='esc')return;
  pipaMoto(dt);
}
