  if(S.toinhoTipo==='nenhum'){S.toinhoTipo=null;t.m.visible=false;t.down=true;return t;}/* selftest antigo: galpao sem Toinho */
  t.kind=S.toinhoTipo;t.hp=SBHP[t.kind];t.down=t.surrendered=t.fly=false;t.hold=true;t.mode='idle';t.yaw=Math.PI/2;t.m.visible=true;t.name=t.kind==='bandido'?'Bandido':'Toinho';cap2Place(t,TOINHO);
  if(t.kind==='bandido'){S.toinhoB={n:t,cd:1.2,ag:false,lost:0,andar:true,mf:t.m.userData.gun?t.m.userData.gun.children[1]:sbxArm(t),mft:0};SBB.push(S.toinhoB);}
