function profSenta(n,carregando){
  var u=n.m.userData,G=u.gl;if(G&&G.profPose){G.profPose.forEach(function(p){p.b.quaternion.copy(p.q);});G.profPose=null;}n.profRise=null;if(!carregando)n.profSit=null;n.m.position.y=n.y;if(!G)return;G.s.position.y=G.baseY+PROF_LIFT;/* sofa-professor */
  var a=G.a.Sitting;if(a){G.mx.stopAllAction();G.cur='Sitting';a.reset().play();a.stopFading();a.setEffectiveWeight(1);a.time=a.getClip().duration;a.paused=true;G.mx.update(0);}
}
/* Primeiro contato: mesmas falas e cenaSeq, direcao e silencio ficam fora do texto. */
function profTemModelo(ch){var u=ch.m.userData;return !!(u.gl&&u.fc&&u.fc.head);}
function profContato(ch,done){
  var espera=S.profPending,pronto=profTemModelo(ch);
  if(!pronto&&!espera){S.profPending={n:ch,done:done,ate:S.time+2,heroi:P1.visible,ator:ch.m.visible};cenaTrava(ch);P1.visible=ch.m.visible=false;return;}
  if(espera){P1.visible=espera.heroi;ch.m.visible=pronto&&espera.ator;}
  S.profPending=null;P.arc=P.mt=null;P.vy=0;ch.sit=true;profSenta(ch);var yp=yawTo(P.x-CHEFE[0],P.z-CHEFE[1]);ch.yaw=PROF_SOFA_YAW;cap2Place(ch,CHEFE);ch.profSit=[ch.x,ch.z,ch.yaw,yp];/* sofa-professor: sentado olha a frente do sofa */
  ch.m.updateMatrixWorld(true);var eye=pronto?ch.m.userData.fc.head.getWorldPosition(new THREE.Vector3()):new THREE.Vector3(ch.x,ch.y+1.32,ch.z);eye.y+=.08;
  S.profCena={eye:eye,n:ch,semModelo:!pronto,atorVisivel:espera?espera.ator:ch.m.visible,plano:'entrada',i:-1,heroParent:P1.parent,heroScale:P1.scale.clone(),heroPos:P1.position.clone(),heroRot:P1.rotation.clone(),heroVisible:P1.visible,axis:new THREE.Vector3(P.x-ch.x,0,P.z-ch.z).normalize(),hero:new THREE.Vector3(P.x,P.y,P.z),yaw:ch.yaw};
  P1.visible=false;
  var gazeYaw=L.yaw,gazePitch=L.pitch;cenaSeq(ch,DIALOGO.chefe,function(){profFim();if(done)done();});L.yaw=gazeYaw;L.pitch=gazePitch;
  SEQ.next=Math.max(SEQ.next,S.time+.85);profCamera(0);
}
function profFim(){var p=S.profPending;if(p){P1.visible=p.heroi;p.n.m.visible=p.ator;S.profPending=null;}var q=S.profCena;if(!q)return;
  if(q.semModelo){/* Ao devolver o controle, não revelar o substituto. O modelo tardio entra como filho novo. */
    if(!profTemModelo(q.n))q.n.m.children.forEach(function(o){o.visible=false;});q.n.m.visible=q.atorVisivel;}
  q.heroParent.add(P1);P1.position.copy(q.heroPos);P1.rotation.copy(q.heroRot);P1.scale.copy(q.heroScale);P1.visible=q.heroVisible;if(P1.userData.gl)glPlay(P1.userData,'Sitting');S.profCena=null;}
function profPlano(l){
  var q=S.profCena;if(!q)return;var i=DIALOGO.chefe.indexOf(l);if(i<0)return;
  if(q.semModelo&&profTemModelo(q.n)){q.semModelo=false;q.n.m.visible=q.atorVisivel;q.n.m.userData.fc.head.getWorldPosition(q.eye);q.eye.y+=.08;}
  q.i=i;q.plano=l.quem==='Você'?'contra':i===8?'revelacao':i>=12?'levanta':'professor';q.shot=null;
  if(i===12&&q.n.sit){var u=q.n.m.userData,G=u.gl;q.n.sit=false;q.n.profRise=S.time;if(G){glPlay(u,'Idle');if(G.a.Sitting)G.a.Sitting.fadeOut(1.8);G.a.Idle.fadeIn(1.8);}}
  if(i===12&&Q34E.on&&S.step==='dentro'){/* Pipoca sai do quadro enquanto a camera olha o Professor. */
    pipocaNaLaje(true);
  }
  profCamera(0); /* establish the cut before say() dispatches faceSay to the visible hero */
}
/* ponytail: one eye-level camera for both conversations. Only the gaze and lens move. */
/* BEGIN CENAS DIRECAO 11/11: dados de assunto, mesma regra para todos os planos. */
function cenaCabeca(m){
  m.updateWorldMatrix(true,true);var u=m.userData,f=u.fc;
  if(f&&f.fit)return f.fit.box.clone().applyMatrix4(f.group.matrixWorld).expandByScalar(.04);
  // ponytail: para o cachorro, caixa conservadora inclui focinho e orelhas, inclusive no HD.
  if(u.hd||u.head){var h=u.hd&&u.hd.root.getObjectByName('Head')||u.head;
    if(h){var p=h.getWorldPosition(new THREE.Vector3());return new THREE.Box3(p.clone().addScalar(-.28),p.clone().addScalar(.28));}}
  var p=m.getWorldPosition(new THREE.Vector3()).add(new THREE.Vector3(0,1.6,0));
  return new THREE.Box3(p.clone().addScalar(-.3),p.clone().addScalar(.3));
}
function cenaPontos(assuntos){
  var pts=[];assuntos.forEach(function(m){var b=cenaCabeca(m);
    [b.min.x,b.max.x].forEach(function(x){[b.min.y,b.max.y].forEach(function(y){[b.min.z,b.max.z].forEach(function(z){pts.push(new THREE.Vector3(x,y,z));});});});});return pts;
}
function cenaEnquadra(assuntos,cam){
  cam=cam||camera;if(!assuntos.length)return;
  var pts=cenaPontos(assuntos);cam.updateMatrixWorld(true);
  // Área segura: 10% de margem lateral/superior e 24% embaixo para a fala existente.
  var limites={x:.8,top:.8,bottom:.52},tan=0;
  pts.forEach(function(p){var v=cam.worldToLocal(p.clone()),d=-v.z;
    if(d<=cam.near)return;
    tan=Math.max(tan,Math.abs(v.x)/(d*cam.aspect*limites.x),Math.abs(v.y)/(d*(v.y<0?limites.bottom:limites.top)));});
  cam.fov=Math.max(cam.fov,2*Math.atan(tan*1.025)*180/Math.PI);cam.updateProjectionMatrix();return pts;
}
function cenaAssunto(){
  if(S.finalCena){var q=S.finalCena;return [q.plano==='pipoca'?DOGM:(q.plano==='junior'?NPCBY.junior:q.plano==='joao'||q.plano==='porta'||q.plano==='final'?NPCBY.juca:NPCBY.marlene).m];}
  if(S.profCena){if(S.profCena.semModelo)return S.dogHideProf?[]:[DOGM];return [S.profCena.i===4?DOGM:S.profCena.n.m];}
  return [];
}
// Queima de arquivo dita em cena: a vitima reconhece o carro, o atirador da o motivo.
var FC_FALAS=[{id:'suplica',t:5.45,quem:'Fujão',texto:'Patrão, eu não falei nada!',dur:.75},
  {id:'ameaca',t:6.25,quem:'Atirador',texto:'Abriu o bico. Virou arquivo queimado.',dur:.95}];
function fcDirecaoFala(q,id){var l=FC_FALAS.filter(function(l){return l.id===id;})[0];
  if(l){clearSubs();say(l.texto,'npc',l.dur,l.quem,true);}}
// Plano aberto mostra o heroi no lugar dele; fora do plano, devolve o rig como estava.
function fcHeroiPlano(q,on){var u=P1.userData,h=q.heroi;
  if(on&&!h){h=q.heroi={parent:P1.parent,pos:P1.position.clone(),rot:P1.rotation.clone(),scale:P1.scale.clone(),vis:P1.visible,
      proc:u.proc?u.proc.map(function(o){return o.visible;}):null,hd:u.profMesh?u.profMesh.visible:null};
    scene.add(P1);P1.scale.setScalar(1);if(u.proc&&u.profMesh){u.proc.forEach(function(o){o.visible=false;});u.profMesh.visible=true;}if(u.gl)glPlay(u,'Idle');}
  if(on){P1.position.set(P.x,P.y,P.z);P1.rotation.set(0,yawTo(FC_CENA.x-P.x,FC_CENA.z-P.z),0);P1.visible=true;return;}
  if(!h)return;q.heroi=null;(h.parent||scene).add(P1);P1.position.copy(h.pos);P1.rotation.copy(h.rot);P1.scale.copy(h.scale);P1.visible=h.vis;
  if(h.proc)u.proc.forEach(function(o,i){o.visible=h.proc[i];});if(h.hd!=null)u.profMesh.visible=h.hd;if(u.gl)glPlay(u,'Sitting');}
/* END CENAS DIRECAO 11/11 */
function cenaOlhos(q,target,fov,dt){
  var eye=new THREE.Vector3(P.x,P.y+1.68,P.z);
  if(!q.gaze){q.gaze={yaw:L.yaw,pitch:L.pitch,fov:camera.fov,t:1};}
  var g=q.gaze;
  if(!q.shot||q.shot.aspect!==camera.aspect){
    var dx=target.x-eye.x,dz=target.z-eye.z;
    q.shot={aspect:camera.aspect,yaw:yawTo(dx,dz),pitch:Math.atan2(target.y-eye.y,Math.hypot(dx,dz)),fov:fov};
    var lens=new THREE.PerspectiveCamera().copy(camera,false);lens.position.copy(eye);lens.rotation.order='YXZ';lens.rotation.set(q.shot.pitch,q.shot.yaw,0);lens.fov=fov;
    cenaEnquadra(cenaAssunto(),lens);q.shot.fov=lens.fov;
    g.fromYaw=g.yaw;g.fromPitch=g.pitch;g.fromFov=g.fov;g.t=0;
  }
  g.t=Math.min(1,g.t+Math.max(0,dt||0)/.8);var e=g.t*g.t*(3-2*g.t),s=q.shot;
  /* Limit also covers low framerate and rapidly skipped dialogue. */
  var dy=dAng(g.yaw,g.fromYaw+dAng(g.fromYaw,s.yaw)*e),dp=g.fromPitch+(s.pitch-g.fromPitch)*e-g.pitch;
  var limit=Math.min(1,.12/(Math.hypot(dy,dp)||1));g.yaw+=dy*limit;g.pitch+=dp*limit;
  g.fov=g.fromFov+(s.fov-g.fromFov)*e;
  camera.position.copy(eye);camera.up.set(0,1,0);camera.rotation.order='YXZ';
  camera.rotation.set(g.pitch,g.yaw,0);L.yaw=g.yaw;L.pitch=g.pitch;
  if(camera.fov!==g.fov){camera.fov=g.fov;camera.updateProjectionMatrix();}
  P1.visible=PW.visible=VM.visible=false;
  document.body.classList.toggle('cena',!q.fim);return true;
}
function profCamera(dt){
  if(S.profPending){var pending=S.profPending;if(profTemModelo(pending.n)||S.time>=pending.ate)profContato(pending.n,pending.done);else return false;}
  var q=S.profCena;if(!q)return false;
  var n=q.n,u=P1.userData;
  /* ponytail: reuse the rig and Leon hair, never wait for the hero's optional HD asset. */
  if(q.plano==='contra'&&u.profMesh&&u.gl&&u.fc){
    if(!q.heroReady){
      scene.add(P1);P1.scale.setScalar(1);P1.position.copy(q.hero);
      P1.rotation.set(0,yawTo(n.x-q.hero.x,n.z-q.hero.z),0);
      var G=u.gl;G.mx.stopAllAction();G.cur='';glPlay(u,'Idle');
      G.a.Idle.stopFading().setEffectiveWeight(1);G.mx.update(0);q.heroReady=true;
    }
    P1.visible=u.profMesh.visible=true;u.proc.forEach(function(o){o.visible=false;});PW.visible=VM.visible=false;
    if(!q.contra||!q.shot||q.shot.aspect!==camera.aspect){
      P1.updateWorldMatrix(true,true);
      var h=u.fc.head.getWorldPosition(new THREE.Vector3()),a=q.axis,r=new THREE.Vector3(a.z,0,-a.x);
      /* Fixed eye-height reverse shot, on the same side of the dialogue axis. No orbit between speakers. */
      var pos=new THREE.Vector3(n.x,n.y+1.58,n.z).addScaledVector(a,-1.05).addScaledVector(r,.32);
      var target=new THREE.Vector3(q.hero.x,h.y+.025,q.hero.z).addScaledVector(r,camera.aspect<.7?-.055:-.23);
      var distance=pos.distanceTo(target),height=Math.max(.86,.56/camera.aspect);
      q.shot={aspect:camera.aspect,pos:pos,target:target,fov:2*Math.atan(height/(2*distance))*180/Math.PI};
    }
    camera.position.copy(q.shot.pos);camera.up.set(0,1,0);camera.rotation.order='YXZ';camera.lookAt(q.shot.target);camera.rotation.z=0;
    q.contra=true;camera.fov=q.shot.fov;camera.updateProjectionMatrix();cenaEnquadra([P1]);document.body.classList.add('cena');return true;
  }
  if(q.contra){q.shot=null;q.contra=false;}
  var target=q.eye.clone();
  if(!n.sit)target.set(n.x,n.y+1.6,n.z);
  target.y-=.2; /* eyes in the upper half, without moving the player's head position */
  /* Missing HD keeps the current first-person shot and the dialogue running. */
  if(q.i===4||q.semModelo&&!S.dogHideProf)target.set(DG.x,(isFinite(DG.y)?DG.y:surfaceY(DG.x,DG.z))+.4,DG.z);
  return cenaOlhos(q,target,(camera.aspect<.7?64:58)-(q.plano==='revelacao'?2:0),dt);
}

