function bailePortas(q){
  q.portas=[[],[],[]];q.geometrias=[];
  var meshes=[];q.car.traverse(function(o){if(o.isMesh&&o.geometry.attributes.uv)meshes.push(o);});
  meshes.forEach(function(o){
    var g=o.geometry,p=g.attributes.position;g.computeBoundingBox();var b=g.boundingBox,hw=(b.max.x-b.min.x)/2,cx=(b.max.x+b.min.x)/2,h=b.max.y-b.min.y,l=b.max.z-b.min.z,cz=(b.min.z+b.max.z)/2;
    if(h/l<.15)return;
    var indices=[[],[],[],[]],grupos=[[],[],[],[]],ix=g.index;
    (g.groups.length?g.groups:[{start:0,count:ix?ix.count:p.count,materialIndex:0}]).forEach(function(gr){
      var start=indices.map(function(a){return a.length;});
      for(var j=gr.start;j<gr.start+gr.count;j+=3){
        var a=ix?ix.getX(j):j,c=ix?ix.getX(j+1):j+1,d=ix?ix.getX(j+2):j+2,x=(p.getX(a)+p.getX(c)+p.getX(d))/3,y=(p.getY(a)+p.getY(c)+p.getY(d))/3,z=(p.getZ(a)+p.getZ(c)+p.getZ(d))/3,k=0;
        if(Math.abs(x-cx)>hw*.72&&y>b.min.y+h*.3&&y<b.min.y+h*.92&&z>cz-l*.29&&z<cz+l*.23){k=x>cx?(z>cz-l*.03?1:3):(z>cz-l*.03?2:0);}
        indices[k].push(a,c,d);
      }
      indices.forEach(function(a,i){if(a.length>start[i])grupos[i].push({start:start[i],count:a.length-start[i],materialIndex:gr.materialIndex});});
    });
    indices.forEach(function(idx,k){
      if(!idx.length)return;var geo=new THREE.BufferGeometry();Object.keys(g.attributes).forEach(function(n){geo.setAttribute(n,g.attributes[n]);});geo.setIndex(idx);grupos[k].forEach(function(gr){geo.addGroup(gr.start,gr.count,gr.materialIndex);});q.geometrias.push(geo);
      if(!k){o.geometry=geo;return;}
      var pivot=new THREE.Group(),side=k===2?-1:1,z=k===3?cz-l*.03:cz+l*.23,door=new THREE.Mesh(geo,o.material);
      pivot.position.set(cx+side*hw*.85,b.min.y+h*.3,z);door.position.copy(pivot.position).multiplyScalar(-1);door.castShadow=door.receiveShadow=true;pivot.add(door);o.add(pivot);q.portas[k-1].push(pivot);
    });
  });
}
