  if(q.pPara&&q.inicio!=null){var pk=sm(clamp((S.time-q.inicio)/1.65,0,1));P.x=q.pDe.x+(q.pPara.x-q.pDe.x)*pk;P.z=q.pDe.z+(q.pPara.z-q.pDe.z)*pk;}
