  var yaw=yawTo(tr[0]-P.x,tr[1]-P.z),pitch=Math.atan2(surfaceY(V.x,V.z)+1.35-camera.position.y,Math.hypot(tr[0]-P.x,tr[1]-P.z));
  L.yaw+=clamp(dAng(L.yaw,yaw),-Math.min(.06,dt*2.4),Math.min(.06,dt*2.4));
