/* CEO 07/11: depois do camburao surge do nada um cara que voce nao tinha visto e sai correndo; parkour atras dele, depois luta */
var FUGA_V=5.6,FUGA_PEGA=1.8,FUGA_SUBIDA=.55,FUGA_POUSO=.2;
/* CEO 07/11 "inquebravel": rota fixa mapeada no modo Deus (deus.info), trecho a trecho. t: run corre, climb sobe caixa, jump pula vao.
   h = topo do apoio acima do chao do baile (0 = chao). Termina no telhado da ultima casa do baile, canto sem saida. */
/* CEO 08/11 "volta ele pra pular pelos pallets, ele tava pulando bem": rota original pelas 4 pilhas de paletes */
var FUGA_PTS=[[74,0,55.8,'run'],[99.5,0,55.5,'run'],/* pe da 1a pilha (face z=56, corpo 0,4 m): 55,8 ficava dentro do raio e ninguem chegava */[99.5,2,57.5,'climb'],[99.5,4,60.5,'climb'],[99.5,6,63.5,'climb'],[99.5,8.22,66.5,'climb'],
  [96,8.22,66.5,'run'],[90.6,8.22,57.6,'run'],[90.6,8.7,56,'run'],[92,8.85,50,'run'],[95.5,9.1,43.4,'run'],[98,10.2,40.8,'jump'],[100,10.2,38.6,'run'],[100,10.2,34.3,'run']];
function fugaRota(){var g=BAILE.stage[1]-1;
  return FUGA_PTS.map(function(p){var h=p[1]?(supportH(p[0],p[2],99)||p[1]):0;return {p:[p[0],h?g+h:surfaceY(p[0],p[2]),p[2]],t:p[3]};});}
/* CEO 07/11 "mapear se e tudo possivel pro NPC executar": checa rota de parkour contra a colisao real (COL). Base do GPS dos bandidos.
   Para cada trecho amostra a cada 25 cm: run = sem parede acima do passo nem buraco embaixo; climb = degrau ate 2.4 m e ate 3.6 m de distancia;
   jump = vao ate 4.5 m, desnivel ate 1.6 m. Devolve lista de problemas (vazia = rota executavel). */
var NAV_CABECA=1.9;
function navTopo(x,z,yPe){var h=0,list=colJogador();for(var i=0;i<list.length;i++){var b=list[i]; /* como supportH, mas ignora o que passa por cima da cabeca (tabua, marquise) */
  if(b.ativo===false||b[4]===undefined||b[4]<=h||(b.minY!==undefined&&b.minY>yPe+NAV_CABECA))continue;if(x>b[0]-.2&&x<b[2]+.2&&z>b[1]-.2&&z<b[3]+.2)h=b[4];}return h;}
var NAV_PASSO=.35,NAV_DEGRAU=2.4,NAV_SUBIDA_D=3.6,NAV_VAO=4.5,NAV_DESNIVEL=1.6;
function navCheca(r,g){var ruim=[],hr=function(y){return Math.max(0,+(y-g).toFixed(2));};
  for(var i=1;i<r.length;i++){var a=r[i-1].p,b=r[i].p,t=r[i].t,ha=hr(a[1]),hb=hr(b[1]),L=Math.hypot(b[0]-a[0],b[2]-a[2]),n=Math.max(2,Math.ceil(L/.25)),dh=hb-ha,tag=i+' '+t+' ';
    if(t==='climb'){if(dh<=0||dh>NAV_DEGRAU)ruim.push(tag+'degrau '+dh.toFixed(2));if(L>NAV_SUBIDA_D)ruim.push(tag+'longe '+L.toFixed(1));continue;}
    if(t==='jump'){if(L>NAV_VAO)ruim.push(tag+'vao '+L.toFixed(1));if(Math.abs(dh)>NAV_DESNIVEL)ruim.push(tag+'desnivel '+dh.toFixed(2));}
    for(var j=1;j<n;j++){var k=j/n,x=a[0]+(b[0]-a[0])*k,z=a[2]+(b[2]-a[2])*k,h=ha+dh*k,top=navTopo(x,z,g+h),teto=h+(t==='jump'?4*clamp(.45+.13*L,.5,1.25)*k*(1-k):0)+NAV_PASSO;
      if(top>teto){ruim.push(tag+'parede '+top.toFixed(2)+' em '+x.toFixed(1)+','+z.toFixed(1));break;}
      if(t==='run'&&h>0&&top<Math.min(ha,hb)-.4){ruim.push(tag+'buraco em '+x.toFixed(1)+','+z.toFixed(1));break;}}}
  return ruim;}
/* CEO 08/11 "impossivel chegar onde o bandido chegou": vao de 3,6 m subindo 1,35 m nao cabe no pulo (0,97 m). Na beirada de um trecho 'jump' da rota,
   olhando pro outro lado, o pulo vira o mesmo arco do fujao ate o pouso. */
function pkAgVar(){var ag=1+(Math.random()*5|0);if(ag>=(pkAgVar.u||0))ag++;return pkAgVar.u=ag;} /* 6 sons de agarrar, nunca repete o anterior */
function pkPuloFuga(){if(CB.drawn)return null;var r=fugaRota(),fx=-Math.sin(L.yaw),fz=-Math.cos(L.yaw);
  for(var i=1;i<r.length;i++){if(r[i].t!=='jump')continue;var a=r[i-1].p,b=r[i].p,dx=b[0]-a[0],dz=b[2]-a[2],Lj=Math.hypot(dx,dz);
    if(Math.hypot(P.x-a[0],P.z-a[2])>2.6||Math.abs(P.y-a[1])>.9||(fx*dx+fz*dz)/Lj<.35)continue;
    var H=clamp(.45+.13*Lj,.5,1.25),a1=supportH(b[0],b[2],99);
    return {k:0,dur:Math.max(2*Math.sqrt(2*H/9.8),Lj/(FUGA_V*1.15)),x0:P.x,z0:P.z,a0:P.alt,x1:b[0],z1:b[2],a1:a1,H:H+Math.max(0,a1-P.alt)*.5};}
  return null;}
function fugaPilha(){QUEBRA.forEach(function(q){if(q.caiu&&q.b[0]===98.1){q.caiu=false;q.show();}});} /* pilha de caixas quebrada no tiro volta antes da largada */
