  n.hold=true;n.down=false;n.always=true;n.m.visible=true;n.yaw=-Math.PI/2;cap2Place(n,[x0,z0]);n.fuga=null; /* CEO 07/11: ja nasce na largada, de frente pro corredor do galpao, nunca cruza o mapa */
