  var yw=camera.rotation.y,pan=d>.5?clamp((dx*Math.cos(yw)-dz*Math.sin(yw))/d,-1,1)*.8:0,t=0;
  ns.forEach(function(k){var n='pipoca-'+k,r=.92+Math.random()*.16,b=AUDIO_EMBED[n];if(smp(n,g,r,pan,t))PSOM.src.push(AUDIO_EMBED.play.last);t+=(b?b.duration:1)/r+.08;});
  if(DOGM.userData.hd&&ns.some(function(k){return /^late/.test(k);}))DOGM.userData.hd.bark=.7;
