/*CUTSCENE-MOTOR-INI*/
/* CEO 13/11 regra 14: motor UNICO de cutscene guiado por dados (docs/visual/cutscene-motor.md). Cena de acao nova = 1 item em CUTSCENES, sem codigo novo.
   gatilho: passo da historia + ator + caixa do edificio [x0,z0,x1,z1] + altura do piso: dispara quando o heroi PISA no edificio onde o ator esta.
   video: mp4 em mvp/video/ (null = plano B). leve: mp4 do PS1 (null = PS1 cai no plano B). pausas: segundo do video em que entra a pergunta.
   fim.acao: como o mundo 3D fica quando o video acaba; fim.passo: passo em que a cena termina e o controle volta. planoB: a cena 3D de hoje. */
var CUTSCENES=[{id:'luta-bandido',gatilho:{passo:'fuga',ator:'fujao',caixa:SOCO_ROOF,piso:10.2},
  video:null,leve:null,fala:'q34topo',minigame:'telhado',pausas:[],
  fim:{acao:'posCacamba',passo:'fugacarro'},planoB:'q34Luta',durante:['topo34','soco34']}];
var CM_LENTO=.6,CM_ESPERA=3,CM_TQ=.34,CM_VID=null;/* CM_TQ: tela quebrando no maximo 1 a cada 0,34 s (<= 3 por segundo, regra do pisca) */
var CM_ACAO={q34Luta:q34Luta,posCacamba:cmPosCacamba};
function cmTrava(){var m=S.cm;return !!m&&(m.modo==='video'||m.c.durante.indexOf(S.step)>=0);}
function cmSrc(c){return BAT===2?c.leve:c.video;}
function cmPisou(g,n){var k=g.caixa;return !S.inCar&&!P.arc&&P.x>=k[0]&&P.x<=k[2]&&P.z>=k[1]&&P.z<=k[3]&&Math.abs(P.y-g.piso)<.35&&n.x>=k[0]-.5&&n.x<=k[2]+.5&&n.z>=k[1]-.5&&n.z<=k[3]+.5&&n.y>g.piso-.6;}
/* chamado 1x por quadro (update); true = a cena de video tem o quadro (missao parada) */
function cmTick(d){var m=S.cm;
  if(!m){for(var i=0;i<CUTSCENES.length;i++){var c=CUTSCENES[i],g=c.gatilho,n;if(S.step!==g.passo||!Q34E.on)continue;
      var src=cmSrc(c);if(src&&c.pre!==src){c.pre=src;cmVideo().src=src;CM_VID.load();}/* pre-carga quando a perseguicao comeca: a cena nao espera a rede */
      n=NPCBY[g.ator];if(n&&cmPisou(g,n)){cmInicia(c,n);return true;}}
    return false;}
  if(m.modo!=='video'){if(m.c.durante.indexOf(S.step)<0)S.cm=null;return false;}/* plano B: a cena de hoje roda; acabou quando sai dos passos dela */
  var v=CM_VID,p=m.c.pausas[m.pi];if(m.q)return true;
  if(!m.tocando){if(v.error||(m.espera+=d)>CM_ESPERA){cmPlanoB(m);return true;}/* regra 7: video nunca trava a cena */
    if(v.readyState>=3){m.tocando=true;v.muted=!(AU.unlocked&&AC&&AC.state==='running');var pr=v.play();if(pr&&pr.catch)pr.catch(cmFalhou);if(m.c.fala&&DIALOGO[m.c.fala])playSeq(DIALOGO[m.c.fala]);}
    return true;}
  if(v.error){cmFalhou();return true;}
  if(p){var falta=p.t-v.currentTime;v.playbackRate=falta<CM_LENTO?.25:1;if(falta<=0){v.pause();cmPergunta(m);}}
  else if(v.ended||v.duration>0&&v.currentTime>=v.duration-.05)cmFimVideo(m);
  return true;}
function cmInicia(c,n){if(n.fuga){n.fuga.r=null;n.fuga=null;}
  var m=S.cm={c:c,n:n,modo:'b',pi:0,qi:0,q:false,vida:SOCO_VIDA,espera:0,tocando:false,qs:null},src=cmSrc(c);
  if(src&&QUIZ_PRONTO)m.qs=questaoPara(c.minigame,c.pausas.length+SOCO_VIDA,95);
  if(!src||!m.qs||m.qs.length<c.pausas.length){cmPlanoB(m);return;}
  m.modo='video';S.step=c.durante[0];setMark(null);setObj('');cenaTrava(n);
  var v=cmVideo();if(c.pre!==src){c.pre=src;v.src=src;v.load();}else if(v.currentTime)v.currentTime=0;v.playbackRate=1;v.classList.add('on');}
function cmPlanoB(m){cmEsconde();m.modo='b';CM_ACAO[m.c.planoB](m.n);}
function cmFimVideo(m){cmEsconde();m.modo='b';CM_ACAO[m.c.fim.acao](m.n);}
function cmFalhou(){var m=S.cm;if(!m||m.modo!=='video'||m.q)return;if(m.pi)cmFimVideo(m);else cmPlanoB(m);}/* caiu antes da 1a pergunta = luta 3D; depois = pula pro fim */
function cmEsconde(){if(CM_VID){CM_VID.pause();CM_VID.classList.remove('on');}}
function cmVideo(){if(!CM_VID){var v=document.createElement('video');v.id='cmv';v.muted=true;v.defaultMuted=true;v.playsInline=true;v.setAttribute('playsinline','');v.setAttribute('webkit-playsinline','');v.setAttribute('aria-hidden','true');v.preload='auto';document.body.appendChild(v);CM_VID=v;}return CM_VID;}
function cmPergunta(m){m.q=true;var q=m.qs[m.qi++];
  if(!q||!quizRun({n:1,qs:[q],dif:'facil',tempo:SOCO_SEG,titulo:'LUTA · No alto do prédio',tema:'luta',npc:m.n,done:cmResposta}))cmResposta({right:1});}
function cmResposta(R){var m=S.cm;if(!m||m.modo!=='video')return;m.q=false;m.pi++;
  if(!R.right){cmDano();if(--m.vida<=0){cmGameOver(m);return;}}
  CM_VID.playbackRate=1;var pr=CM_VID.play();if(pr&&pr.catch)pr.catch(cmFalhou);}
function cmGameOver(m){cmEsconde();S.cm=null;gameOverJornal('','briga','',function(){cmInicia(m.c,m.n);});}
/* erro na luta (video ou plano B): o heroi nao faz o golpe; tela quebra + som de dano, a cena segue (regra 8) */
function cmDano(){telaQuebra();sfx('soco');sfx('grunhido',.9);CB.shake=Math.max(CB.shake||0,.45);}
/* efeito REAPROVEITAVEL: rachadura + tranco curto, 1 pico que so apaga; nunca mais de 3 por segundo (regra do pisca) */
function telaQuebra(){if(S.time-(S.tqT==null?-9:S.tqT)<CM_TQ)return false;S.tqT=S.time;S.tqN=(S.tqN||0)+1;
  var e=$('tq');if(!e){e=document.createElement('div');e.id='tq';e.setAttribute('aria-hidden','true');e.onanimationend=tqFim;document.body.appendChild(e);}
  e.classList.remove('on');void e.offsetWidth;e.classList.add('on');return true;}
function tqFim(){var e=$('tq');if(e)e.classList.remove('on');}
/* fim da luta em video: o ultimo quadro e os dois dentro da cacamba; o mundo 3D entra ali e segue o pos-cacamba de hoje (ele corre pro Fusca e foge) */
function cmPosCacamba(n){S.step='soco34';S.phase='play';n.fuga=null;n.hold=true;n.down=false;n.m.visible=true;FIST.visible=false;S.cena=true;S.falante=null;setObj('');setMark(null);
  S.soco={n:n,luta:true,hp:SOCO_CACAMBA,vida:SOCO_VIDA,qs:[],i:0,total:0,lado:1,right:0,wait:0,forma:'',fx:{hitStop:0,particles:0,sounds:0,vibrations:0,pain:0,special:0},
    queda:{t:1.5,px:P.x,pz:P.z,nx:n.x,nz:n.z,bateu:false,grito:1}};}
/*CUTSCENE-MOTOR-FIM*/
var FC_DK=2.5,FC_DMIN=20,FC_TRAS=.3,FC_COLA=1.1;/* CEO 09/11 'nao consigo ganhar do Fusca': batida vale 20 a 50 (era 6 a 40), traseira larga (pega canto), Fusca acelera so 10% com o jogador colado (era 35%) */
var FC_V=13,FC_PEGA=7,FC_SEG=1.2,FC_PERDE=150,FC_HP=100,FC_BATE=3.8,FC_VMIN=4,FC_CD=.8,FC_ESC_MAX=10,FC_R=6,FC_VIS=60;/* CEO 08/11: perder a escada batendo no Fusca NAO conta; game over so na 10a escada quebrada ('o cara fugiu'). FC_VIS: Fusca nunca fica mais longe que 60 m de quem joga *//* CEO 07/11 23h: Fusca com HP, toda batida que derruba a escada = missao escada, 3a perda = game over */
function fcPerto(path,x,z){var b=1e9,s0=0,s,q;for(s=0;s<path.len;s+=2){q=path.at(s);var d=dist2(q.x,q.z,x,z);if(d<b){b=d;s0=s;}}return s0;}
var FC_CAR=null;/* CEO 08/11: 3 Fuscas na rua apos reiniciar; o Fusca da fuga e UM so, reaproveitado em todo retry */
function fcModelo(){if(!FC_CAR){FC_CAR=new THREE.Group();ccSpawn(FC_CAR,0,{ci:5,dim:FC_DIM});/* CEO 13/11 (ni): classico laranja, caixa do modelo antigo */scene.add(FC_CAR);}return FC_CAR;}
function fcPrepara(path,s){var car=fcModelo();
  FCG=null;S.fc={car:car,path:path,s:s,on:false,v:FC_V,tranco:0,off:0,lv:0,dist:0,gps:null,perto:0,longe:0,hp:FC_HP,cd:0,perdas:0,esc:false};car.visible=true;fcPos();fcHud();}
function fcHud(){var f=S.fc,on=!!(f&&S.step==='fugacarro'&&f.on);$('fchp').style.display=on?'':'none';if(f){var t='Escada '+f.perdas+'/'+FC_ESC_MAX,e=$('fcesc');if(e.textContent!==t)e.textContent=t;}if(on)$('fchpi').style.width=Math.max(0,f.hp/FC_HP*100)+'%';}
/* CEO 09/11 21h2x "o Fusca nao ta perdendo a vida": o Fusca e solido e a colisao geral parava o Uno a 4,4 m do centro dele, mas o dano so valia abaixo de 3,8 m (FC_BATE):
   batida de verdade nunca tirava vida (medido no loop real: 6 batidas retas na traseira, de 12 a 45 m/s, 0 de dano). Agora vale encostar de verdade (30 cm de folga). */
function fcToca(f){var h=f&&f.car&&modelHitbox(f.car);if(!h)return false;var fx=-Math.sin(C0.yaw),fz=-Math.cos(C0.yaw);return [1.2,0,-1.2].some(function(k){return h.push({x:C0.x+fx*k,z:C0.z+fz*k},1.3);});}
/* CEO 09/11 21h3x (em live) "atirar no pneu do Fusca e ele parar de correr; se atirar no vidro, game over": o suspeito segue desarmado.
   Tiro a pe: parte de baixo do Fusca = pneu furado, ele para e se rende; cabine (vidros) = matou o suspeito, jornal do fujao; lataria = nada. */
var _fcRy=new THREE.Ray(),_fcP=new THREE.Vector3(),FC_PNEU=.45,FC_VIDRO=.58;
function fcFoiAlvo(){var f=S.fc,h=f&&f.on&&f.car.visible&&modelHitbox(f.car);return !!h&&BALA.veic&&BALA.col===h.col;}function fcTiro(eye,range,orig){var f=S.fc,h=f&&f.on&&S.step==='fugacarro'&&f.car.visible&&modelHitbox(f.car);if(!h)return '';
  if(orig)_fcRy.origin.copy(orig);else _fcRy.origin.set(P.x,eye,P.z);_fcRy.direction.copy(_td);_fcRy.applyMatrix4(h.inv);if(!_fcRy.intersectBox(h.box,_fcP))return '';
  var ny=(_fcP.y-h.box.min.y)/((h.box.max.y-h.box.min.y)||1);_fcP.applyMatrix4(h.root.matrixWorld);if(Math.hypot(_fcP.x-P.x,_fcP.z-P.z)>range)return '';
  if(ny<FC_PNEU){f.hp=0;f.v=0;sfx('thump');say('Pneu furado. O Fusca parou.','sys',2);return 'pneu';}
  if(ny>FC_VIDRO){f.on=false;fcHud();sfx('bad');gameOverJornal('','fujao','',function(){q34FugaCarro();},['','']);return 'vidro';}
  say('Lataria. Mire no pneu.','sys',1.5);return 'lata';}
function fcSemEscada(){var u=unoEsc();return !!(u&&(u.cai||u.mao));}
/* Uno com escada ao lado do jogador na cena; retry conserva a largada perto da rota. */
/* CEO 08/11 heroi machucado: tremor leve, visao turva que limpa, grunhido de tempos em tempos; some sozinho */
/* CEO 08/11 'lisinho': luz dentro de grupo que some mudava a contagem de luz e recompilava todos os shaders (engasgo ao entrar/sair de area).
   Luz pontual sai do grupo pra raiz da cena, segue a posicao dele e so apaga a intensidade; a contagem nunca muda. */
var LUZF=null;
function luzTick(){
  if(!LUZF){LUZF=[];var ls=[];scene.traverse(function(o){if(o.isPointLight&&o.parent&&o.parent!==scene&&!o.parent.isCamera)ls.push(o);});
    ls.forEach(function(l){var g=l.parent,lp=l.position.clone();scene.add(l);LUZF.push({l:l,g:g,p:lp});});}
  for(var i=0;i<LUZF.length;i++){var f=LUZF[i],l=f.l,v=true,q=f.g,r=null;while(q){if(!q.visible)v=false;r=q;q=q.parent;}if(r!==scene)v=false;
    l.position.copy(f.p).applyMatrix4(f.g.matrixWorld);
    if(!v){if(l.intensity>0){l.userData.i0=l.intensity;l.intensity=0;}}else if(l.userData.i0!=null){l.intensity=l.userData.i0;l.userData.i0=null;}}
}
function feridoTick(){var c=renderer.domElement;if(S.ferido>S.time){var k=(S.ferido-S.time)/9;CB.shake=Math.max(CB.shake||0,.05+.1*k);c.style.filter='blur('+(k*2.2).toFixed(2)+'px)';
    if(S.time>(S.ferGr||0)){S.ferGr=S.time+2.4+Math.random()*1.8;sfx('grunhido',.55+.35*k);}}else if(c.style.filter){c.style.filter='';S.ferido=0;}}
/* CEO 08/11 pos-cacamba: Uno com escada fica MAIS PRA TRAS, longe do galpao do baile e fora do quadro da cena (24 a 45 m do jogador, o mais longe do baile possivel) */
function unoLonge(path){var st=BAILE.stage,b=null,bg=-1;for(var s=0;s<path.len;s+=2){var q=path.at(s),d=Math.hypot(q.x-P.x,q.z-P.z);if(d<24||d>45)continue;var g=Math.hypot(q.x-st[0],q.z-st[2]);if(g>bg){bg=g;b=q;}}
  return b||{x:P.x+5,z:P.z,dx:0,dz:1};}
function unoAqui(path,s,lado){var p=PCARS[UNO_SPOT];if(!p||!p.m)return false;if(p.solta||fcSemEscada())unoEscadaVolta(true);var q=lado?unoLonge(path):path.at(s);
  p.m.position.set(q.x,surfaceY(q.x,q.z),q.z);p.m.rotation.y=yawTo(q.dx,q.dz)+UNO_YAW;
  {var c=Math.abs(Math.cos(p.m.rotation.y)),sn=Math.abs(Math.sin(p.m.rotation.y)),hx=(1.7*c+UNO_LEN*sn)/2,hz=(1.7*sn+UNO_LEN*c)/2;p.col[0]=q.x-hx;p.col[1]=q.z-hz;p.col[2]=q.x+hx;p.col[3]=q.z+hz;}p.m.visible=true;p.col.ativo=!(S.inCar&&S.uno);/* CEO 08/11 parede invisivel: a caixa do Uno ficava no lugar antigo; Uno escondido pelo spawn da base voltava invisivel com caixa ativa */
  return true;}
function q34FugaCarro(pronto){fcAssets();if(NPCBY.fujao){NPCBY.fujao.kind='suspeito';profSkin(NPCBY.fujao);}pronto=pronto===true&&!!S.fc;var path=pronto?S.fc.path:new Path(TR_PTS),s0=fcPerto(path,P.x,P.z);
  if(!pronto)fcPrepara(path,s0+25);
  fcGpsLiga(S.fc);
  S.step='fugacarro';setObj('Ele fugiu de Fusca! Persegue no Uno');setMark(null);
  if(S.inCar)exitCar(true);
  var temUno=pronto?!!(PCARS[UNO_SPOT]&&PCARS[UNO_SPOT].m):unoAqui(path,Math.max(0,s0-6));
  if(temUno&&!pronto){var pu=PCARS[UNO_SPOT].m;pu.updateMatrixWorld(true);var pw=pu.localToWorld(V3(-1.8,0,.3));P.x=pw.x;P.z=pw.z;P.y=surfaceY(P.x,P.z);} /* retry: exitCar largou o jogador onde o Uno longe estava; volta ao lado do Uno novo */
  if(!pronto)smp('pneu-cantando',.6);
  playSeq((pronto?DIALOGO.q34fogecarro.slice(1):DIALOGO.q34fogecarro).concat(temUno?DIALOGO.q34uno:[]),function(){if(S.step!=='fugacarro')return;if(temUno&&!S.inCar){var B=PCARS[UNO_SPOT].m;if(Math.hypot(B.position.x-P.x,B.position.z-P.z)<8&&portaLivre(B,true))enterUno();if(!S.inCar){marcaPortaVeiculo(B);setObj('Corre pro Uno com escada');}}});
}
/* ---------- GPS do Fusca (CEO 08/11) ----------
   Grafo das ruas por onde carro passa: nos = cruzamentos, aresta so existe se ha uma faixa livre de COL (parede/carro parado) para o Fusca (raio 1,05).
   A cada cruzamento ele escolhe a rua: foge do jogador mas fica a vista (alvo ~38 m, nunca passa de 60), faz curva, nao repete rua recente, nao volta pela mesma. */
var FCG=null,FC_RS=7;
function fcRnd(){FC_RS=(FC_RS*16807)%2147483647;return FC_RS/2147483647;}
