function fcCenaFim(q){
  if(S.fcCena!==q)return;
  var n=q.n,y=n.y,log=q.log.slice();clearSubs();fcCenaLimpa();
  n.down=true;n.cap2Body=true;n.fcCenaBody=true;n.fcCorpoPendente=!!q.semAtor&&!(n.m.userData.bandido||n.m.userData.gl);n.m.visible=!n.fcCorpoPendente;n.hold=true;n.idleHold=false;n.m.rotation.x=n.m.userData.bandido?0:1.5;n.m.position.y=y+(n.m.userData.bandido?.007:.08);if(n.m.userData.bandido)bandidoTick(0);
  /* CEO 08/11 22h: a viatura volta pra vaga do baile (nada de ficar no meio da rua da perseguicao) e o heroi e levado ate ela */
  var st=BAILE.stage,v=cambCarro(),moveis=vehicleHitboxes(),p;
  // A mesma faixa já usada para sair do baile comporta mais duas viaturas em fila.
  for(var i=0;i<3;i++){
    var vaga={x:st[0]-26-6*i,z:st[2]+6,yaw:Math.PI/2};
    p=fcViaturaPe(vaga,moveis,true);if(!p)continue;
    v.x=vaga.x;v.z=vaga.z;v.yaw=vaga.yaw;
    if(v===C0){v.v=0;placeCar();}else{var vi=COL.indexOf(S.vtrCol);if(vi>=0)COL.splice(vi,1);S.vtrCol=null;}
    break;
  }
  if(!p)p=fcViaturaPe(v,moveis,true);
  var semVaga=!p;if(semVaga)p=q.origem||P;
  P.x=p.x;P.z=p.z;P.y=semVaga?p.y:surfaceY(p.x,p.z);P.crouch=false;P.alt=semVaga?Math.max(0,P.y-groundY(P.x,P.z)):0;P.dip=0;P.clr=P.alt+.05;P.arc=P.mt=null;P.vx=P.vz=P.vy=P.spd=0;
  L.yaw=yawTo(v.x-P.x,v.z-P.z);L.pitch=0;
  cenaSolta();S.step='casa';S.fcCenaLog=log;casaGuia();
  if(semVaga&&!casaVagaOk()){setObj('Volte à viatura para levar o Pipoca à Dona Marlene');setMark([v.x,surfaceY(v.x,v.z)+1,v.z]);}
  speak(DIALOGO.q34volta[0]);
  $('fade').classList.add('on');later(.15,function(){$('fade').classList.remove('on');});
  questCapture(true);
}
function fcViaturaPe(v,moveis,estacionar){
  // Busca local: prefere a calçada junto à porta; sem espaço, o chamador conserva a vaga anterior.
  var best=null,score=Infinity,raio=3.9,folga=raio+.45,piso={y:surfaceY(v.x,v.z)};
  function perto(c){return c!==S.vtrCol&&c.ativo!==false&&v.x+folga>=c[0]&&v.x-folga<=c[2]&&v.z+folga>=c[1]&&v.z-folga<=c[3]&&colAltura(c,piso)&&(!c.obb||c.obb.root.visible);}
  var col=COL.filter(perto);if(moveis)col=col.concat(moveis.filter(perto));
  var gente=NPCS.filter(function(n){return n.m.visible&&!n.down&&Math.abs(n.x-v.x)<=raio+.9&&Math.abs(n.z-v.z)<=raio+.9&&(n.y==null||Math.abs(n.y-piso.y)<1.65);});
  if(estacionar&&!cabeCarro(v.x,v.z,v.yaw,function(q){q.y=piso.y;return !pushCircle(q,1.1,col)&&!(GP.colCarro&&pushCircle(q,1.1,GP.colCarro))&&!gente.some(function(n){return dist2(q.x,q.z,n.x,n.z)<1.5;});}))return null;
  col=col.concat(PORTA_PE.filter(perto));caixasViatura(col,v);
  for(var r=2;r<=raio&&r<score;r+=.3)for(var i=0;i<48;i++){
    var a=v.yaw+i*Math.PI/24,x=v.x-Math.cos(a)*r,z=v.z+Math.sin(a)*r,lado=Math.abs(Math.sin(a-v.yaw));if(r+lado>=score)continue;
    if(col.some(function(c){return x>c[0]-.45&&x<c[2]+.45&&z>c[1]-.45&&z<c[3]+.45;}))continue;
    if(gente.some(function(n){return dist2(x,z,n.x,n.z)<.8;}))continue;
    var sc=(roadAt(x,z)>=0?10:0)+r+lado;if(sc<score){best={x:x,z:z};score=sc;}
  }
  return best;
}
