  var p=SMK.shift();SMK.push(p);p.blood=false;p.s.material.map=SMKT;p.fc=h<.5?6:4;p.t=0;p.s.visible=true;p.s.material.color.setHex(cor);p.s.position.set(x,surfaceY(x,z)+h,z);p.s.scale.setScalar(.8);p.vx=.15;p.vy=.6;p.vz=.2;
