function fcCenaCamera(){
  var q=S.fcCena;if(!q)return false;
  document.body.classList.add('cena');P1.visible=PW.visible=VM.visible=false;
  camera.fov=camera.aspect<.7?40:35;camera.updateProjectionMatrix();
  if(!q.fixa){camera.position.set(S.fc.x-4,surfaceY(S.fc.x,S.fc.z)+1.68,S.fc.z-3);camera.lookAt(S.fc.x,1+surfaceY(S.fc.x,S.fc.z),S.fc.z);}
  else{var t=q.tempo,x=FC_CENA.x,z=FC_CENA.z,y=q.n.y;
    if(q.conversa&&!q.radio){camera.position.set(x+.5,y+1.05,z-2.3);camera.lookAt(x,y+.48,z+.2);}
    else if(t<3.2){camera.position.set(P.x,y+1.68-.65*clamp((t-1.8)/.35,0,1),P.z);camera.lookAt(x,y+(t<1.18?1.5:.48),z+.2);if(t>=1.8){camera.position.set(P.x,y+.83,P.z+.5);camera.lookAt(x,y+.35,z+.85);}}
    else if(t<5.8){camera.position.set(P.x,y+1.45,P.z);camera.lookAt(x+5,y+.9,z+2.5);}
    else if(t<7.5){var janela=FC_ASSET.pulso.getWorldPosition(_gT);camera.position.set(x+1.95,y+1.55,z-.50);camera.lookAt(janela);}
    else{camera.position.set(x+1.55,y+.95,z-2.65);camera.lookAt(x,y+.26,z);}
  }
  /* O mesmo plano acompanha o preso de pe, sem lente dentro do corpo. */
  if(q.fixa&&q.n.m.userData.bandido&&q.tempo>=1.4&&q.tempo<7.5&&(q.conversa&&!q.radio||q.tempo<3.2)){
    var pk=clamp((q.tempo-1.4)/.35,0,1);pk=pk*pk*(3-2*pk);
    _gT.set(0,0,-1).applyQuaternion(camera.quaternion).multiplyScalar(3.7).add(camera.position);
    camera.position.lerp(_gS.set(x+.8,y+1.55,z-3.7),pk);camera.lookAt(_gT.lerp(_gS.set(x,y+.95,z),pk));
  }
  // Respiracao e mao independem da animacao do ator. Mesmo relogio = mesmo quadro.
  var clock=q.motion||0,quiet=q.conversa&&!q.radio,amp=quiet?.002:.012;
  var kick=q.impact==null?0:clamp(1-(clock-q.impact)/.16,0,1);
  camera.position.x+=amp*Math.sin(clock*8.3);
  camera.position.y+=amp*.65*Math.sin(clock*1.9)+kick*.012*Math.sin(clock*61);
  camera.position.z+=amp*.5*Math.sin(clock*9.7);
  camera.rotateX((quiet?.0008:.006)*Math.sin(clock*7.1)+kick*.009);
  camera.rotateY((quiet?.0008:.006)*Math.sin(clock*8.7));
  camera.rotation.z=quiet?0:.0053*Math.sin(clock*5.3);
  // Se o assunto do plano não chegou a tempo, acompanha o policial. O diálogo nunca espera o arquivo.
  var reacao=q.fixa&&(t>=7.5&&t<7.75||(t<3.8||t>=7.5?q.semAtor:q.semCarro));
  fcHeroiPlano(q,reacao);
  if(q.fixa&&!reacao&&(q.conversa&&!q.radio||t<3.2))cenaEnquadra([q.n.m]);
  // Disparo: corte para a reacao do heroi. A lente fica entre ele e a vitima, olhando o rosto dele; a vitima fica atras da camera.
  if(reacao){camera.position.set(P.x+.9,y+1.55,P.z+1.6);camera.lookAt(cenaCabeca(P1).getCenter(new THREE.Vector3()));cenaEnquadra([P1]);}
  pmPlanoAlgema(q);camera.updateMatrixWorld(true);L.yaw=camera.rotation.y;L.pitch=camera.rotation.x;return true;
}
function vizinhaNPC(){var v=NPCBY.vizinha||addNPC('vizinha',{shirt:0xc9739a,pants:0x3a3240,hair:0x2a1810,bun:true,skin:0x9a6a48,dress:true},{x:0,z:0,mode:'talk',name:'Vizinha'});v.m.visible=true;return v;} /* CEO 06/11: quem fala tem corpo na cena */
/* CEO 07/11: chega de viatura, desce, vai atras, pega o Pipoca e entra na casa com ele no colo; sem cartao de escolha */
function cambCarro(){return S.uno&&S.vtr?S.vtr:C0;} /* Pipoca anda no camburao da VIATURA, mesmo com o jogador no Uno */
function cambTras(){var V=cambCarro(),c=Math.cos(V.yaw),s=Math.sin(V.yaw);return [V.x+3*s,V.z+3*c];}
/* CEO 08/11 ENTREGA DO PIPOCA: bate na porta, o Seu Joao (vizinho do mercadinho, cuida dela) abre, voce entra, cena na sala e a Marlene oferece um cafe */
/* CEO 08/11 'cheguei sem o Pipoca no colo': no passo casa o guia aponta o camburao onde ele esta; na porta sem ele, avisa e aponta de novo */
/* CEO 08/11 "igual GTA": primeiro leva a viatura ate a vaga na frente da casa da Marlene; descendo la, pega o Pipoca no camburao e bate na porta */
var CASA_VAGA=[2.8,54,0];
function casaVagaOk(){var V=cambCarro();return dist2(V.x,V.z,CASA_VAGA[0],CASA_VAGA[1])<12&&Math.abs(V===C0?C0.v||0:0)<.5;}
function distanciaDoCamburao(){var t=cambTras(),d=dist2(P.x,P.z,t[0],t[1]);return d<2.2&&Math.abs(P.y-surfaceY(t[0],t[1]))<1.4?d:Infinity;}
function pertoDoCamburao(){return Number.isFinite(distanciaDoCamburao());}
/* CEO 08/11 22h22: na entrega do Pipoca a Dona Marlene e o Seu Joao ja estao DENTRO da casa (nunca na salinha do mercadinho) */
function casaMoradores(){if(S.casaMor)return;S.casaMor=1;[['marlene',[12.6,54.6]],['juca',[9.4,55.2]]].forEach(function(a){var n=NPCBY[a[0]];if(!n)return;n.hold=true;n.idleHold=true;n.fleeT=0;n.mode='idle';n.away=false;cap2Place(n,a[1]);n.yaw=yawTo(7.2-n.x,54-n.z);n.m.rotation.y=n.yaw;n.m.visible=true;});}
function marcaTraseira(rota){var t=cambTras();if(!rota&&MK?.guiaCamb&&!MK.rota&&Math.hypot(MK.x-t[0],MK.z-t[1])<.1)return;setMark([t[0],surfaceY(t[0],t[1]),t[1]],rota);MK.guiaCamb=true;}
function marcaSoleiraCasa(){var x=CASINHA.door[0]-1,z=CASINHA.door[1];setMark([x,groundY(x,z),z]);MK.soleira=true;}
function casaGuia(){if(S.step!=='casa')return;casaMoradores();if(CAMB.dentro.indexOf('dog')<0){CAMB.dentro.push('dog');}
  if(!S.casaVaga){setObj('Levar a viatura até a frente da casa da Dona Marlene');setMark([CASA_VAGA[0],.2,CASA_VAGA[1]]);return;}
  setObj('Pegar o Pipoca no camburão e bater na porta da Dona Marlene');marcaTraseira();}
function q34Bate(){if(S.step==='porta'||S.step==='abriu'||S.finalCena&&S.finalCena.sala)return;finalPrepara();S.step='porta';S.bateT=S.time;setObj('');setMark(null);cenaTrava(null);[0,.32,.64].forEach(function(t){smp('door-kick',.32,1.9+Math.random()*.15,0,t);});}
function q34PortaTick(){if(S.step!=='porta'||S.time-S.bateT<1.3)return;var d=CASINHA.door,jo=NPCBY.juca;S.step='abriu';if(S.finalCena)S.finalCena.shot=null;
  jo.hold=true;jo.mode='talk';cap2Place(jo,[d[0]+1.6,d[1]+.4]);jo.yaw=yawTo(P.x-jo.x,P.z-jo.z);jo.m.rotation.y=jo.yaw;CASINHA.porta.quer=1;cenaSolta();
  cenaSeq(jo,DIALOGO.q34porta,function(){sfx('grunhido',.6);S.step='entra';if(S.finalCena)S.finalCena.plano='entra';setObj('Entrar na casa');setMark([11.6,1.5,53.25]);cap2Place(jo,[9.2,55.3]);});SEQ.next=Math.max(SEQ.next,S.time+.45);}
/* Final: blocking and eye-level gaze belong to the scene, never to the speaking animation. */
