function cap2Stall(){
  if(CAP2.stallMesh)return;
  // ponytail: um batch para a barraca da feira existente, sem criar outro lugar.
  var B=new Batch(),p=CAP2.stall,x=p[0],z=p[1];
  function b(dx,y,dz,w,h,d,col){B.add(BOX,x+dx,GY+y,z+dz,w,h,d,0,C(col),.1,.02);}
  b(0,.15,0,2.8,.9,.85,0x846440);b(0,1.05,0,3,.1,1,0xc5ae83);
  [-1.35,1.35].forEach(function(dx){b(dx,0,.3,.07,2.35,.07,0x766047);});
  b(0,2.3,0,3.2,.1,1.5,0x386d68);
  for(var i=0;i<6;i++)b(-1.15+i*.45,1.15,0,.32,.16,.4,i%2?0xd7b24c:0x638748);
  CAP2.stallMesh=B.mesh(MAT,false,true);scene.add(CAP2.stallMesh);
  COL.push([x-1.5,z-.5,x+1.5,z+.5,1.15]);
}
