  clearSubs();say(txt,l.cls==='pensa'?'thought':l.cls||'npc',Math.max(4,wordsDur(l.texto)),name||null,false,null,l.emo||'neutro');if(l.quem==='marlene'&&SUBS.length)SUBS[SUBS.length-1].keep=true;
