    var carlos=NPCBY.carlos;cap2Place(carlos,[MERC.door[0]-.6,MERC.door[1]+.6]);carlos.hold=true;carlos.cap2Safe=true;PROT.carlos=1;carlos.yaw=yawTo(NPCBY.marlene.x-carlos.x,NPCBY.marlene.z-carlos.z);animPerson(carlos.m,.01,0,'idle',carlos.y);carlos.m.rotation.y=carlos.yaw;
