function showLesson(done){
  var i=0,el=$('les');
  function draw(){var l=LESSON[i];$('lesE').textContent=l.e;$('lesT').textContent=l.t;$('lesP').textContent=l.p;$('lesB').textContent=i<LESSON.length-1?'Próximo':'Começar';$('lesN').textContent=(i+1)+' de '+LESSON.length+' · {{avancar}}';}
  function next(){if(i<LESSON.length-1){i++;draw();}else{el.classList.remove('on');window.removeEventListener('keydown',kd,true);done();}}
  function kd(e){if(e.code==='Enter'||e.code==='Space'){e.preventDefault();e.stopPropagation();next();}}
  window.addEventListener('keydown',kd,true);$('lesB').onclick=next;draw();el.classList.add('on');
}

