/* ---------- loop de logica ---------- */
/* lote residencial: entrar sem mandado, flagrante ou socorro = errado (CF art. 5o, XI). Aviso leve, nao trava. */
function loteCheck(){
  if(S.inCar||S.mandado||S.flagrante||(S.pipa&&S.pipa.st!=='fim')){S.lote=-1;return;}
  var i,l,at=-1;for(i=0;i<LOTES.length;i++){l=LOTES[i];if(P.x>l[0]&&P.x<l[2]&&P.z>l[1]&&P.z<l[3]){at=i;break;}}
  if(at!==S.lote){S.lote=at;S.loteT=S.time;S.loteHit=false;if(at>=0)say('Lote particular: sem mandado, flagrante ou socorro, nao entra (CF art. 5o, XI).','sys',3.2);}
  else if(at>=0&&!S.loteHit&&S.time-S.loteT>2.2){S.loteHit=true;addKarma(-3);falaNaRua(ruaVizinho(P.x,P.z,18,false),['Qual foi, seu polícia? Cadê o mandado?'],{prio:1});}
}
function update(dt){
  if($('opt').classList.contains('on'))return;
  questCapture();
  S.time+=dt;placasTick(dt);
  laterTick();subTick();seqTick();
  if(S.soco&&S.soco.tema==='clinch'){quizTick(dt);placeCam(dt);return;}
  if(S.soco&&!S.soco.luta)quizTick(dt);
  if(QZ&&!QZ.done&&S.phase==='ui'){QZ.t-=dt;$('qbar').style.transform='scaleX('+clamp(QZ.t/QZ.max,0,1)+')';if(QZ.t<=0)ansQ(null);}if(QZ&&QZ.fbAte&&performance.now()>=QZ.fbAte)closeQ();
  if(S.phase==='luta'){lutaTick(dt);return;}
  if(EST.fim){estFimUpdate(dt);return;}
  if(EST.on){estUpdate(dt);updNPCs(dt,false);return;}
  if(S.phase==='cut'){cutUpdate(dt);updNPCs(dt,false);return;}
  var inp=S.phase==='play'&&!cenaOn()?readIn():{fx:0,fy:0,run:false};
  P.botDist=0;if(SQV.mode){P.vx=P.vz=P.spd=0;C0.v=0;}else if(S.inCar)carUpdate(dt,inp);else footUpdate(dt,inp);unoFogo(dt);sangueTick(dt);
  if(S.inCar&&S.phase==='play'&&S.time-(S.lookT||0)>1.6&&Math.abs(C0.v)>2)L.yaw*=Math.max(0,1-dt*1.4);
  placeCar();carVis(dt,S.inCar?C0.v:0);praiaTick(dt);
  if(S.funk&&S.inCar){S.beat=(S.beat||0)+dt;if(S.beat>60/PAT.bpm/2){S.beat=0;RUMB_CALA=1;try{sfx('thump');}finally{RUMB_CALA=0;}BEAT=1;}}
  S.mood=(S.mood||0)+dt;if(S.mood>.5){S.mood=0;npcMood();}
  dogUpdate(dt);
  if(S.phase==='play'){if(!lifeActive()&&!cmTick(dt)){missionUpdate(dt);q34Update(dt);}else if(S.step==='fuga'||S.step==='tiroteio')q34Update(dt);}
  if(S.fcCena)fcCenaTick(dt);sossegoTick(dt);
  escadaPortaSync();
  if(S.inCar&&S.phase==='play'&&(VIB.dt=(VIB.dt||0)+dt)>.28){VIB.dt=0;var av=Math.abs(C0.v||0);if(av>2)rumble(300,Math.min(.22,av/160)+(potDepth(C0.x,C0.z)>.05?.15:0),Math.min(.18,av/220));}/* CEO 09/11: estrada trepida no controle, mais forte rapido e no buraco */
  placeCam(dt);botinaPasso(dt);
  updNPCs(dt,S.funk);
  if(!S.inCar&&Math.abs(L.yaw)>50)L.yaw%=Math.PI*2;
}

