function gunPose(dt){
  /* arma na mao do jogador (1a pessoa): pronto baixo (cano para o chao, quase fora da tela) ou mirando */
  GUNK+=((GUNUP?1:0)-GUNK)*Math.min(1,dt*9);var k=GUNK;
  if(Math.abs(GUNK-(GUNUP?1:0))<.003)GUNK=k=GUNUP?1:0;
  var kk=CB&&CB.kick||0;/* coice do tiro */
  /* ORDEM 11 (CEO): arma GRANDE e BAIXA no canto direito, estilo FPS (nao voa); sem braco direito, so a mao esquerda aparece no reload */
  var rl=CB&&CB.reload>0;RLK+=((rl?1:0)-RLK)*Math.min(1,dt*12);if(RLK<.003)RLK=0;
  var rp=reloadPose(rl?1-CB.reload/CB.rdur:-1,CB.rdur||1.4);
  ADSK+=((ads()?1:0)-ADSK)*Math.min(1,dt*12);var D=GUNPOSE.ads,A0=GUNPOSE.aim,A=A0.map(function(v,i){return v+(D[i]-v)*ADSK;});
  var w=RLK,H=GUNPOSE.hip,R=GUNPOSE.rl;
  function mx(i){var v=H[i]+(A[i]-H[i])*k;return v+(R[i]-v)*w;}  /* quadril -> mira -> reload (reload cola a arma na tela para pente e mao aparecerem) */
  GUN.position.set(mx(0)+rp.x,mx(1)+rp.y,mx(2)+kk*.05+rp.z);
  GUN.rotation.set(mx(3)+kk*.22+rp.rx,mx(4)+rp.ry,mx(5)+rp.rz);
  GUN.scale.setScalar(GUNPOSE.s+(GUNPOSE.sr-GUNPOSE.s)*w);reloadViz(rp);
}
