  if(md){md.visible=rp.dv;md.position.set(p.x+rp.dx,p.y+rp.dy+.07,p.z+rp.dz);md.rotation.set(RL.r0.x+rp.dr,RL.r0.y,RL.r0.z+rp.dr*.6);}
