function mat(hex,em){var k=hex+'_'+(em||0);return MATS[k]||(MATS[k]=new THREE.MeshStandardMaterial({color:C(hex),flatShading:true,roughness:.9,emissive:em?C(em):0x000000}));}
function box(g,w,h,d,x,y,z,m,ry){var o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);if(ry)o.rotation.y=ry;o.castShadow=true;o.receiveShadow=true;g.add(o);return o;}
