  if(!(Number.isInteger(i)&&i>=0&&i<RADIO_ESTACOES.length)){S.funk=false;S.stn=-1;trkWant(null);if(!quieto){sfx('bump');say('Rádio desligado.','sys',1.4);}radioPlaca();return;}
