    var hill=Math.abs(Math.atan2(Math.sin(solMorroAz(camera.position.x,camera.position.z)-Math.atan2(SUND.x,-SUND.z)),Math.cos(solMorroAz(camera.position.x,camera.position.z)-Math.atan2(SUND.x,-SUND.z))))<.4&&SUND.y<.4;
    var visible=!hill&&GOLD.view.dot(SUND)>0&&Math.abs(GOLD.p.x)<.96&&Math.abs(GOLD.p.y)<.96;
