  var texto=q.q||q.t,key=texto+'|'+op[a],lista=S.cadErros||(S.cadErros=[]),e=lista.find(function(v){return v.id===key;});
  if(e){if(q.x||q.comentario)e.x=q.comentario||q.x;e.vezes++;e.corrigida=false;if(e.origens.indexOf(origem)<0)e.origens.push(origem);}
