  if(!c){var g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(n*3),3));if(src.index)g.setIndex(src.index);g.groups=src.groups;
    c=o.userData.aimSk={m:new THREE.Mesh(g,o.material),rel:new Float32Array(bs.length*16),ok:false};c.m.matrixAutoUpdate=false;}
