    if(best&&al>=best.d)continue;
    /* CEO 08/11 "nao acerto o bandido perto da arvore/poste/muro": a visada para 40 cm ANTES do corpo; a caixa da arvore/poste/muro encostada no bandido nao engole mais o tiro */
    var kk=Math.max(0,(al-.4)/Math.max(al,.01)),ex=ox+(pt.x-ox)*kk,ez=oz+(pt.z-oz)*kk,ey=olho+(pt.y-olho)*kk;
