var _mvV=new THREE.Vector3();
var _motoFrEsfera=new THREE.Sphere(new THREE.Vector3(),1.85);
function motoForaVista(n){camera.updateMatrixWorld();_fcFr.setFromProjectionMatrix(_fcM.multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse));_motoFrEsfera.center.set(n.x,(n.y||0)+.95,n.z);return !_fcFr.intersectsSphere(_motoFrEsfera);}
