  var range=shotRange(),spread=shotSpread(),oy=(rnd()-.5)*spread,op=(rnd()-.5)*spread*.7,pad=!lifeActive()&&aaPad()?.14:0,cano=canoTerceira(),ombro=cano?tiroDoOmbro(cano,range,pad,oy,op):null,hr=ombro?ombro.hit:aimRay(range,pad,oy,op),t=hr&&hr.n,hitT=!!hr;
  var sy=L.yaw+oy,sp=shotPitch()+op,eye=shotEye();
