/* corpo arremessado: gravidade, gira no ar, cai deitado */
function voaNPC(n,dt){var f=n.fly;f.t+=dt;f.vy-=20*dt;n.x+=f.vx*dt;n.z+=f.vz*dt;f.vx*=1-dt*.8;f.vz*=1-dt*.8;
  var gy=surfaceY(n.x,n.z),y=n.m.position.y+f.vy*dt;voaBate(n,f,y-gy);n.m.rotation.x-=f.s*dt;n.m.rotation.z+=f.s*.4*dt;
  if(y<=gy+.15&&f.t>.2){n.fly=null;n.y=gy;n.m.rotation.x=-1.45;n.m.rotation.z=0;y=gy+.15;sfx('bump');}
  n.m.position.set(n.x,y,n.z);}
/* Corpo arremessado encontra a mesma lataria orientada do jogador. */
function voaBate(n,f,alt){if(alt>1.7)return;var boxes=vehicleHitboxes();if(f.t>.35){var h=modelHitbox(S.uno?PCARS[UNO_SPOT].m:CAR);if(h)boxes.push(h.col);}
  for(var i=0;i<boxes.length;i++){var x=n.x,z=n.z;if(!pushCircle(n,.2,[boxes[i]]))continue;
    var dx=n.x-x,dz=n.z-z,d=Math.hypot(dx,dz)||1;dx/=d;dz/=d;var vn=f.vx*dx+f.vz*dz;
    if(vn<0){f.vx-=1.3*vn*dx;f.vz-=1.3*vn*dz;f.vx*=.4;f.vz*=.4;sfx('bump');}}}
/* empurra p para fora do circulo (cx,cz,r): moto e carro nao atravessam o jogador */
function pushOut(p,cx,cz,r){var dx=p.x-cx,dz=p.z-cz,d=Math.hypot(dx,dz);if(d>=r)return;if(d<1e-3){dx=1;dz=0;d=1;}p.x=cx+dx/d*r;p.z=cz+dz/d*r;}
/* CEO 08/11 "matei o Toinho e ta voando em cima da escada": corpo deitado tombava sempre pro mesmo lado do mundo (ordem XYZ), sem olhar chao.
   Agora escolhe o lado com chao firme e sem parede em todo o comprimento do corpo (longe do jogador primeiro). */
function corpoApoio(x,z,y){
  if(y>GY-.3&&galpaoEscadaY(x,z)!==null)return false; /* buraco da escada do galpao */
  if(y>GY-.3&&y<GY+.5&&surfaceY(x,z)<y-.45)return false; /* beirada/desnivel */
  return !COL.some(function(b){return b.ativo!==false&&x>b[0]&&x<b[2]&&z>b[1]&&z<b[3]&&(b[4]==null||b[4]>.45)&&(b.minY==null||b.minY<y+.5);});
}
function corpoLado(n){
  var y=n.y||0,base=Math.atan2(n.x-P.x,n.z-P.z),best=null;
  for(var k=0;k<8&&best===null;k++){var a=base+[0,.79,-.79,1.57,-1.57,2.36,-2.36,3.14][k],ok=true;
    for(var d=.4;d<=1.7&&ok;d+=.4)ok=corpoApoio(n.x+Math.sin(a)*d,n.z+Math.cos(a)*d,y);
    if(ok)best=a;}
  if(best===null)best=base;
  /* YXZ: rotation.x=-1.45 leva a cabeca para (-sin y, -cos y); queremos cabeca para (sin a, cos a) */
  n.m.rotation.order='YXZ';n.yaw=best+Math.PI;n.m.rotation.y=n.yaw;n.corpoA=best;sacosContato(n.x,n.z,y,Math.sin(best)*1.55,Math.cos(best)*1.55,.35,1.2);return best;
}
function downNPC(n,causa){if((QUEST[n.id]||n.cap2Safe)&&!(n.id==='marlene'&&S.marlene&&S.marlene.morrendo))return false;if(n.bike){if(!n.down)n.hold00=!!n.hold;motoTombo(n);}else{corpoLado(n);n.m.rotation.x=-1.45;n.m.position.y=n.y+.15;}n.down=true;n.hold=true;if(!(n.id==='marlene'&&S.marlene&&S.marlene.morrendo)&&(npcKind(n)==='civil'||PROT[n.id]||n.surrendered))morteJornal(n,n.surrendered?'rendido':causa||'civil');}
/* reload em fases (p 0..1): inclina, solta o pente, ele cai, pente novo entra com tapa, ferrolho, volta */
var RP0={x:0,y:0,z:0,rx:0,ry:0,rz:0,sl:0,mv:true,my:-.07,dv:false,dx:0,dy:0,dz:0,dr:0,hv:false,hy:-.3};
function rsm(x){x=x<0?0:x>1?1:x;return x*x*(3-2*x);}
/* pistola sobe e gira (rz NEGATIVO mostra o pente pro centro da tela), pente cai a vista, mao traz o novo, tapa, ferrolho */
function reloadPose(p,dur){
  if(p<0)return RP0;
  var T=rsm(p/.12)*(1-rsm((p-.62)/.2)),r={x:-.12*T,y:.2*T,z:.04*T,rx:.35*T,ry:.25*T,rz:-.65*T,sl:0,mv:p<.16||p>=.38,my:-.07,dv:false,dx:0,dy:0,dz:0,dr:0,hv:false,hy:-.3};
  if(p>=.38){r.my=-.25+.18*rsm((p-.38)/.18);}
  if(p>=.38&&p<.68){r.hv=true;r.hy=r.my-.09-(p>.58?.22*rsm((p-.58)/.1):0);}
  if(p>.16&&p<.4){var t=(p-.16)*dur;r.dv=true;r.dy=-.07-.25*t-3*t*t;r.dx=-.05*t;r.dz=.15*t;r.dr=t*5;}
  if(p>.56&&p<.62)r.rx+=.06*Math.sin((p-.56)/.06*Math.PI);
  if(p>.68&&p<.77){r.sl=p<.73?.06*rsm((p-.68)/.05):.06*(1-rsm((p-.73)/.02));}
  return r;
}
/* som do reload em camadas, sincronizado com as fases: solta, desliza, cai no chao, desliza, TAPA, ferrolho */
function reloadSfx(d,rifle){
  var k=rifle?.8:1;
  var at=function(p){return p*d;};
  /* clipes originais (tools/reload_sfx.py) casados pelo pico de cada um com a fase do pente; sintese abaixo so se nao carregou */
  var rr=rifle?.88:1,gg=rifle?.9:1;
  /* gravacao real de pistola (CC0, tools/reload_sfx_real.py): cada clipe entra pelo pico (offset) casado com a fase */
  var rl2=function(n,v,off,p){return smp(n,v*gg,rr,0,Math.max(0,at(p)-off/rr));};
  if(AUDIO_EMBED['rl2-release']&&AUDIO_EMBED['rl2-out']&&AUDIO_EMBED['rl2-in']&&AUDIO_EMBED['rl2-rack']){
    rl2('rl2-release',1,.053,.16);rl2('rl2-out',1,.149,.4);rl2('rl2-in',1,.063,.56);rl2('rl2-rack',1,.007,.7);
    return;
  }
  if(smp('rl-release',.9*gg,rr,0,at(.16))){
    smp('rl-out',.9*gg,rr,0,at(.2)-.211);smp('rl-floor',.8*gg,1,0,at(.4));smp('rl-in',1*gg,rr,0,at(.56)-.171);
    smp('rl-back',.8*gg,rr,0,at(.7)-.101);smp('rl-fwd',1*gg,rr,0,at(.75));
    smp('mag-out',.4,rr,0,at(.19));smp('mag-in',.5,rr,0,at(.55));
    return;
  }
  nburst(4200*k,6,.025,.13,at(.14));tone(1900*k,900*k,.03,'square',.03,at(.14));/* botao de soltar */
  nburst(1800*k,2,.1,.09,at(.17));tone(190*k,95*k,.09,'triangle',.12,at(.26));/* pente desliza e sai */
  tone(150*k,55*k,.12,'sine',.16,at(.5));nburst(1000,1,.07,.12,at(.5));tone(2600,1900,.06,'sine',.04,at(.5));/* pente bate no chao */
  tone(2400,1700,.05,'sine',.025,at(.5)+.11);tone(120,60,.08,'sine',.07,at(.5)+.11);/* quica */
  nburst(2300*k,3,.09,.08,at(.46));/* pente novo desliza */
  tone(230*k,110*k,.07,'square',.1,at(.58));nburst(5200,4,.025,.16,at(.58));tone(90*k,42*k,.12,'sine',.2,at(.58));/* TAPA no pente */
  nburst(3400*k,5,.06,.1,at(.66));tone(1500*k,700*k,.05,'square',.04,at(.66));/* puxa o ferrolho */
  tone(260*k,130*k,.06,'square',.11,at(.74));nburst(6200,6,.025,.2,at(.74));tone(110*k,60*k,.1,'sine',.1,at(.74));/* solta: clack */
  if(AUDIO_EMBED&&AUDIO_EMBED['slide-rack'])smp('slide-rack',.35,1,0,at(.66));
}
function reload(mudo){
  var it=CB.item,cap=it?30:12;
  if(!CB.drawn||CB.reload>0)return;
  if(CB.mag[it]>=cap){if(!mudo)say('Pente cheio.','sys',1.2);return;}
  if(CB.res[it]<=0){if(!mudo)say('Sem munição reserva.','sys',1.2);return;}
  CB.rdur=it?1.7:1.4;CB.reload=CB.rdur;reloadSfx(CB.rdur,it);
}
