  if(CB.aimT>0)CB.aimT-=dt;GUNUP=aiming();CB.shake=Math.max(0,CB.shake-dt);CB.flash=Math.max(0,CB.flash-dt);CB.mf.visible=CB.flash>0;if(CB.filmCD>0)CB.filmCD-=dt;
  if(CB.rec>0)CB.rec-=dt;
