    if(a[3]!==a[2])a[3].position.copy(a[3].parent.worldToLocal(V[6].copy(goal)));
    a[3].parent.getWorldQuaternion(C.parent);a[3].quaternion.copy(C.parent.invert().multiply(n.m.getWorldQuaternion(C.q).multiply(C.footQ[i])));a[3].updateMatrixWorld(true);
