  if(q){q.emb.forEach(function(b){var i=SBB.indexOf(b);if(i>=0)SBB.splice(i,1);b.n.m.visible=false;b.n.down=b.n.surrendered=false;b.n.hold=true;if(b.mf)b.mf.visible=false;});q34EmbTira();if(q.car)scene.remove(q.car);}
  S.q34=null;CARRY.ser=null;var ci=CAMB.dentro.indexOf('dog');if(ci>=0)CAMB.dentro.splice(ci,1);
  CB.hp=100;guardaNoRetorno();S.inCar=false;P.vx=P.vz=0;P.crouch=false;clearSubs();
