function emit(type,x,z,r){BUS[type]=(BUS[type]||0)+1;GUARDS.forEach(function(g){if(!g.dead&&g.st==='post'&&dist2(g.n.x,g.n.z,x,z)<(r||30)&&type==='tiro')gAlert(g);});}
/* ---------- guardas: FSM post -> alert -> chase -> post (ou caught) ---------- */
function gAlert(g){if(g.dead||g.st!=='post')return;g.st='alert';g.t=0;sfx('radio');if(S.prep>=30)S.slowT=2.2;say('Guarda: Ei! Parado aí!','npc',1.6,'Guarda');}
function gReset(g){g.dead=false;g.st='post';g.t=0;g.n.x=g.home[0];g.n.z=g.home[1];g.n.yaw=g.yaw0;g.n.down=false;g.n.m.rotation.x=0;g.n.hold=true;g.n.m.position.set(g.n.x,surfaceY(g.n.x,g.n.z),g.n.z);g.n.m.rotation.y=g.yaw0;}
function addGuard(id,cfg,x,z,yaw,kind){
  var n=addNPC(id,cfg,{x:x,z:z,yaw:yaw,mode:'idle',name:'Vigia'});n.hold=true;n.kind=kind||'bandido';
  var g={n:n,home:[x,z],yaw0:yaw,st:'post',t:0,dead:false};GUARDS.push(g);return g;
}
function gUpdate(g,dt){
  var n=g.n;if(g.dead||n.down||!EP.on||(EP.step!=='ep_campo'&&EP.step!=='ep_volta')){animPerson(n.m,dt,0,'idle',n.y);return;}
  var r=P,dx=r.x-n.x,dz=r.z-n.z,d=Math.hypot(dx,dz),fx=-Math.sin(n.yaw),fz=-Math.cos(n.yaw);
  var ang=d>.1?Math.acos(clamp((dx*fx+dz*fz)/d,-1,1)):0;
  var vis=d<EP.seeD&&ang<1.05&&losClear(n.x,n.z,P.x,P.z)&&(CB.drawn||!EP.disguise||d<4)&&!EP.hide;
  var need=1.2+(100-EP.susp)/45+(EP.late?1.5:0)+S.prep/60;
  if(g.st==='post'){
    n.yaw+=Math.sin(S.time*.5+n.x)*.004;n.m.rotation.y=n.yaw;animPerson(n.m,dt,0,'idle',n.y);
    if(vis){g.t+=dt;if(g.t>=need)gAlert(g);}else g.t=Math.max(0,g.t-dt*.6);
  }else if(g.st==='alert'){
    g.t+=dt;n.yaw+=dAng(n.yaw,yawTo(dx,dz))*Math.min(1,dt*6);n.m.rotation.y=n.yaw;
    if(g.t>1.1){g.st='chase';g.t=0;}
  }else if(g.st==='chase'){
    if(d>1.3){var sp=4.3*(EP.reforco?.8:1);n.x+=dx/d*sp*dt;n.z+=dz/d*sp*dt;_cp.x=n.x;_cp.z=n.z;hit(_cp,.4,[]);n.x=_cp.x;n.z=_cp.z;n.yaw+=dAng(n.yaw,yawTo(dx,dz))*Math.min(1,dt*8);animPerson(n.m,dt,sp/1.4,'walk',n.y);}
    n.y=npcY(n);n.m.position.set(n.x,n.y,n.z);n.m.rotation.y=n.yaw;
    if(d<1.5)caught(g);
    else if(d>30){g.t+=dt;if(g.t>4){g.st='post';g.t=0;gReset(g);}}else g.t=0;
  }
}
function caught(g){
  if(EP.reforco&&!EP.reforcoUsed){EP.reforcoUsed=true;g.st='post';gReset(g);say('Reforço: Sai daí, doutor! A gente segura eles.','radio',undefined,'Reforço');return;}
  CB.hp=Math.max(0,CB.hp-100);failRun('Os vigias te pegaram no campo. Sem farda, sem reforço, sem Pipoca.');
}

/* Motor único: o card, o relógio e as respostas da luta servem a todos os desafios. */
var QUIZ_BANCO=[],QUIZ_ERRO='',QUIZ_PRONTO=false,QUIZ_BUEIRO_N=17; // Fonte filtrada: 34 difíceis, duas tentativas sem repetir.
fetch('dados/questoes-s4p.json').then(function(r){if(!r.ok)throw Error('HTTP '+r.status);return r.json();}).then(function(d){
  var ids=new Set(),textos=new Set();
  if(!d||!Array.isArray(d.questoes))throw Error('Formato inválido');
  QUIZ_BANCO=d.questoes.map(function(q){
    if(!q||typeof q.enunciado!=='string'||!q.enunciado.trim()||!q.disciplina||!['C','E'].includes(q.gabarito)||!['facil','dificil'].includes(q.dificuldade)||ids.has(q.id)||textos.has(q.enunciado))throw Error('Questão inválida ou repetida');
    ids.add(q.id);textos.add(q.enunciado);return {id:q.id,t:q.enunciado,a:q.gabarito==='C',d:q.disciplina,dif:q.dificuldade,origem:q.id,src:'Cebraspe · '+q.disciplina,x:q.comentario||q.x||'Este banco não trouxe comentário do professor. Gabarito: '+(q.gabarito==='C'?'CERTO':'ERRADO')+'. Revise este enunciado em '+q.disciplina+'.'};
  });
  if(QUIZ_BANCO.filter(function(q){return q.dif==='dificil';}).length<34||QUIZ_BANCO.filter(function(q){return q.dif==='facil';}).length<60)throw Error('Banco insuficiente');
  QUIZ_PRONTO=true;
}).catch(function(e){QUIZ_BANCO=[];QUIZ_ERRO=e.message;});
/* Tabela unica (CEO 10/11): cada minigame pede uma dificuldade do banco; questaoPara e a unica porta de escolha.
   ligacao: ainda nao existe minigame de questao na ligacao; a linha fica pronta. */
var MINIGAME_DIFICULDADE={bueiro:'dificil',intimidacao:'facil',telhado:'facil',ligacao:'facil'};
var DIF_ORDEM=['facil','dificil'];
function questaoPara(minigame,n,teto){
  var alvo=DIF_ORDEM.indexOf(MINIGAME_DIFICULDADE[minigame]),qs=[];if(alvo<0)return qs;
  /* faltou estoque na pedida: completa com a dificuldade mais proxima, nunca trava */
  DIF_ORDEM.slice().sort(function(a,b){return Math.abs(DIF_ORDEM.indexOf(a)-alvo)-Math.abs(DIF_ORDEM.indexOf(b)-alvo);})
    .forEach(function(d){if(qs.length<n)qs=qs.concat(quizEscolhe(n-qs.length,d,teto));});
  return qs;
}
function quizEscolhe(n,dif,teto){
  if(!S.quizPools)S.quizPools={};var chave=dif+(teto?':'+teto:''),deck=S.quizPools[chave]||[],pool=QUIZ_BANCO.filter(function(q){return q.dif===dif&&(!teto||q.t.length<=teto);}).sort(function(a,b){return a.t.length-b.t.length;});
  if(dif==='facil')pool=pool.slice(0,Math.max(60,n*2)); // Prioriza as 60 mais curtas; suficiente para os desafios fáceis.
  if(deck.length<n){var resto=new Set(deck.map(function(q){return q.id;}));deck=deck.concat(lutaShuffle(pool.filter(function(q){return !resto.has(q.id);})));}
  var qs=deck.splice(0,n);S.quizPools[chave]=deck;return qs;
}
