function quizAnima(el,quadros,op){QP.anims.push(el.animate(quadros,op));}
function quizFxPara(vaiRedesenhar){
  QP.batalha=null;
  QP.anims.forEach(function(a){a.cancel();});QP.anims.length=0;
  if(QP.raf){cancelAnimationFrame(QP.raf);QP.raf=0;if(!vaiRedesenhar){var c=$('quizfx');c.getContext('2d').clearRect(0,0,c.width,c.height);}}
}
// O impacto da luta usa o canvas existente. Um desenho local e um número; nenhum objeto 3D ou luz nasce no clique.
function batalhaImpacto(z,ok){
  var c=$('quizfx'),r=$('socoq').getBoundingClientRect(),alvo=ok?z.n:P;
  c.style.left=c.style.top='0px';if(c.width!==innerWidth)c.width=innerWidth;if(c.height!==innerHeight)c.height=innerHeight;
  _v.set(alvo.x,alvo.y+1.38,alvo.z).project(camera);
  var x=(1+_v.x)*c.width/2,y=(1-_v.y)*c.height/2;
  if(_v.z< -1||_v.z>1||!Number.isFinite(x+y)){x=c.width*.50;y=c.height*.40;}
  x=clamp(x,62,c.width-62);y=clamp(y,76,c.height-65);
  if(x>r.left-38&&x<r.right+38&&y>r.top-22)y=Math.max(76,r.top-48);
  var max=ok?SOCO_HP-SOCO_CACAMBA:SOCO_VIDA,hp=ok?z.hp-SOCO_CACAMBA:z.vida;
  QP.batalha={z:z,x:x,y:y,ok:ok,final:hp===1,dano:Math.round(100*hp/max)-Math.round(100*(hp-1)/max),leve:matchMedia('(prefers-reduced-motion:reduce)').matches};
  var noContato=z.tema==='clinch',delay=noContato?0:.075;QP.batalha.delay=delay;
  // ponytail: especial tipografico no canvas existente, apenas no ultimo acerto da disputa de rua.
  var especial=noContato&&ok&&hp===1;QP.batalha.especial=especial;z.especial=especial;
  if(especial&&!QP.batalha.leve)quizAnima(renderer.domElement,[{translate:'0 0'},{translate:'5px -3px',offset:.2},{translate:'-3px 2px',offset:.5},{translate:'0 0'}],{duration:130});
  QP.started=performance.now();quizFxDraw(QP.started);
  if(aok()){
    var fim=hp===1;
    if(especial){tone(210,38,.22,'sine',.15,delay);nburst(2200,.8,.11,.09,delay,'bandpass',null,420);tone(830,415,.19,'triangle',.045,delay+.015);}
    nburst(1250,.85,.085,.13,0,'bandpass',470); // passagem curta, seguida pelo contato e a cauda tonal
    (noContato?smpE:smp)('soco-'+(1+(Math.random()*4|0)),fim?.8:.66,ok?1.05:.86,0,delay);
    tone(ok?137:101,42,.17,'sine',fim?.27:.20,delay);
    if(ok){var nota=z.combo>1?740:554;tone(nota,nota*.997,.14,'triangle',.082,delay+.009);tone(nota*1.5,nota*1.497,fim?.29:.17,'sine',.055,delay+.045);}
  }
}
function batalhaDesenha(cx,t,h){
  var u=clamp((t-h.delay)/.35,0,1),k=1-Math.pow(1-u,3),base=Math.min(innerWidth/520,1),raio=(h.final?78:57)*base;
  if(t<h.delay)return;
  cx.save();cx.translate(h.x,h.y);var cor=h.ok?'#ffd26b':'#ff927f';
  if(h.especial){
    cx.save();cx.globalAlpha=Math.max(0,Math.min(1,(.29-t)/.08));
    if(!h.leve){cx.rotate(-.13);cx.scale(1+.16*Math.sin(Math.PI*u),1+.16*Math.sin(Math.PI*u));}
    cx.textAlign='center';cx.lineJoin='round';cx.font='italic 1000 '+Math.round(70*Math.max(.65,base))+'px system-ui';
    cx.lineWidth=12;cx.strokeStyle='#21182e';cx.strokeText('POW!',3,4);cx.fillStyle='#eb5c9f';cx.fillText('POW!',3,4);
    cx.lineWidth=6;cx.strokeStyle='#21182e';cx.strokeText('POW!',0,0);cx.fillStyle='#ffe777';cx.fillText('POW!',0,0);cx.restore();
  }
  if(!h.leve&&u<1){
    cx.save();cx.rotate(h.ok?-.34:.34);cx.globalAlpha=(1-u)*.95;cx.strokeStyle=cor;cx.lineWidth=3-2*u;
    cx.beginPath();cx.ellipse(0,0,8+raio*k,5+raio*.60*k,0,0,Math.PI*2);cx.stroke();
    for(var i=0;i<8;i++){cx.rotate(Math.PI/4);var v=raio*(i%2?.52:1.12),ini=6+k*v*.76;
      cx.fillStyle=i%2?cor:'#fff7d7';cx.beginPath();cx.moveTo(ini,-(1-u)*4);cx.lineTo(ini+(1-k)*v+2,0);cx.lineTo(ini,(1-u)*4);cx.closePath();cx.fill();}
    cx.restore();
  }
  var mov=h.leve?0:k;cx.translate(0,(h.especial?43:-14)-mov*23);var tam=(h.final?54:44)*Math.max(.76,base)*(1+(h.leve?0:.15*Math.sin(Math.PI*u)));
  cx.globalAlpha=Math.min(1,(.70-t)/.16);cx.textAlign='center';cx.lineJoin='round';cx.lineWidth=5;cx.strokeStyle='#241b23';
  cx.font='italic 900 '+tam+'px system-ui';var num='−'+h.dano;cx.strokeText(num,0,0);cx.fillStyle=h.ok?'#ffebb5':'#ffc1ad';cx.fillText(num,0,0);
  var faixa=h.final?(h.ok?'GOLPE FINAL':'NOCAUTE'):!h.ok?'CONTRA':h.z.combo>1?'COMBO ×'+h.z.combo:'IMPACTO';
  cx.font='800 12px system-ui';cx.strokeText(faixa,0,17);cx.fillStyle='#fff';cx.fillText(faixa,0,17);cx.restore();
}
function quizFxDraw(now){
  var c=$('quizfx'),cx=c.getContext('2d'),t=Math.max(0,(now-QP.started)/1000),k=Math.min(1,t/.6);cx.clearRect(0,0,c.width,c.height);
  var h=QP.batalha;if(h){
    if(S.soco!==h.z||t>=.70){QP.batalha=null;QP.raf=0;return;}
    batalhaDesenha(cx,t,h);QP.raf=requestAnimationFrame(quizFxDraw);return;
  }
  if(t>=.6){QP.raf=0;return;}
  cx.globalAlpha=1-k;cx.strokeStyle=QP.ok?'#ffe698':'#ff5940';cx.lineWidth=5*(1-k)+1;cx.beginPath();cx.arc(QP.cx,QP.cy,12+t*420,0,Math.PI*2);cx.stroke();
  for(var i=0;i<QP.particles.length;i++){var p=QP.particles[i],x=QP.cx+p.vx*t,y=QP.cy+p.vy*t+220*t*t;cx.fillStyle=i%3?'#ffc53d':'#fff5d0';cx.fillRect(x,y,p.size*(1-k),p.size*(1-k)*2);}
  cx.globalAlpha=1;QP.raf=requestAnimationFrame(quizFxDraw);
}
function quizPunch(z,ok){
  var start=performance.now(),batalha=z.luta&&z.forma==='batalha',anel=BAT<2&&!matchMedia('(prefers-reduced-motion:reduce)').matches;
  quizFxInit();quizFxPara(batalha||anel);z.combo=ok?z.combo+1:0;var special=ok&&z.combo%5===0,f=z.fx;
  if(batalha){z.hitStop=0;if(!ok)f.pain++;if(ok&&z.hp-SOCO_CACAMBA===1)f.special++;batalhaImpacto(z,ok);f.sounds++;}
  else{
  z.hitStop=ok&&z.tema!=='bueiro'?.075:0;if(z.hitStop)f.hitStop++;if(!ok)f.pain++;if(special)f.special++;
  var n=anel&&!BAT&&!MOB&&ok?Math.min(80,24+z.combo*8):0;
  QP.particles.length=0;
  if(anel){
    // Uma superfície por perfil, sem realocar no erro ou combo: 390 px cobrem até a fagulha especial em 0,6 s.
    var c=$('quizfx'),r=$('socoq').getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,h=!BAT&&!MOB?390:268;
    var w=Math.min(2*h,innerWidth),vH=Math.min(2*h,innerHeight),left=clamp(Math.round(x-w/2),0,innerWidth-w),top=clamp(Math.round(y-vH/2),0,innerHeight-vH);
    if(c.width!==w)c.width=w;if(c.height!==vH)c.height=vH;c.style.left=left+'px';c.style.top=top+'px';
    QP.cx=x-left;QP.cy=y-top;QP.ok=ok;QP.started=performance.now();
    for(var i=0;i<n;i++){var a=Math.random()*Math.PI*2,v=(90+Math.random()*260)*(special?1.4:1);QP.particles.push({vx:Math.cos(a)*v,vy:Math.sin(a)*v,size:2+Math.random()*3+Math.min(5,z.combo)*.5});}f.particles+=n;
    quizFxDraw(QP.started);
  }
  var b=$('quizburst');b.style.color=ok?'#ffe895':'#ff705b';b.innerHTML=(ok?'CERTO!':'ERRADO')+(z.combo>1?'<small>'+(special?'LIMITE! ':'COMBO ')+'x'+z.combo+'</small>':'');
  quizAnima(b,!anel?[{opacity:1},{opacity:0}]:ok?[{opacity:0,scale:'.4',easing:'cubic-bezier(.18,.89,.32,1.3)'},{opacity:1,scale:special?'1.35':'1.18',offset:.22,easing:'cubic-bezier(.18,.89,.32,1.3)'},{opacity:1,scale:'1',offset:.75},{opacity:0,scale:'1'}]:[{opacity:1,transform:'translateY(-45px) scale(1.25)'},{opacity:1,transform:'translateY(15px) scale(1)',offset:.4},{opacity:0,transform:'translateY(30px)'}],{duration:ok?390:800,easing:ok?'linear':'ease-in'});
  if(anel)quizAnima($('socoq'),ok?[{opacity:.85},{opacity:1}]:[{transform:'translateX(calc(-50% - 6px))'},{transform:'translateX(calc(-50% + 6px))'},{transform:'translateX(-50%)'}],{duration:ok?300:250});
  if(anel&&!BAT&&z.tema!=='bueiro')quizAnima(renderer.domElement,[{translate:'0 0'},{translate:(special?'9px':'4px')+' -3px'},{translate:'-4px 3px'},{translate:'0 0'}],{duration:special?230:150});
  if(!ok&&anel)quizAnima($('quizpain'),[{opacity:1},{opacity:0}],{duration:650});
  f.sounds++;if(aok()){var pitch=Math.pow(2,(z.combo-1)/12);tone(ok?130:95,35,.18,'sine',ok?.4:.35);if(ok){tone(800*pitch,1600*pitch,.17,'sine',.12);nburst(1500,.6,.16,.13);if(special)tone(1200,2400,.25,'triangle',.12);}}
  }
  if(z.tema==='clinch'){if(impTato(ok?(z.especial&&!QP.batalha?.leve?{pad:[160,1,.8],cel:55}:IMPACTO.soco):IMPACTO.dano))f.vibrations++;}
  else{f.vibrations++;try{var ps=controlesLidos();for(var j=0;j<ps.length;j++){var g=ps[j];if(g&&g.vibrationActuator){var promise=g.vibrationActuator.playEffect('dual-rumble',{duration:ok?120:240,strongMagnitude:ok?.8:.2,weakMagnitude:ok?.5:.15});if(promise&&promise.catch)promise.catch(function(){});}}if(navigator.vibrate)navigator.vibrate(ok?40:100);}catch(e){}}
  f.ms=performance.now()-start;f.maxMs=Math.max(f.maxMs||0,f.ms);
}
function quizScore(ok){
  if(ok){S.combo++;S.prep=Math.min(100,S.prep+Math.round(5*(1+.25*Math.min(S.combo-1,4))*(1+.1*rpgAt('memoria'))));}
  else{var f=Math.max(.3,1-.15*rpgAt('sangue'));S.combo=0;S.clock+=.04*f;say('Errou: -'+Math.max(1,Math.round(3*f))+' min no relógio.','sys',1.4);} /* erro custa tempo, nunca trava */
}
/* ---------- ficha do agente: nivel, XP, atributos e equipamento que mexem no quiz ---------- */
var ITENS={oculos:{n:'Óculos de leitura',s:'cabeca',ic:'👓',b:{foco:2}},bone:{n:'Boné da corporação',s:'cabeca',ic:'🧢',b:{sangue:1}},
  colete:{n:'Colete leve',s:'corpo',ic:'🦺',b:{sangue:2}},jaqueta:{n:'Jaqueta de couro',s:'corpo',ic:'🧥',b:{memoria:1,foco:1}},
  caderno:{n:'Caderno de resumos',s:'acess',ic:'📓',b:{memoria:2}},relogio:{n:'Relógio de prova',s:'acess',ic:'⌚',b:{foco:1}}};
var ATRS={foco:['Foco','+1 s para responder cada questão'],memoria:['Memória','+10% de Preparo em cada acerto'],sangue:['Sangue frio','erro tira 15% menos tempo do relógio']};
var SLOTS={cabeca:'Cabeça',corpo:'Corpo',acess:'Acessório'};
function rpgNew(){return {lvl:1,xp:0,pts:0,at:{foco:0,memoria:0,sangue:0},eq:{cabeca:null,corpo:null,acess:null},inv:['relogio']};}
var RPG=rpgNew();
if(!SELFTEST)try{var _rp=JSON.parse(localStorage.getItem('vda_rpg'));if(_rp&&_rp.at&&_rp.eq&&_rp.inv)RPG=_rp;}catch(e){}
function rpgSave(){$('bPl').textContent=RPG.lvl;if(SELFTEST)return;try{localStorage.setItem('vda_rpg',JSON.stringify(RPG));}catch(e){}}
function rpgAt(k){var v=RPG.at[k]||0;for(var s in RPG.eq){var it=ITENS[RPG.eq[s]];if(it&&it.b[k])v+=it.b[k];}return v;}
function rpgNeed(){return 100*RPG.lvl;}
function gainXP(n){
  RPG.xp+=n;
  while(RPG.xp>=rpgNeed()){
    RPG.xp-=rpgNeed();RPG.lvl++;RPG.pts++;
    var novo=Object.keys(ITENS).filter(function(k){return RPG.inv.indexOf(k)<0;})[0];
    if(novo)RPG.inv=RPG.inv.concat([novo]);
    say('Subiu para o nível '+RPG.lvl+'! +1 ponto de atributo'+(novo?' e '+ITENS[novo].n+' na mochila':'')+' ({{ficha}})','sys',2.6);sfx('ok');
  }
  rpgSave();if($('rpg').classList.contains('on'))rpgDraw();
}
function rpgEquip(id){var it=ITENS[id];if(!it||RPG.inv.indexOf(id)<0)return;RPG.eq[it.s]=RPG.eq[it.s]===id?null:id;rpgSave();rpgDraw();}
function rpgPt(k){if(RPG.pts<1||!(k in RPG.at))return;RPG.pts--;RPG.at[k]++;rpgSave();rpgDraw();}
function rpgBon(it){return Object.keys(it.b).map(function(k){return '+'+it.b[k]+' '+ATRS[k][0];}).join(' · ');}
function rpgDraw(){
  $('rpgN').textContent=HERO;$('rpgL').textContent=RPG.lvl;
  $('rpgX').style.transform='scaleX('+(RPG.xp/rpgNeed())+')';
  $('rpgXt').textContent='Experiência '+RPG.xp+' / '+rpgNeed()+' · acerto +10 · bandido abatido +25'+(RPG.pts?' · '+RPG.pts+' ponto'+(RPG.pts>1?'s':'')+' livre'+(RPG.pts>1?'s':''):'');
  $('rpgA').innerHTML=Object.keys(ATRS).map(function(k){
    var b=RPG.at[k],t=rpgAt(k),p='';for(var i=0;i<10;i++)p+='<i class="'+(i<b?'on':i<t?'eq':'')+'"></i>';
    return '<div class="at"><b>'+ATRS[k][0]+'</b><em>'+t+'</em><button type="button" data-pt="'+k+'"'+(RPG.pts?'':' disabled')+' aria-label="Subir '+ATRS[k][0]+'">+</button><div class="pips">'+p+'</div><small>'+ATRS[k][1]+'</small></div>';
  }).join('');
  $('rpgE').innerHTML=Object.keys(SLOTS).map(function(s){
    var it=ITENS[RPG.eq[s]];
    return it?'<button type="button" class="sl on" data-eq="'+RPG.eq[s]+'"><span class="ic">'+it.ic+'</span><span>'+it.n+'<small>'+SLOTS[s]+' · '+rpgBon(it)+' · toque para tirar</small></span></button>'
      :'<div class="sl vz"><span class="ic">·</span><span>'+SLOTS[s]+'<small>vazio</small></span></div>';
  }).join('');
  $('rpgI').innerHTML=RPG.inv.map(function(id){
    var it=ITENS[id],on=RPG.eq[it.s]===id;
    return '<button type="button" class="sl'+(on?' on':'')+'" data-eq="'+id+'"><span class="ic">'+it.ic+'</span><span>'+it.n+'<small>'+SLOTS[it.s]+' · '+rpgBon(it)+(on?' · equipado':'')+'</small></span></button>';
  }).join('');
}
function rpgOpen(pausa){if(!pausa&&S.phase!=='play')return;if(pausa){RPG_PAUSA=S.phase;$('opt').classList.add('optSub');$('rpgC').firstChild.nodeValue='Voltar à pausa ';}else $('rpgC').firstChild.nodeValue='Voltar à rua ';rpgDraw();$('rpg').classList.add('on');S.phase='ui';if(document.exitPointerLock&&document.pointerLockElement)document.exitPointerLock();}
function rpgClose(){if(!$('rpg').classList.contains('on'))return;$('rpg').classList.remove('on');if(RPG_PAUSA!==null){S.phase=RPG_PAUSA;RPG_PAUSA=null;$('opt').classList.remove('optSub');PADUI.root=null;menuSync();menuFocus($('optFicha'));}else S.phase='play';}
$('rpg').addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;if(b.dataset.pt)rpgPt(b.dataset.pt);else if(b.dataset.eq)rpgEquip(b.dataset.eq);else if(b.id==='rpgC')rpgClose();});
$('bP').addEventListener('click',function(){if($('rpg').classList.contains('on'))rpgClose();else rpgOpen();});
document.addEventListener('keydown',function(e){
  if(e.code!=='KeyI'&&e.code!=='Escape')return;
  if($('rpg').classList.contains('on')){rpgClose();e.preventDefault();}
  else if(e.code==='KeyI')rpgOpen();
});
rpgSave();
