/* ---------- entrada nova: sacar/guardar (Q), mirar (segura botao direito ou F), atirar (clique), recarregar (T), Central (B) ---------- */
document.addEventListener('keydown',function(e){
  if(S.phase!=='play')return;
  if(e.code==='KeyQ'&&!e.repeat){draw();}
  else if(e.code==='KeyT')reload();
  else if(e.code==='KeyB'&&EP.on)central();
  else if(e.code==='Digit1'&&CB.drawn)CB.item=0;
  else if(e.code==='Digit2'&&CB.drawn)CB.item=1;
});
(function(){
  var cv=$('c');
  cv.addEventListener('mousedown',function(e){if(S.phase!=='play')return;if(e.button===2){if(!CB.drawn)draw(true);CB.aimHold=CB.drawn;var sn=CB.drawn&&aaAlvo(1.2);if(sn)aaPuxa(sn,1,.5*aaM());e.preventDefault();}else if(e.button===0&&CB.drawn)tiroCad();});
  document.addEventListener('mouseup',function(e){if(e.button===2)CB.aimHold=false;});
  cv.addEventListener('contextmenu',function(e){e.preventDefault();});
  /* botao de tiro: segura = rajada; arrastar o dedo no botao tambem mira */
  var bF=$('bF'),fp=null,fx=0,fy=0;
  bF.addEventListener('pointerdown',function(ev){ev.preventDefault();ev.stopPropagation();audioInit();bF.classList.add('dn');fp=ev.pointerId;fx=ev.clientX;fy=ev.clientY;try{bF.setPointerCapture(fp);}catch(e){}if(!CB.drawn&&!S.inCar){draw();return;}/* arma guardada: 1o toque saca */CB.fireHold=true;CB.fireCD=0;});
  bF.addEventListener('pointermove',function(ev){if(ev.pointerId!==fp)return;if(S.phase==='play')lookBy((ev.clientX-fx)*1.25,(ev.clientY-fy)*1.25);fx=ev.clientX;fy=ev.clientY;});
  ['pointerup','pointercancel','lostpointercapture'].forEach(function(t){bF.addEventListener(t,function(ev){if(ev.pointerId!==fp)return;fp=null;CB.fireHold=false;bF.classList.remove('dn');});});
  /* MIRA (celular): segura para mirar, solta para voltar; captura garante soltar fora do botao. */
  var bA=$('bA'),ap=null;
  bA.addEventListener('pointerdown',function(ev){ev.preventDefault();ev.stopPropagation();if(ap!==null||INPUT!=='toque'||!CB.drawn||S.inCar||S.phase!=='play'||cenaOn())return;audioInit();ap=ev.pointerId;CB.aimHold=true;try{bA.setPointerCapture(ap);}catch(e){}});
  ['pointerup','pointercancel','lostpointercapture'].forEach(function(t){bA.addEventListener(t,function(ev){if(ev.pointerId!==ap)return;ap=null;CB.aimHold=false;});});
  addEventListener('blur',function(){ap=null;CB.aimHold=false;});
  var bR=$('bR');
  $('bM').addEventListener('pointerdown',function(ev){ev.preventDefault();ev.stopPropagation();audioInit();reload();});
})();

