  poster(M.g,'LEVE 3','PAGUE 3',-3.9,2.0,-M.d/2+.35,0,1.8,1.3);
  poster(M.g,'PROMOÇÃO VÁLIDA','ONTEM',-1.6,2.0,-M.d/2+.35,0,1.8,1.3);
