/* ====================== FLUXO DO EPISODIO ====================== */
function seq(lines,cb){
  var t=0;lines.forEach(function(l){later(t,function(){say(l[0],l[1]||'npc',3.2);});t+=3.3;});
  if(cb)later(t,cb);
}
function epReset(){
  EP={on:false,step:'',ring:false,baileMk:false,baile:{x:BAILE.gate[0],z:BAILE.gate[2]},ringR:26,susp:50,disguise:false,hasShirt:false,seeD:18,reforco:false,
      reforcoUsed:false,mapOn:false,cidaStage:0,cidaFollow:false,pipoca:false,path:'',t0:0,flyT:0,truckAt:0,erros:0,late:false,hide:false};
  FAILING=false;GUARDS.forEach(gReset);
  if(W.cida){var n=W.cida;n.x=W.merc.x+7.2;n.z=W.merc.z+2.6;n.m.rotation.x=0;n.m.position.set(n.x,surfaceY(n.x,n.z),n.z);}
  if(W.jun){W.jun.m.rotation.x=0;}
  if(W.cage&&NPCBY.zoio){var z=NPCBY.zoio;z.x=z.home[0];z.z=z.home[1];z.fleeT=0;z.hold=true;z.m.position.set(z.x,z.y,z.z);}
}
epReset();cbReset();
function epStart(){
  epReset();cbReset();EP.on=true;EP.step='ep_juninho';S.clock=17.8;S.prep=S.prep||0;
  setObj('Chamado: cachorro Pipoca sumiu. Falar com Juninho (casa verde)');setMark(W.casaM);
  seq([['Central: '+HERO+', chamado da Vila de Abril: Pipoca, caramelo, sumiu.','radio'],['Central: Moradora idosa também desaparecida. Fala com o filho.','radio']]);
}
function epEnd(){}
function epTarget(){
  if(!EP.on||S.inCar||S.phase!=='play')return null;
  var s=EP.step;
  if(s==='ep_juninho'&&nearNPC('juninho',3.4))return {label:tecla('acao')+' · Falar com Juninho',fn:talkJuninho};
  if(s==='ep_achar'&&nearNPC('cida',3.2))return {label:tecla('acao')+' · Falar com a senhora',fn:findCida};
  if(s==='ep_achar'&&dist2(P.x,P.z,W.merc.x,W.merc.z)<14){
    if(nearNPC('acougueiro',3))return {label:tecla('acao')+' · Falar com o açougueiro',fn:function(){seq([['Açougueiro: Picanha a R$ 19,90, pô. Mas a placa é de ontem.'],['Moleque, tem senhora de rosa perto da geladeira. Fala sozinha.']]);EP.clue=1;}};
  }
  if(dist2(P.x,P.z,W.merc.x+0,W.merc.z+0)<14&&nearNPC('caixa',3))return {label:tecla('acao')+' · Comprar camisa de baile (R$ 40)',fn:buyShirt};
  if(s==='ep_levar'&&dist2(P.x,P.z,W.casa.x,W.casa.z)<8)return {label:tecla('acao')+' · Deixar a Dona Cida em casa',fn:cidaHome};
  if((s==='ep_espera'||s==='ep_portao'||s==='ep_levar')&&dist2(P.x,P.z,W.bench.x,W.bench.z)<3)return {label:tecla('acao')+' · Esperar no banco',fn:benchMenu};
  if(s==='ep_portao'&&(nearNPC('seguranca',3.6)||nearNPC('gerente',3.6)))return {label:tecla('acao')+' · Falar com a segurança do baile',fn:gateMenu};
  if(s==='ep_campo'&&nearNPC('zoio',3.4)&&!EP.duelDone)return {label:tecla('acao')+' · Encarar o Zóio',fn:duelStart};
  if((s==='ep_campo'||s==='ep_volta')&&!EP.pipoca&&dist2(P.x,P.z,W.cage.x,W.cage.z)<2.4)return {label:tecla('acao')+' · Abrir a jaula do Pipoca',fn:grabPipoca};
  if(s==='ep_volta'&&dist2(P.x,P.z,W.casa.x,W.casa.z)<8)return {label:tecla('acao')+' · Entrar com o Pipoca',fn:finalScene};
  return null;
}
function talkJuninho(){
  EP.step='ep_ocupado';
  seq([['Juninho: Foi no mercado faz 3 hora, pô. Mãe sempre volta.','npc'],['Juninho: Tô no meio da fase, pô, policial. Não pausa.','npc'],[HERO+': Ela tem 80 anos. Onde ela vai?','npc'],['Juninho: Mercado Joia. Ou na pracinha, pô. Sei lá.','npc']],function(){
    EP.step='ep_achar';setObj('Achar a Dona Cida (Mercado Joia)');setMark([W.merc.x,3,W.merc.z+W.merc.d/2]);});
}
function findCida(){
  EP.step='ep_ocupado';EP.cidaStage=0;
  seq([['Dona Cida: Davizinho! Meu neto! Você cresceu tanto.','npc'],[HERO+': Dona Cida, vamos pra casa. Eu levo a senhora.','npc'],['Dona Cida: Eu não lembro onde moro, filho. Mas lembro do Pipoca.','npc'],['Dona Cida: É a única coisa que me deixa feliz.','npc']],function(){
    EP.step='ep_levar';EP.cidaFollow=true;setObj('Levar a Dona Cida para casa');setMark(W.casaM);});
}
function buyShirt(){
  if(EP.hasShirt){say('Caixa: Já levou a camisa, doutor.','npc',undefined,'Caixa');return;}
  if(S.rs<40){say('Caixa: Sem trocado. O carnê é em até 235x.','npc',undefined,'Caixa');return;}
  S.rs-=40;EP.hasShirt=true;sfx('cash');say('Camisa de baile comprada (-R$ 40).','sys');
}
function cidaHome(){
  EP.step='ep_ocupado';EP.cidaFollow=false;EP.cidaStage=1;
  var n=W.cida;n.x=W.casa.x+3.4;n.z=W.casa.z-1.2;n.m.position.set(n.x,surfaceY(n.x,n.z),n.z);n.m.rotation.x=.12;
  seq([['Dona Cida: Pipoca ia comer aqui, sabe? Ele sumiu do portão.','npc'],['Dona Cida: Levaram ele pro baile. Eu vi. Pessoal do baile.','npc'],['Juninho: Pô... ela fala isso todo dia, policial.','npc']],function(){
    epEspera();});
}
function epEspera(){
  EP.step='ep_espera';EP.ring=true;EP.baileMk=true;
  say('O baile começa às 23h. Espere ou vá agora.','sys',5);
  setObj('O baile começa às 23h. Espere no banco ou vá agora.');setMark([EP.baile.x,3,EP.baile.z]);
  if(S.clock>=23)epPortao();
}
function epPortao(){EP.step='ep_portao';setObj('Chegar ao portão do baile (área restrita)');}
function skipTo(h){
  if(h<S.clock)h+=24;
  S.clock=h;EP.lastN=-1;say('Passam as horas. São '+fmtClock(S.clock)+'.','sys',3);
  if(EP.step==='ep_espera'&&S.clock>=23)epPortao();
}
function benchMenu(){
  showDec('BANCO DA PRAÇA','Passar o tempo','Agora são '+fmtClock(S.clock)+'. O baile começa às 23h.',[
    {t:'Esperar até as 23h',s:'o céu escurece',fn:function(){closeDecPlay();skipTo(23);}},
    {t:'Esperar até as 5h',s:'baile quase vazio',fn:function(){closeDecPlay();skipTo(29);}},
    {t:'Levantar',s:'',fn:closeDecPlay}]);
}
/* portao: 5 caminhos */
function gatePath(p){
  EP.path=p;
  if(p==='farda'){say('Segurança: Farda não entra aqui, não, doutor.','npc',3,'Segurança');EP.susp=Math.min(100,EP.susp+20);return false;}
  if(p==='disfarce'){if(!EP.hasShirt){say('Sem camisa de baile, o disfarce não cola.','sys');return false;}EP.disguise=true;EP.susp=Math.max(0,EP.susp-40);return gateOpen('Segurança: Cola aí, tá na lista.');}
  if(p==='suborno'){if(S.rs<100){say('Faltam R$ 100.','sys');return false;}S.rs-=100;sfx('cash');addKarma(-10);return gateOpen('Segurança: Vi nada, pô.');}
  if(p==='forca'){addKarma(-8);GUARDS.forEach(function(g){gAlert(g);});EP.late=true;return gateOpen('Segurança cai. Alarme tocando.');}
  if(p==='espera'){if(S.clock<29){skipTo(29);}return gateOpen('Segurança: Baile acabou, porra. Entra e some.');}
  if(p==='argumento'){argStart();return null;}
}
function gateOpen(msg){say(msg,'npc',3,'seguranca');EP.step='ep_campo';setObj('Achar o Zóio no campo (atrás do baile)');setMark([W.campo.x,3,W.campo.z]);return true;}
function gateMenu(){
  showDec('PORTÃO DO BAILE','Segurança barra a entrada','Cinco jeitos de passar. Nenhum é de graça.',[
    {t:'Entrar de farda',s:'não vai colar',fn:function(){closeDecPlay();gatePath('farda');}},
    {t:'Disfarce (camisa de baile)',s:EP.hasShirt?'sem chamar atenção':'compre no mercado',fn:function(){closeDecPlay();gatePath('disfarce');}},
    {t:'Argumentar com o Gerente',s:'3 rodadas',fn:function(){closeDec();gatePath('argumento');}},
    {t:'Subornar (R$ 100)',s:'karma cai',fn:function(){closeDecPlay();gatePath('suborno');}},
    {t:'Força',s:'o campo fica em alerta',fn:function(){closeDecPlay();gatePath('forca');}},
    {t:'Esperar até as 5h',s:'baile esvazia',fn:function(){closeDecPlay();gatePath('espera');}},
    {t:'Sair',s:'',fn:closeDecPlay}]);
}
function argStart(){EP.arg={i:0,score:0};argRound();}
function argRound(){
  var A=EP.arg,R=ARGS.gerente[A.i];
  showDec('ARGUMENTAÇÃO · RODADA '+(A.i+1)+'/3',R.f,'Escolha o que dizer. A terceira rodada fecha o acordo.',R.r.map(function(r){return {t:r[0],s:'',fn:function(){A.score+=r[1];A.i++;if(A.i>=3)argEnd();else argRound();}};}));
}
function argEnd(){
  var ok=EP.arg.score>=4;
  closeDecPlay();
  if(ok){addKarma(4);gateOpen('Gerente: Tá bom. Vai direto, sem barulho.');}
  else{say('Gerente: Não rola. Volta quando tiver convite.','npc',3,'Gerente');EP.susp=Math.min(100,EP.susp+15);}
  return ok;
}
/* duelo de flashcards com o Zoio */
function duelStart(){
  EP.duel={i:0,erros:0,tk:0};duelCard();
}
function duelCard(){
  var D=EP.duel,c=CARTAS[D.i];D.tk++;var tk=D.tk;
  showDec('DUELO COM O ZÓIO · '+(D.i+1)+'/'+CARTAS.length+' · erros '+D.erros+'/2',c.q,'8 s por carta. Acertar traz o Pipoca de volta sem tiro.',c.o.map(function(t,k){return {t:t,s:'',fn:function(){duelAns(k===c.a,tk);}};}));
  later(8,function(){if(EP.duel&&EP.duel.tk===tk&&S.decOpts&&$('dec').classList.contains('on'))duelAns(false,tk,true);});
}
function duelAns(ok,tk,timeout){
  var D=EP.duel;if(!D||tk!==D.tk)return;
  var c=CARTAS[D.i];if(!ok)cadRegistra(c,'Duelo com o Zóio');
  if(ok){S.acertos++;sfx('ok');S.prep=Math.min(100,S.prep+6);}else{S.erros++;D.erros++;sfx('bad');}
  say((ok?'Certo. ':(timeout?'Tempo. ':'Errou. '))+c.x,'sys',3.6);
  D.i++;
  if(D.erros>=2){closeDecPlay();EP.duelDone=true;EP.duel=null;duelFail();return;}
  if(D.i>=CARTAS.length){closeDecPlay();EP.duelDone=true;EP.duel=null;duelWin();return;}
  duelCard();
}
function duelWin(){
  addKarma(5);addPts(40);var z=NPCBY.zoio;z.kind='civil';
  seq([['Zóio: Tá bom, tá bom. Você manja de lei, doutor.','npc'],['Zóio: Leva o cachorro, porra. Fala que não fui eu.','npc']]);
  setObj('Abrir a jaula e pegar o Pipoca');setMark([W.cage.x,2,W.cage.z]);
}
function duelFail(){
  var z=NPCBY.zoio;z.fleeT=6;z.hold=false;
  GUARDS.forEach(function(g){gAlert(g);});say('Zóio: Pega o policial, caralho!','npc',2.5,'Zóio');
  setObj('Abrir a jaula e pegar o Pipoca antes que os vigias te peguem');setMark([W.cage.x,2,W.cage.z]);
}
function grabPipoca(){
  EP.pipoca=true;EP.step='ep_volta';sfx('bark');addKarma(3);
  S.dogMode='ep';
  say(HERO+': Vem, Pipoca. Vamos pra casa.','npc',3);
  setObj('Levar o Pipoca para a Dona Cida');setMark(W.casaM);
}
/* final: Dona Cida debilitada, cena digna */
function finalScene(){
  EP.step='ep_final';EP.cidaStage=2;
  var n=W.cida;n.m.rotation.x=-1.45;n.x=W.casa.x+3.4;n.z=W.casa.z-2.4;n.m.position.set(n.x,surfaceY(n.x,n.z)+.62,n.z);
  W.jun.face={x:W.casa.x-3.2,z:W.casa.z+2};
  emoMusic();
  var steps=[
   ['Dona Cida está deitada. A voz sai baixinha.','Dona Cida: Eu sei que a cabeça não é mais minha. Esqueço o nome dos meus filhos.','Dona Cida: Mas esse aqui eu conheço.'],
   ['Pipoca sobe na cama e deita ao lado dela. Ela o abraça.','Dona Cida: Agora eu posso descansar. Tá tudo em ordem.','A respiração fica leve. Ela dorme, e não acorda.'],
   ['Juninho: Pô... vou terminar a fase.','O policial ajoelha ao lado do cachorro.','Policial: Vem comigo, Caramelo. Agora você é meu.'],
   ['Tem gente que ninguém cuida.','Quem cuida de quem ninguém cuida é quem veste essa farda de verdade.']];
  var i=0;(function next(){
    if(i>=steps.length){closeDecPlay();epGrade();return;}
    var s=steps[i++];showDec('EPISÓDIO 1 · O CARAMELO DA DONA CIDA','',s.join('\n'),[{t:'Continuar',s:'',fn:next}]);
  })();
}
function epGrade(){
  var tot=S.acertos+S.erros;
  showEnd('ep1','EPISÓDIO 1 · CONCLUÍDO','Distrito liberado','Karma '+S.karma+' · caminho: '+(EP.path||'sem registro')+' · acertos '+S.acertos+'/'+tot+' · horário '+fmtClock(S.clock),'Isto é o Episódio 1. Próximos quarteirões chegam em breve.');
}
function emoMusic(){
  if(!aok())return;
  [[261.6,0],[329.6,.4],[392,.8],[523.3,1.4],[440,2.4],[349.2,3.2],[392,4]].forEach(function(n){try{var t0=AC.currentTime+n[1];var o=AC.createOscillator(),g=AC.createGain();o.type='sine';o.frequency.value=n[0];g.gain.setValueAtTime(0,t0);g.gain.linearRampToValueAtTime(.09,t0+.5);g.gain.linearRampToValueAtTime(0,t0+3.2);o.connect(g);g.connect(AU.musG);o.start(t0);o.stop(t0+3.4);}catch(e){}});
}
/* update do episodio: relogio, Dona Cida, moscas, carro de som, guardas, pipoca, falha */
function epUpdate(dt){
  if(!EP.on)return;
  if(S.phase==='play'||S.phase==='cut')S.clock+=dt*0.012;
  if(S.clock>=29.5)S.clock-=24;
  if(EP.step==='ep_espera'&&S.clock>=23)epPortao();
  GUARDS.forEach(function(g){gUpdate(g,dt);});
  if(W.casa)doorTick(W.casa,dt);if(W.merc)doorTick(W.merc,dt);
  var n=W.cida;
  if(EP.cidaFollow){
    var dx=P.x-n.x,dz=P.z-n.z,d=Math.hypot(dx,dz);
    if(d>2.2){var sp=1.9;n.x+=dx/d*sp*dt;n.z+=dz/d*sp*dt;_cp.x=n.x;_cp.z=n.z;hit(_cp,.4,[]);n.x=_cp.x;n.z=_cp.z;n.yaw+=dAng(n.yaw,yawTo(dx,dz))*Math.min(1,dt*6);animPerson(n.m,dt,1.3,'walk',n.y);}
    n.y=npcY(n);n.m.position.set(n.x,n.y,n.z);n.m.rotation.y=n.yaw;n.m.rotation.x=.08;
  }
  if(W.flies){EP.flyT+=dt;W.flies.forEach(function(f,i){var a=EP.flyT*(3+i*.4)+i*2;f.position.set(-4.2+Math.cos(a)*.5,1.9+Math.sin(a*1.7)*.2,-4.4+Math.sin(a)*.5);});}
  if(W.truck){W.truck.t-=dt;if(W.truck.t<=0&&S.phase==='play'&&dist2(P.x,P.z,W.truck.x,W.truck.z)<40){W.truck.t=22;say('Carro de som: Frango a R$ 9,99! Só hoje! Todo dia!','npc',3.2,'Carro de som');}}
  if(EP.pipoca&&S.dogMode==='ep'){var r=ref();var dd=dist2(DG.x,DG.z,r.x,r.z);if(dd>2.2)dogGo(r.x,r.z,clamp(2+dd*.5,2,12),dt);}
  else if(!EP.pipoca&&W.cage&&S.dogMode==='ep'){DG.x=W.cage.x;DG.z=W.cage.z-1.2;}
  if(CB.hp<=0&&!lifeActive()&&!FAILING&&!lifeStart())failRun('Sua vida acabou. A missão fica para o próximo plantão.');
}
