        if(!Number.isFinite(medidas.tiro.transiente)||medidas.tiro.transiente<.77||medidas.tiro.transiente>.8005)erros.push('transiente pistola fora de .77 a .8005: '+medidas.tiro.transiente);
        medidas.rifleVsPistolaDB=20*Math.log10(medidas.rifle.transiente/medidas.tiro.transiente);
        medidas.caudaAbaixoAtaqueDB=20*Math.log10(medidas.rifle.transiente/medidas.rifle.cauda);
