  T('ceu estrelas 11/11: ponto de luz redondo e suave, sem quadrado de PR 0,5 a 3, tamanhos e brilhos variados',function(){
    var U=skyU,ks=['cZen','cMid','cHor','cGold','cGround'],k0={},n0=U.noite.value,t0=U.time.value,rt0=renderer.getRenderTarget(),N=256,
      rt=new THREE.WebGLRenderTarget(N,N),sc=new THREE.Scene(),cam=new THREE.PerspectiveCamera(20,1,.1,2000),px=new Uint8Array(N*N*4),R=10,tam=[],pic=[],vistos=0,ruim=[];
    var domo=new THREE.Mesh(skyMesh.geometry,skyMat),sem=skyMat.clone(),fundo=new Uint8Array(px.length),brilhos=new Uint8Array(N*N);
    sem.uniforms=U;sem.fragmentShader=sem.fragmentShader.replace(CEU_ESTRELAS_GLSL,'');sc.add(domo);
    ks.forEach(function(k){k0[k]=U[k].value.clone();U[k].value.copy(NIGHT[k]);});
    try{U.noite.value=.25;U.time.value=0;
      /* fov 44/20/7 em 256 px = 317/726/2093 px por radiano ~ tela 1440 em PR 0,5/1/3 */
      [[44,'PR0.5'],[20,'PR1'],[7,'PR3']].forEach(function(f){cam.fov=f[0];cam.updateProjectionMatrix();
        for(var v=0;v<9;v++){var a=v*.7;cam.position.set(0,0,0);cam.up.set(0,0,1);cam.lookAt(v?Math.cos(a)*.45:0,1,v?Math.sin(a)*.45:.001);
          renderer.setRenderTarget(rt);domo.material=sem;renderer.render(sc,cam);renderer.readRenderTargetPixels(rt,0,0,N,N,fundo);
          domo.material=skyMat;renderer.render(sc,cam);renderer.readRenderTargetPixels(rt,0,0,N,N,px);
          for(var z=0;z<N*N;z++){var off=z*4;brilhos[z]=Math.max(0,px[off]-fundo[off],px[off+1]-fundo[off+1],px[off+2]-fundo[off+2]);}
          var L=function(x,y){return brilhos[y*N+x];};
          for(var y=R;y<N-R;y++)for(var x=R;x<N-R;x++){var c=L(x,y),mx=true,bg=255;
            for(var j=-R;j<=R&&mx;j++)for(var i=-R;i<=R;i++){var q=L(x+i,y+j);if(q<bg)bg=q;if((i||j)&&(q>c||(q===c&&(j<0||(j===0&&i<0))))){mx=false;break;}}
            if(!mx||c-bg<12)continue;var pk=c-bg,n50=0,n95=0,x0=x,x1=x,y0=y,y1=y;
            for(j=-R;j<=R;j++)for(i=-R;i<=R;i++){q=L(x+i,y+j)-bg;if(q>=pk*.5){n50++;x0=Math.min(x0,x+i);x1=Math.max(x1,x+i);y0=Math.min(y0,y+j);y1=Math.max(y1,y+j);}if(q>=pk*.95)n95++;}
            var w=x1-x0+1,hh=y1-y0+1;vistos++;
            if(n50>=6&&n95>n50*.6)ruim.push(f[1]+' plato '+n95+'/'+n50);
            if(n50>=6&&Math.max(w,hh)>1.6*Math.min(w,hh))ruim.push(f[1]+' esticada '+w+'x'+hh);
            if(n50>=12&&n50/(w*hh)>.9)ruim.push(f[1]+' quadrada '+n50+'/'+(w*hh));
            if(f[1]==='PR3'){tam.push(n50);pic.push(pk);}}}});
      tr(!ruim.length,'estrela quadrada/chapada: '+ruim.slice(0,6).join(', '));tr(vistos>=10,'poucas estrelas vistas '+vistos);
      tr(tam.length>=4,'poucas estrelas em PR3 '+tam.length);
      tr(Math.max.apply(null,tam)>=2*Math.min.apply(null,tam),'tamanho igual '+tam.join(','));tr(Math.max.apply(null,pic)>=1.5*Math.min.apply(null,pic),'brilho igual '+pic.join(','));
    }finally{U.noite.value=n0;U.time.value=t0;ks.forEach(function(k){U[k].value.copy(k0[k]);});renderer.setRenderTarget(rt0);sem.dispose();rt.dispose();}
  });
