          if(size[0]===960&&size[1]===540&&['demoAviso','loadT','demoPresente','s4pOf'].includes(e.id))tr(parseFloat(doc.defaultView.getComputedStyle(e).fontSize)>=(e.id==='s4pOf'?11:12),'fonte pequena '+e.id+' '+estado);
