  T('polir: quatro faixas sem objetos na area e na frente (triangulos e instancias)',function(){
    scene.updateMatrixWorld(true);var banners=GP.decor.getObjectByName('galpao-faixas'),tri=new THREE.Box3(),p=new THREE.Vector3(),mat=new THREE.Matrix4(),world=new THREE.Matrix4();
    GP.faixas.forEach(function(f){var hits=[];
      scene.traverse(function(m){if(!m.isMesh||m===banners||!m.geometry||!m.geometry.attributes.position||m.geometry.isInstancedBufferGeometry||m.material.visible===false||m.name==='folhas')return;
        var g=m.geometry,a=g.attributes.position,ix=g.index,ct=ix?ix.count:a.count;
        if(!g.boundingBox)g.computeBoundingBox();
        for(var k=0;k<(m.isInstancedMesh?m.count:1);k++){
          if(m.isInstancedMesh){m.getMatrixAt(k,mat);world.multiplyMatrices(m.matrixWorld,mat);}else world.copy(m.matrixWorld);
          if(!g.boundingBox.clone().applyMatrix4(world).intersectsBox(f.area))continue;
          for(var i=0;i<ct;i+=3){tri.makeEmpty();for(var j=0;j<3;j++){p.fromBufferAttribute(a,ix?ix.getX(i+j):i+j).applyMatrix4(world);tri.expandByPoint(p);}
            if(Number.isFinite(tri.min.x+tri.min.y+tri.min.z+tri.max.x+tri.max.y+tri.max.z)&&tri.intersectsBox(f.area)){hits.push(m.name||m.id);break;}
          }
        }
      });eq(hits.length,0,f.nome+': '+hits.join(','));
    });
  });
