  function faceNPCs(){return GLS.filter(function(n){return n.m.userData.fc&&!n.m.userData.prof;});}
  function headWeight(o,i){var a=o.geometry.attributes,w=0;for(var j=0;j<4;j++)if(o.skeleton.bones[a.skinIndex.array[i*4+j]].name==='Head')w+=a.skinWeight.array[i*4+j];return w>.5;}
  function staticFace(n){
    var f=n.m.userData.fc,groups={},v=new THREE.Vector3(),parent={},height={};n.m.updateMatrixWorld(true);
    function root(k){while(parent[k]!==k){parent[k]=parent[parent[k]];k=parent[k];}return k;}
    n.m.userData.gl.s.traverse(function(o){
      if(!o.isSkinnedMesh||!o.visible)return;var g=o.geometry,a=g.attributes,mat=o.material,ix=g.index.array,cv=mat.map&&mat.map.image,ctx=cv&&cv.getContext('2d'),skin=ctx&&ctx.getImageData(0,0,1,1).data;
      function dark(i){if(!headWeight(o,i))return false;if(mat.name==='Eyes')return true;if(!ctx)return false;
        var row=Math.floor(a.uv.getY(i)*cv.height);if(row<6||row>=11)return false;var rgb=ctx.getImageData(0,row,1,1).data;return rgb[0]!==skin[0]||rgb[1]!==skin[1]||rgb[2]!==skin[2];}
      var keys={};function key(i){if(keys[i])return keys[i];v.fromBufferAttribute(a.position,i);o.boneTransform(i,v);o.localToWorld(v);f.group.worldToLocal(v);var k=o.uuid+':'+v.toArray().map(function(x){return x.toFixed(5);}).join(',');parent[k]=k;height[k]=v.y;return keys[i]=k;}
      for(var i=0;i<ix.length;i+=3){var ids=[ix[i],ix[i+1],ix[i+2]];if(!ids.every(dark))continue;var ks=ids.map(key);for(var j=1;j<3;j++)parent[root(ks[j])]=root(ks[0]);}
    });
    Object.keys(parent).forEach(function(k){var r=root(k);if(!groups[r])groups[r]=[];groups[r].push(height[k]);});
    var count={eyes:0,mouths:0};Object.keys(groups).forEach(function(k){var ys=groups[k],y=(Math.min.apply(null,ys)+Math.max.apply(null,ys))/2;count[y>(f.fit.ey+f.fit.my)/2?'eyes':'mouths']++;});return count;
  }
