  function caminhoSub(de,ate){
    // 0.5 m grid, player's full radius, actual lower-layer colliders and floor volumes.
    function livre(x,z){var p={x:x,z:z,y:-4};if(!pisoEm(p))return false;
      return !COL_SUB.some(function(b){if(b.ativo===false)return false;var dx=x-clamp(x,b[0],b[2]),dz=z-clamp(z,b[1],b[3]);return dx*dx+dz*dz<.4*.4;});}
    var fila=[[Math.round(de[0]*2)/2,Math.round(de[1]*2)/2]],vistos=new Set(),head=0;
    while(head<fila.length){var q=fila[head++],key=q.join(',');if(vistos.has(key)||!livre(q[0],q[1]))continue;vistos.add(key);
      if(Math.hypot(q[0]-ate[0],q[1]-ate[1])<.51)return true;
      [[.5,0],[-.5,0],[0,.5],[0,-.5]].forEach(function(d){var x=q[0]+d[0],z=q[1]+d[1];if(!vistos.has(x+','+z)&&livre(x,z))fila.push([x,z]);});}
    return false;
  }
