  /* CEO 09/11 05h15 escolta GUIADA: o heroi vai pela rota na velocidade vel(t) (para quando encosta nela); mede Marlene na frente, maior salto, parede e fala cortada */
  function c2segue(pts,vel,stage,lim,o){o=o||{};var r=rotaMake(pts),m=NPCBY.marlene,c=S.marlene,ps=0,t=0,fr=0,ahead=0,jump=0,last=[m.x,m.z],dt=1/20,cort=[],reg=[],p0=rotaAt(r,0);
    P.x=p0[0]-p0[2]*1.5;P.z=p0[1]-p0[3]*1.5;P.y=GY;
    while(c.stage===stage&&t<lim){var v=typeof vel==='function'?vel(t):vel;
      if(v>0){var q=rotaAt(r,Math.min(r.L,ps+v*dt));if(v>=6||dist2(q[0],q[1],m.x,m.z)>.8){ps=Math.min(r.L,ps+v*dt);P.x=q[0];P.z=q[1];}}P.vx=P.vz=0;
      var f=SUBS.filter(function(x){return /^Dona Marlene/.test(x.el.textContent);})[0];
      mercTick(dt);casinhaTick();update(dt);t+=dt;fr++;
      if(f&&SUBS.indexOf(f)<0&&S.time<f.exp-.15&&c.stage===stage)cort.push(f.el.textContent.slice(0,40));
      var j=dist2(last[0],last[1],m.x,m.z);jump=Math.max(jump,j);last=[m.x,m.z];
      var pos={x:m.x,z:m.z};pushCircle(pos,.3,COL);tr(dist2(pos.x,pos.z,m.x,m.z)<.05,'Marlene dentro da parede '+m.x.toFixed(1)+','+m.z.toFixed(1));tr(S.phase!=='ui','ocorrencia na escolta');
      var dp=rotaAt(r,rotaProj(r,P.x,P.z,0,r.L));if((m.x-P.x)*dp[2]+(m.z-P.z)*dp[3]>0)ahead++;else if(fr%10===0&&reg.length<40){/* registrador (Gabinete 10/11 01h35): toda vez que ela fica atras, guarda onde estava e o que tinha por perto; sai na mensagem da falha */var nd=99,np=99,nn='';TRAF.forEach(function(o){if(o.x!=null)nd=Math.min(nd,dist2(o.x,o.z,m.x,m.z));});NPCS.forEach(function(o){if(o===m||!o.m||!o.m.visible)return;var d=dist2(o.x,o.z,m.x,m.z);if(d<np){np=d;nn=o.id||o.nome||o.k||'';}});reg.push([+t.toFixed(1),+m.x.toFixed(1),+m.z.toFixed(1),+P.x.toFixed(1),+P.z.toFixed(1),c.det?c.det.length:0,+(c.preso||0).toFixed(1),+nd.toFixed(1),+np.toFixed(1),nn].join(','));}}
    return {t:t,ahead:ahead/Math.max(1,fr),jump:jump,cort:cort,reg:reg};}
