  /* Fuzz deterministico: o mesmo retorno para todos os passos, todos os raios,
     mercadinho, veiculos, arma e cancelamento. Os avancos abaixo sao os do jogo. */
  var QUEST_PASSOS=['cena','marlene','ocupada','baile','bigode','galpao','fimbaile','dentro','teto','tiroteio','descer','levar','twist','decisao','fuga','topo34','soco34','fugacarro','rendido','casa','entregar','porta','abriu','entra','filho','fim','livre','cap3','f_vit','f_test','f_fare','f_quiz','f_fim'];
  function questFuzz(){
    var key=questKey(),ck=QUEST_CK,actor=NPCBY.marlene,ax=actor.x,az=actor.z;
    var places=questZones().map(function(z){return [z[0],z[1]];}).concat([[13,45],[0,92],[-5.7,35]]);
    places.forEach(function(p){
      P.x=p[0];P.z=p[1];P.y=surfaceY(P.x,P.z);P.alt=0;CB.hp=0;sbxDie(true);
      // Chega aqui tanto pelo retry do jornal quanto pelo simulado perdido.
      sbxRespawn(false);eq(CB.hp,100,'vida '+key);eq(questKey(),key,'passo '+key);
      eq(actor.x,ax,'ator x '+key);eq(actor.z,az,'ator z '+key);
      tr(questSafePoint(P,questZones()),'retorno em gatilho/parede '+key+' '+P.x+','+P.z+','+P.y);
      tr(!S.soco&&!QZ&&!lifeActive(),'minigame aberto '+key);
      tr(SEQ.done===ck.records.filter(function(r){return r.o===SEQ;})[0].v.done,'callback perdido '+key);
    });
    questRestore();
  }
  QUEST_PASSOS.forEach(function(st){T('LICAO 08/11 fuzz snapshot: '+st,function(){
    fresh();exitCar(true);clearSubs();S.step=st;S.phase='play';P.x=-5.7;P.z=35;P.y=surfaceY(P.x,P.z);P.alt=0;
    // Perturbacoes antes da morte, nunca substituem o estado que sera retomado.
    questCapture(true);var ck=QUEST_CK;
    enterCar();exitCar(true);draw(true);draw(false);questRestore();
    tr(quizRun({n:3,dif:'facil',tempo:18,titulo:'Teste',tema:'vigia'}),'abrir '+st);tr(quizCancela(),'cancelar '+st);
    eq(S.step,st,'cancelar alterou passo');questRestore();questFuzz();tr(QUEST_CK===ck,'snapshot trocado');fresh();
  });});
