var LMUS={timer:0,alvo:0};
function lmusTick(){var a=$('lmus');if(!a)return;var v=a._som?a._som.v:0;
  v=LMUS.alvo>v?Math.min(LMUS.alvo,v+.05):Math.max(LMUS.alvo,v-.05);somMediaVol(a,v);
  if(v===LMUS.alvo){clearInterval(LMUS.timer);LMUS.timer=0;if(!v)a.pause();}
}
function lmusFade(alvo){clearInterval(LMUS.timer);LMUS.alvo=alvo;LMUS.timer=setInterval(lmusTick,40);}
