  if(AC&&AU.unlocked){var p=AC.resume();if(p&&p.catch)p.catch(function(){});}
  if(!a.paused&&LMUS.alvo===.55)return;
  somMedia(a,'mus',a.paused?0:(a._som?a._som.v:0));lmusFade(.55);
  try{var q=a.play();if(q&&q.catch)q.catch(function(){});}catch(e){}
