  if(LOADW&&now-LOADW>350){if(!LOADGO.preparado&&now-LOADGO.inicio<2100&&(!SQV.ready||AC&&!AUDIO_EMBED['car-door']))return true;if(!LOADENTRA){LOADENTRA=true;return true;}loadEntra();return true;}
